INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22094, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "为建筑打下稳固的地基或基石，使之后的施工能够开始。", "primary_collocate": null, "pronunciation": "diàn dìng", "ipa": "tjɛn˥˩ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "工人们先奠定地基，再盖楼。", "target_word": "奠定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要先把基础奠定好，房子才不会倒。", "target_word": "奠定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们花了一个月奠定桥的基础。", "target_word": "奠定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地基奠定了，下个月就能建房。", "target_word": "奠定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "师傅正在奠定新厂房的基石。", "target_word": "奠定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "基础没有奠定好，后面的工作很难做。", "target_word": "奠定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先奠定好第一块基石，工人才开始盖墙。", "target_word": "奠定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地基要奠定得牢，房子才结实。", "target_word": "奠定", "complexity_tier": "T3", "furigana": "dì jī yào diàn dìng de láo, fáng zi cái jiē shi", "sentence_source": "generated"}, {"text": "工人们在山边奠定了房屋的地基。", "target_word": "奠定", "complexity_tier": "T3", "furigana": "gōng rén men zài shān biān diàn dìng le fáng wū de dì jī", "sentence_source": "generated"}, {"text": "村里人一起奠定了新桥的基石。", "target_word": "奠定", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "奠定了", "label": "体标"}, {"form": "奠定过", "label": "体标"}], "register": "书面", "sense_fingerprint": "先把地基或基石放稳，之后才能继续施工", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfd5ce0b-25db-4a50-9d7c-c2c7f75df794') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22094, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "奠定", "is_correct": true, "explanation": "正确：奠定（diàn dìng）指先把地基或基石放稳，为之后的施工做准备。"}, {"text": "淡定", "is_correct": false, "explanation": "dàn（第四声）与 diàn 的第一音节只差介音 i（ian 与 an），淡定指镇定、从容，与放稳地基无关。"}, {"text": "电动", "is_correct": false, "explanation": "第二音节韵母 ong 与 ing 不同（dòng 与 dìng），电动指靠电力驱动，与放稳地基无关。"}, {"text": "限定", "is_correct": false, "explanation": "第一音节声母 x 与 d 不同（xiàn 与 diàn），限定指规定在一定范围内，与放稳地基无关。"}], "explanations": {"奠定": "正确：奠定（diàn dìng）指先把地基或基石放稳，为之后的施工做准备。", "淡定": "dàn（第四声）与 diàn 的第一音节只差介音 i（ian 与 an），淡定指镇定、从容，与放稳地基无关。", "电动": "第二音节韵母 ong 与 ing 不同（dòng 与 dìng），电动指靠电力驱动，与放稳地基无关。", "限定": "第一音节声母 x 与 d 不同（xiàn 与 diàn），限定指规定在一定范围内，与放稳地基无关。"}, "sentence_index": null, "correct_answer": "奠定"}, "level_3": {"options": [{"text": "摘", "is_correct": false, "explanation": "搭配：“摘”用于果实、花朵，不能接“地基”。"}, {"text": "熄灭", "is_correct": false, "explanation": "语义：“熄灭”针对火、光，用在“地基”上句子不通，与放稳地基的意思无关。"}, {"text": "分享", "is_correct": false, "explanation": "搭配：“分享”接经验、快乐等，不接“地基”。"}, {"text": "奠定", "is_correct": true, "explanation": "正确：“奠定地基”指先把地基放稳，符合句意。"}], "explanations": {"摘": "搭配：“摘”用于果实、花朵，不能接“地基”。", "熄灭": "语义：“熄灭”针对火、光，用在“地基”上句子不通，与放稳地基的意思无关。", "分享": "搭配：“分享”接经验、快乐等，不接“地基”。", "奠定": "正确：“奠定地基”指先把地基放稳，符合句意。"}, "sentence_index": 0, "correct_answer": "奠定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人们奠定了一条新的水管。", "explanation": "这里应该用〈铺设〉。奠定用于地基、基石，不用于水管等管道；铺设水管、线路要用铺设。"}, {"text": "师傅奠定了新的大门。", "explanation": "这里应该用〈安装〉。奠定指打下地基，不用于装门窗等成品；装门要说安装。"}, {"text": "他们奠定了一个舞台。", "explanation": "这里应该用〈搭建〉。奠定指打下地基，不用于搭起舞台等临时结构；搭舞台要用搭建。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ecb297-d7dd-4b53-90b2-e9becbfbfd7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22094, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "奠定", "is_correct": true, "explanation": "正确：奠定（diàn dìng）指先把地基或基石放稳，为之后的施工做准备。"}, {"text": "电令", "is_correct": false, "explanation": "第二音节声母 l 与 d 不同（lìng 与 dìng），电令指以电报发出的命令。"}, {"text": "电镜", "is_correct": false, "explanation": "第二音节声母 j 与 d 不同（jìng 与 dìng），电镜指电子显微镜。"}, {"text": "电性", "is_correct": false, "explanation": "第二音节声母 x 与 d 不同（xìng 与 dìng），电性指与电有关的性质。"}], "explanations": {"奠定": "正确：奠定（diàn dìng）指先把地基或基石放稳，为之后的施工做准备。", "电令": "第二音节声母 l 与 d 不同（lìng 与 dìng），电令指以电报发出的命令。", "电镜": "第二音节声母 j 与 d 不同（jìng 与 dìng），电镜指电子显微镜。", "电性": "第二音节声母 x 与 d 不同（xìng 与 dìng），电性指与电有关的性质。"}, "sentence_index": null, "correct_answer": "奠定"}, "level_3": {"options": [{"text": "拆", "is_correct": false, "explanation": "语义：“拆”是拆掉，与“先放稳基石才盖墙”的顺序相反。"}, {"text": "砸", "is_correct": false, "explanation": "语义：“砸”会把基石弄坏，与“先打好基础”的意思相矛盾。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”接食物，不能接“基石”。"}, {"text": "奠定", "is_correct": true, "explanation": "正确：“奠定好基石”指先把第一块基石放稳，符合句意。"}], "explanations": {"拆": "语义：“拆”是拆掉，与“先放稳基石才盖墙”的顺序相反。", "砸": "语义：“砸”会把基石弄坏，与“先打好基础”的意思相矛盾。", "煮": "搭配：“煮”接食物，不能接“基石”。", "奠定": "正确：“奠定好基石”指先把第一块基石放稳，符合句意。"}, "sentence_index": 6, "correct_answer": "奠定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人们奠定了一根电线杆。", "explanation": "这里应该用〈竖立〉。奠定指打下基础，不用于立起电线杆这类竖立物；立电线杆要说竖立。"}, {"text": "工人们奠定了一座小房子。", "explanation": "这里应该用〈建造〉。奠定只指打地基、放基石这一步，不指完成整座房子；建房子要说建造。"}, {"text": "工人们奠定了一个大坑。", "explanation": "这里应该用〈挖掘〉。奠定指打下基础，不用于挖坑；挖坑要说挖掘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ecb297-d7dd-4b53-90b2-e9becbfbfd7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22094, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个工人把地基奠定很牢。", "corrected_sentence": "这个工人把地基奠定得很牢。", "error_description": "错误：程度补语“很牢”前漏掉了“得”，写成了“奠定很牢”。应写作“奠定得很牢”，“得”用来连接动词和补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ecb297-d7dd-4b53-90b2-e9becbfbfd7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22094, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们把地基奠定了好，才开始盖楼。", "corrected_sentence": "工人们把地基奠定好了，才开始盖楼。", "error_description": "错误：结果补语“好”应紧接动词，“了”应放在补语之后。“奠定了好”是错的，应写作“奠定好了”，即“奠定”后接补语“好”，再接“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ecb297-d7dd-4b53-90b2-e9becbfbfd7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
