INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22104, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用脑子想事情，比如看书、算数。", "primary_collocate": null, "pronunciation": "zhì lì huó dòng", "ipa": "ʈʂɻ̩˥˩ li˥˩ xuɔ˧˥ tʊŋ˥˩", "syllable_count": 4, "sentences": [{"text": "看书是一种智力活动。", "target_word": "智力活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "算数也是智力活动。", "target_word": "智力活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子玩拼图，也是一种智力活动。", "target_word": "智力活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷每天看书、下棋，都是智力活动。", "target_word": "智力活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个小时的智力活动让我觉得很累。", "target_word": "智力活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你喜欢体育活动，还是智力活动？", "target_word": "智力活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "算数和猜谜都是有趣的智力活动。", "target_word": "智力活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，孩子每天都要有一些智力活动。", "target_word": "智力活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打球是体力活动，看书是智力活动。", "target_word": "智力活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师推荐我们多做一些智力活动，比如猜谜和算数。", "target_word": "智力活动", "complexity_tier": "T3", "furigana": "zhì lì huó dòng", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}], "register": "中性", "sense_fingerprint": "用脑子想事情，如看书、算数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16210783-d732-40a2-80fa-3855ab679b2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22104, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "智力活动", "is_correct": true, "explanation": "正确。“看书”是用脑子想事情的活动，属于智力活动。"}, {"text": "体育运动", "is_correct": false, "explanation": "语义：看书是安静的阅读，不是体育运动。"}, {"text": "家务劳动", "is_correct": false, "explanation": "语义：看书不是做家务，家务劳动指打扫、做饭等日常劳作。"}, {"text": "园艺", "is_correct": false, "explanation": "语义：园艺指照料植物，看书是阅读，不是园艺。"}], "explanations": {"智力活动": "正确。“看书”是用脑子想事情的活动，属于智力活动。", "体育运动": "语义：看书是安静的阅读，不是体育运动。", "家务劳动": "语义：看书不是做家务，家务劳动指打扫、做饭等日常劳作。", "园艺": "语义：园艺指照料植物，看书是阅读，不是园艺。"}, "sentence_index": 0, "correct_answer": "智力活动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爷爷每天散步、打太极，都是智力活动。", "explanation": "这里应该用〈体力活动〉。散步、打太极是身体运动，不是用脑子想事情。"}, {"text": "周末我们和朋友聚会，做了很多智力活动。", "explanation": "这里应该用〈社交活动〉。与朋友聚会属于社交，不是用脑子想事情的活动。"}, {"text": "我们去海边晒太阳、吃冰淇淋，这也算智力活动。", "explanation": "这里应该用〈休闲放松〉。智力活动指用脑子想事情，晒太阳、吃冰淇淋是放松享受，不需要动脑思考。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b56b74d8-f574-424d-9635-f728518e07a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22104, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "智力活动", "is_correct": true, "explanation": "正确。算数和猜谜都需要动脑思考，属于智力活动。"}, {"text": "体力活动", "is_correct": false, "explanation": "语义：算数和猜谜是动脑的活动，不是体力活动。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪是做饭，与算数、猜谜毫无关系。"}, {"text": "手工艺", "is_correct": false, "explanation": "搭配：“有趣的手工艺”指动手制作的物件，不能用来形容算数和猜谜。"}], "explanations": {"智力活动": "正确。算数和猜谜都需要动脑思考，属于智力活动。", "体力活动": "语义：算数和猜谜是动脑的活动，不是体力活动。", "烹饪": "语义：烹饪是做饭，与算数、猜谜毫无关系。", "手工艺": "搭配：“有趣的手工艺”指动手制作的物件，不能用来形容算数和猜谜。"}, "sentence_index": 6, "correct_answer": "智力活动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的智力活动很高，做题很快。", "explanation": "这里应该用〈智力水平〉。“高”形容水平，智力活动指思考的过程，不能说高低。"}, {"text": "周末我们看电影、唱歌，都是智力活动。", "explanation": "这里应该用〈娱乐活动〉。看电影、唱歌是娱乐，不是用脑子想事情。"}, {"text": "我们去公园游览，这些都是智力活动。", "explanation": "这里应该用〈休闲活动〉。游览是放松的活动，不是用脑子想事情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b56b74d8-f574-424d-9635-f728518e07a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22104, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子每天都做一只智力活动，比如拼图。", "corrected_sentence": "孩子每天都做一项智力活动，比如拼图。", "error_description": "量词错误：“智力活动”应用量词“项”，不能用“只”。正确形式为“一项智力活动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b56b74d8-f574-424d-9635-f728518e07a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22104, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师说，孩子每天都要吃一项智力活动。", "corrected_sentence": "老师说，孩子每天都要做一项智力活动。", "error_description": "搭配错误：“智力活动”应与动词“做”搭配，不能说“吃”。正确形式为“做一项智力活动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b56b74d8-f574-424d-9635-f728518e07a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
