INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22106, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "读完文章后，仔细想里面的字用得好不好。", "primary_collocate": null, "pronunciation": "tuī qiāo", "ipa": "tʰuei˥ tɕʰiɑu˥", "syllable_count": 2, "sentences": [{"text": "读完这首诗，他开始推敲里面的每个字。", "target_word": "推敲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们推敲这句话里的用字。", "target_word": "推敲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看完文章，我推敲了一下题目里的那个字。", "target_word": "推敲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读完短文，开始推敲作者的用词好不好。", "target_word": "推敲", "complexity_tier": "T3", "furigana": "tā dú wán duǎn wén kāi shǐ tuī qiāo zuò zhě de yòng cí hǎo bù hǎo", "sentence_source": "generated"}, {"text": "这个“绿”字用得妙，值得推敲。", "target_word": "推敲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读完小说，她推敲了作者用的几个词。", "target_word": "推敲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们读完课文，一起推敲文中的用词。", "target_word": "推敲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人读诗，爱推敲每个字的用法。", "target_word": "推敲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读完这篇作文，老师推敲了几个词。", "target_word": "推敲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我读完文章，又推敲了一遍用字。", "target_word": "推敲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "推敲了", "label": "完成体"}, {"form": "推敲过", "label": "经历体"}, {"form": "推敲推敲", "label": "重叠"}], "register": "中性", "sense_fingerprint": "读完文章后细想字词用得好不好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16210783-d732-40a2-80fa-3855ab679b2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22106, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "推敲", "is_correct": true, "explanation": "推敲：细想字词用得好不好，与“每个字”的语境相符。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是液体，不能说“喝每个字”。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”指燃烧，与读诗、看字的动作无关。"}, {"text": "寄", "is_correct": false, "explanation": "语义：“寄”指邮寄，与读诗无关。"}], "explanations": {"推敲": "推敲：细想字词用得好不好，与“每个字”的语境相符。", "喝": "搭配：“喝”的对象是液体，不能说“喝每个字”。", "烧": "语义：“烧”指燃烧，与读诗、看字的动作无关。", "寄": "语义：“寄”指邮寄，与读诗无关。"}, "sentence_index": 0, "correct_answer": "推敲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这首诗推敲成英文。", "explanation": "这里应该用〈翻译〉。推敲指细想字词用得好不好，把诗译成外文要用翻译。"}, {"text": "这家书店很值得推敲给朋友。", "explanation": "这里应该用〈推荐〉。推敲指细想字词用得好不好，把书店介绍给朋友要用推荐。"}, {"text": "他推敲了一壶水。", "explanation": "这里应该用〈烧〉。推敲指细想字词用得好不好，烧水要用烧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b56b74d8-f574-424d-9635-f728518e07a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22106, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "推敲", "is_correct": true, "explanation": "推敲：细想课文中的用词好不好，与句意相符。"}, {"text": "点燃", "is_correct": false, "explanation": "搭配：“点燃”接的是火、希望等，不能说“点燃用词”。"}, {"text": "搬", "is_correct": false, "explanation": "语义：“搬”是移动实物，与文字用词无关。"}, {"text": "冻", "is_correct": false, "explanation": "语义：“冻”指降温变硬，与读课文的动作无关。"}], "explanations": {"推敲": "推敲：细想课文中的用词好不好，与句意相符。", "点燃": "搭配：“点燃”接的是火、希望等，不能说“点燃用词”。", "搬": "语义：“搬”是移动实物，与文字用词无关。", "冻": "语义：“冻”指降温变硬，与读课文的动作无关。"}, "sentence_index": 6, "correct_answer": "推敲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地震把那座旧墙推敲了。", "explanation": "这里应该用〈推倒〉。推敲指细想字词用得好不好，把墙弄倒要用推倒。"}, {"text": "爸爸推敲着轮椅走进了医院。", "explanation": "这里应该用〈推〉。推敲不能表示推动物体，推轮椅要用推。"}, {"text": "两个孩子互相推敲。", "explanation": "这里应该用〈推搡〉。推敲指细想字词用得好不好，孩子之间互相推来推去要用推搡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b56b74d8-f574-424d-9635-f728518e07a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22106, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她读完文章，推敲地很仔细。", "corrected_sentence": "她读完文章，推敲得很仔细。", "error_description": "结构错误：推敲的补语结构要用“得”，不能用“地”。应说“推敲得很仔细”，“推敲地很仔细”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b56b74d8-f574-424d-9635-f728518e07a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22106, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从来不推敲过这首诗的用字。", "corrected_sentence": "我从来没推敲过这首诗的用字。", "error_description": "错误在于否定词用了“不”。表示“从来没有过某种经历”要用“没”，应说“从来没推敲过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b56b74d8-f574-424d-9635-f728518e07a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
