INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22108, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "说话时把声音压得很低、很小。", "primary_collocate": null, "pronunciation": "dī yīn", "ipa": "ti˥ in˥", "syllable_count": 2, "sentences": [{"text": "他用低音在我耳边说话。", "target_word": "低音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子睡了，妈妈用低音讲电话。", "target_word": "低音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说：请大家用低音讨论。", "target_word": "低音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆里请用低音说话。", "target_word": "低音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他低着头，用低音说了声对不起。", "target_word": "低音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在电影院里，她用低音问我几点了。", "target_word": "低音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用低音对病人说了几句话。", "target_word": "低音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了不吵醒宝宝，我们都用低音交谈。", "target_word": "低音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他太紧张，只能用低音回答。", "target_word": "低音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时，小李用低音和我商量。", "target_word": "低音", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "低音部", "label": "复合"}, {"form": "低音提琴", "label": "复合"}], "register": "通用", "sense_fingerprint": "说话时压低的、很小的声音", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3313a1a0-cc7f-4011-8962-bd3ab5d2c9e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22108, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "低音", "is_correct": true, "explanation": "指说话时压得很低的声音，与「在我耳边」的语境相符。"}, {"text": "高音", "is_correct": false, "explanation": "语义：高音指音调高，与在耳边轻声说话的语境相反。"}, {"text": "音箱", "is_correct": false, "explanation": "语义：音箱是播放设备，不是说话的方式。"}, {"text": "音调", "is_correct": false, "explanation": "搭配：「用音调说话」不成立，音调说高低，不表示说话的声量。"}], "explanations": {"低音": "指说话时压得很低的声音，与「在我耳边」的语境相符。", "高音": "语义：高音指音调高，与在耳边轻声说话的语境相反。", "音箱": "语义：音箱是播放设备，不是说话的方式。", "音调": "搭配：「用音调说话」不成立，音调说高低，不表示说话的声量。"}, "sentence_index": 0, "correct_answer": "低音"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在操场上用低音大声喊我的名字。", "explanation": "这里的低音指压低的声音，与「大声」矛盾，应说〈高声〉。"}, {"text": "他在台上用低音唱了一首高亢的歌。", "explanation": "低音指压低、低沉的声音，与「高亢」矛盾，两者不能描述同一种声音。"}, {"text": "图书馆里请用一只低音说话。", "explanation": "量词错误：「只」用于动物等，声音不能用「只」计量，这里应去掉量词，直接说「用低音」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3aee74ca-cee8-48a7-a1f0-2caa03801e6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22108, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "低音", "is_correct": true, "explanation": "指说话时压低的声音，与「对病人说几句话」的语境相符。"}, {"text": "手势", "is_correct": false, "explanation": "语义：手势不是声音，不能用来说话。"}, {"text": "耳机", "is_correct": false, "explanation": "语义：耳机是听的设备，不能作为对病人说话的方式。"}, {"text": "背景音乐", "is_correct": false, "explanation": "语义：背景音乐是播放的声音，不是医生说话的方式。"}], "explanations": {"低音": "指说话时压低的声音，与「对病人说几句话」的语境相符。", "手势": "语义：手势不是声音，不能用来说话。", "耳机": "语义：耳机是听的设备，不能作为对病人说话的方式。", "背景音乐": "语义：背景音乐是播放的声音，不是医生说话的方式。"}, "sentence_index": 6, "correct_answer": "低音"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "开会时，小李用低音大声地和我争论。", "explanation": "这里的低音指压低的声音，与「大声地」矛盾，应去掉「大声地」。"}, {"text": "开会时，小李拿一把低音和我商量。", "explanation": "量词错误：「把」用于有柄的器物，声音不能用它计量，这里应直接说「用低音」。"}, {"text": "开会时，小李用一条低音和我商量。", "explanation": "量词错误：「条」用于细长的东西，声音不能用它计量，这里应直接说「用低音」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3aee74ca-cee8-48a7-a1f0-2caa03801e6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22108, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她用一只低音在我耳边叮嘱了一句。", "corrected_sentence": "她用低音在我耳边叮嘱了一句。", "error_description": "量词错误：「一只」用于动物，不能用于说话的声音，此处应去掉「一只」，直接说「用低音」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3aee74ca-cee8-48a7-a1f0-2caa03801e6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22108, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "开会时，小李用一只低音和我商量了一下。", "corrected_sentence": "开会时，小李用低音和我商量了一下。", "error_description": "量词错误：「一只」用于动物，说话的声音不能用「只」计量，此处应直接说「用低音」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3aee74ca-cee8-48a7-a1f0-2caa03801e6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
