INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22110, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "巴洛克是一种有很多装饰的艺术风格。", "primary_collocate": null, "pronunciation": "bā luò kè", "ipa": "pa˥ luɔ˥˩ kʰɤ˥˩", "syllable_count": 3, "sentences": [{"text": "巴洛克是一种有很多装饰的艺术风格。", "target_word": "巴洛克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座巴洛克教堂里到处都是金色的装饰。", "target_word": "巴洛克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢巴洛克，不喜欢简单的风格。", "target_word": "巴洛克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "巴洛克的房子看起来很华丽。", "target_word": "巴洛克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了一张巴洛克建筑的照片。", "target_word": "巴洛克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的桌椅是巴洛克风格的，有很多花纹。", "target_word": "巴洛克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对巴洛克很感兴趣，想去欧洲看看。", "target_word": "巴洛克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "巴洛克音乐和巴洛克画都很有名。", "target_word": "巴洛克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把家里布置成了巴洛克风格。", "target_word": "巴洛克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有一幅巴洛克时代的画。", "target_word": "巴洛克", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "巴洛克式", "label": "复合"}, {"form": "巴洛克风格", "label": "复合"}], "register": "中性", "sense_fingerprint": "装饰很多的艺术风格", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16210783-d732-40a2-80fa-3855ab679b2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22110, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "巴洛克", "is_correct": true, "explanation": "正确。巴洛克是一种有很多装饰的艺术风格，与句子描述相合。"}, {"text": "极简主义", "is_correct": false, "explanation": "语义：极简主义去除多余装饰，与“有很多装饰”正好相反。"}, {"text": "包豪斯", "is_correct": false, "explanation": "语义：包豪斯强调功能、反对繁复装饰，与“有很多装饰”矛盾。"}, {"text": "禅意", "is_correct": false, "explanation": "搭配：“禅意”是一种意境，不是艺术风格，不能与“艺术风格”这样搭配。"}], "explanations": {"巴洛克": "正确。巴洛克是一种有很多装饰的艺术风格，与句子描述相合。", "极简主义": "语义：极简主义去除多余装饰，与“有很多装饰”正好相反。", "包豪斯": "语义：包豪斯强调功能、反对繁复装饰，与“有很多装饰”矛盾。", "禅意": "搭配：“禅意”是一种意境，不是艺术风格，不能与“艺术风格”这样搭配。"}, "sentence_index": 0, "correct_answer": "巴洛克"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这栋房子的风格是巴洛克的，没有多余的装饰。", "explanation": "这里应该用〈简约风格〉。巴洛克以繁复装饰为特点，与“没有多余的装饰”相反。"}, {"text": "这间客厅装修得很巴洛克，墙面光秃秃的，什么装饰都没有。", "explanation": "这里应该用〈简朴〉。巴洛克指装饰繁多的风格，“什么装饰都没有”的客厅不能这样形容。"}, {"text": "这幅画是巴洛克的，看不出具体的形象。", "explanation": "这里应该用〈抽象主义〉。巴洛克绘画人物形象具体、戏剧性强，不能说看不出具体形象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b56b74d8-f574-424d-9635-f728518e07a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22110, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "巴洛克", "is_correct": true, "explanation": "正确。“我对巴洛克很感兴趣，想去欧洲看看”指对欧洲艺术风格的兴趣，与句意相合。"}, {"text": "噪音", "is_correct": false, "explanation": "语义：一般不会对噪音感兴趣，与“很感兴趣”的语境不符。"}, {"text": "雾霾", "is_correct": false, "explanation": "语义：雾霾是环境问题，与“想去欧洲看看”的兴趣语境不协调。"}, {"text": "垃圾", "is_correct": false, "explanation": "搭配：“感兴趣”通常搭配可以欣赏、研究的对象，“垃圾”不能这样搭配。"}], "explanations": {"巴洛克": "正确。“我对巴洛克很感兴趣，想去欧洲看看”指对欧洲艺术风格的兴趣，与句意相合。", "噪音": "语义：一般不会对噪音感兴趣，与“很感兴趣”的语境不符。", "雾霾": "语义：雾霾是环境问题，与“想去欧洲看看”的兴趣语境不协调。", "垃圾": "搭配：“感兴趣”通常搭配可以欣赏、研究的对象，“垃圾”不能这样搭配。"}, "sentence_index": 6, "correct_answer": "巴洛克"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家咖啡馆的装修是巴洛克风格，屋里很素净。", "explanation": "这里应该用〈日式风格〉。日式风格讲究素净，巴洛克以繁复华丽著称，与“很素净”矛盾。"}, {"text": "这栋楼是巴洛克建筑，线条很简单。", "explanation": "这里应该用〈现代主义〉。现代主义以线条简单为特点，巴洛克以繁复装饰为特点。"}, {"text": "这幅巴洛克画线条简练，留白很多。", "explanation": "这里应该用〈水墨画〉。水墨画讲究留白，巴洛克绘画画面饱满，不能这样形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b56b74d8-f574-424d-9635-f728518e07a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22110, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座老宅的墙上雕满了花纹，属于一只巴洛克风格。", "corrected_sentence": "这座老宅的墙上雕满了花纹，属于一种巴洛克风格。", "error_description": "量词错误：“巴洛克风格”应用量词“种”，“只”不能用于风格。正确形式为“一种巴洛克风格”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b56b74d8-f574-424d-9635-f728518e07a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22110, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位画家是一本巴洛克时代的重要人物。", "corrected_sentence": "这位画家是一位巴洛克时代的重要人物。", "error_description": "量词错误：“人物”指人，应用人的量词“位”，不能用“本”。正确形式为“一位巴洛克时代的重要人物”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b56b74d8-f574-424d-9635-f728518e07a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
