INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22122, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情发展的方向或变化的样子。", "primary_collocate": null, "pronunciation": "qū xiàng", "ipa": "tɕʰy˥ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "孩子们的阅读趋向和以前不一样了。", "target_word": "趋向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看一看天气的趋向，再决定去不去爬山。", "target_word": "趋向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校想知道学生选课的趋向。", "target_word": "趋向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻里说，明年的就业趋向不太乐观。", "target_word": "趋向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的发展趋向是越来越绿色。", "target_word": "趋向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板很关心市场价格的趋向。", "target_word": "趋向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天记录股票的趋向。", "target_word": "趋向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图表清楚地显示了销售的趋向。", "target_word": "趋向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家正在研究气候变化的趋向。", "target_word": "趋向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在大家的饮食趋向更健康了。", "target_word": "趋向", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "趨向", "label": "繁体"}, {"form": "趋向性", "label": "复合"}, {"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "趋向|名词|事情发展的方向或变化的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30f964d1-cfc8-4ab7-9f81-00f306f69457') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22122, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "趋向", "is_correct": true, "explanation": "正确：“趋向”指阅读变化的方向或样子，与“和以前不一样了”相合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：阅读没有颜色，“阅读颜色”与“不一样了”的变化说法不相关。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指人体的高矮，与阅读的变化无关。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“阅读”不与“价格”搭配，“阅读价格”不能表达阅读的变化。"}], "explanations": {"趋向": "正确：“趋向”指阅读变化的方向或样子，与“和以前不一样了”相合。", "颜色": "语义：阅读没有颜色，“阅读颜色”与“不一样了”的变化说法不相关。", "身高": "语义：“身高”指人体的高矮，与阅读的变化无关。", "价格": "搭配：“阅读”不与“价格”搭配，“阅读价格”不能表达阅读的变化。"}, "sentence_index": 0, "correct_answer": "趋向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他朝着车站的趋向跑去。", "explanation": "这里应该用〈方向〉。“趋向”指事情发展的走向或样子，不指跑步时的具体方向。"}, {"text": "这台电脑很快，用起来很方便。", "explanation": "这里应该用〈快〉。“趋向”不能用来形容物体的快慢，形容快要说快。"}, {"text": "侦探很趋向，案子破得很快。", "explanation": "这里应该用〈聪明〉。“趋向”不能用来形容人的才智，形容人的才智要用聪明。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc597bcd-5819-488a-bfc6-a09fdb9ef0d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22122, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "趋向", "is_correct": true, "explanation": "正确：“趋向”指股票变化的方向，与“记录股票的”相合。"}, {"text": "面积", "is_correct": false, "explanation": "语义：股票没有面积，“面积”与股票的变化情况不相关。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“体积”指物体占的空间，股票不能说有体积。"}, {"text": "温度", "is_correct": false, "explanation": "语义：股票不讲温度，“温度”无法作为股票变化情况被记录。"}], "explanations": {"趋向": "正确：“趋向”指股票变化的方向，与“记录股票的”相合。", "面积": "语义：股票没有面积，“面积”与股票的变化情况不相关。", "体积": "搭配：“体积”指物体占的空间，股票不能说有体积。", "温度": "语义：股票不讲温度，“温度”无法作为股票变化情况被记录。"}, "sentence_index": 6, "correct_answer": "趋向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的精神趋向很好。", "explanation": "这里应该用〈状态〉。“趋向”指事情发展的方向或变化的样子，人的精神情况要用“状态”。"}, {"text": "他的说话很温和，大家都爱听。", "explanation": "这里应该用〈温和〉。“趋向”不能用来形容说话的语气，形容语气要用温和。"}, {"text": "他待人很热情，大家都爱找他。", "explanation": "这里应该用〈热情〉。“趋向”不能用来形容待人的态度，形容态度要用热情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc597bcd-5819-488a-bfc6-a09fdb9ef0d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22122, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份计划预测了明年就业总体趋向。", "corrected_sentence": "这份计划预测了明年就业的总体趋向。", "error_description": "定语漏“的”：“明年就业”修饰“总体趋向”，中间应加“的”，应说“明年就业的总体趋向”，不能省去“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc597bcd-5819-488a-bfc6-a09fdb9ef0d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22122, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们看到了一根新的饮食趋向。", "corrected_sentence": "我们看到了一种新的饮食趋向。", "error_description": "量词错误：“趋向”是抽象名词，应该用量词“种”，不能用“根”；“根”多用于细长的物体。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc597bcd-5819-488a-bfc6-a09fdb9ef0d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22128, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "局部", "is_correct": true, "explanation": "“局部”与“全面”相对，指只涉及一部分，与“全面的检查”相对。"}, {"text": "详细", "is_correct": false, "explanation": "“详细”强调细致，与“全面”不构成反义关系。"}, {"text": "深刻", "is_correct": false, "explanation": "“深刻”强调程度深，与“全面”不构成反义关系。"}, {"text": "精确", "is_correct": false, "explanation": "“精确”强调准确无误，与“全面”不构成反义关系。"}], "correct_answer": "局部", "explanations": {"局部": "“局部”与“全面”相对，指只涉及一部分，与“全面的检查”相对。", "详细": "“详细”强调细致，与“全面”不构成反义关系。", "深刻": "“深刻”强调程度深，与“全面”不构成反义关系。", "精确": "“精确”强调准确无误，与“全面”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22128, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "片面", "is_correct": true, "explanation": "“片面”指只看一部分，与“知识很全面”相对。"}, {"text": "深入", "is_correct": false, "explanation": "“深入”强调程度深，与“全面”不构成反义关系。"}, {"text": "渊博", "is_correct": false, "explanation": "“渊博”与“全面”意思相近，不是反义关系。"}, {"text": "丰富", "is_correct": false, "explanation": "“丰富”指种类多、数量大，与“全面”不构成反义关系。"}], "correct_answer": "片面", "explanations": {"片面": "“片面”指只看一部分，与“知识很全面”相对。", "深入": "“深入”强调程度深，与“全面”不构成反义关系。", "渊博": "“渊博”与“全面”意思相近，不是反义关系。", "丰富": "“丰富”指种类多、数量大，与“全面”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22128, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "各个方面、各个部分都照顾到，没有遗漏。", "primary_collocate": null, "pronunciation": "quán miàn", "ipa": "tɕʰɥɛn³⁵ mjɛn⁵¹", "syllable_count": 2, "sentences": [{"text": "这份报告写得很全面。", "target_word": "全面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师全面检查了我的作业。", "target_word": "全面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这个问题的看法不全面。", "target_word": "全面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生给他做了全面的检查。", "target_word": "全面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要全面了解这里的情况。", "target_word": "全面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书全面地介绍了中国的历史。", "target_word": "全面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想得太不全面了。", "target_word": "全面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习要全面发展,不能只学数学。", "target_word": "全面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司对新工人进行了全面的训练。", "target_word": "全面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的知识很全面,什么都懂。", "target_word": "全面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "全面地", "label": "状语"}, {"form": "不全面", "label": "否定"}], "register": "中性", "sense_fingerprint": "各个方面都照顾到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fef3691-c05f-4979-b766-4af9a742d3ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22128, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全面", "is_correct": true, "explanation": "“全面”指各方面都照顾到，“这份报告写得很全面”成立。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，不能用来形容文章或报告。"}, {"text": "胖", "is_correct": false, "explanation": "语义：“胖”形容人或动物的体型，不能用来形容报告。"}, {"text": "咸", "is_correct": false, "explanation": "搭配：“咸”形容味道，不用来评价写作。"}], "explanations": {"全面": "“全面”指各方面都照顾到，“这份报告写得很全面”成立。", "甜": "搭配：“甜”形容味道，不能用来形容文章或报告。", "胖": "语义：“胖”形容人或动物的体型，不能用来形容报告。", "咸": "搭配：“咸”形容味道，不用来评价写作。"}, "sentence_index": 0, "correct_answer": "全面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "全面观众都站了起来。", "explanation": "这里应该用〈全场〉。整个场地的观众要用“全场”；“全面”指方面都顾到，不用于修饰观众。"}, {"text": "他个子很全面。", "explanation": "这里应该用〈高〉。形容身高要用“高”；“全面”指方面或范围都包括，不能形容身高。"}, {"text": "这件事全面是他的错。", "explanation": "这里应该用〈完全〉。表示彻底、毫无例外用“完全”；“全面”指方面，不能用于判断是非。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22128, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全面", "is_correct": true, "explanation": "“全面”指想问题周到、不遗漏，“你想得太不全面了”成立。"}, {"text": "高", "is_correct": false, "explanation": "语义：“高”形容高度，不能形容想法的周全程度。"}, {"text": "烫", "is_correct": false, "explanation": "语义：“烫”形容温度，不能形容想法。"}, {"text": "辣", "is_correct": false, "explanation": "搭配：“辣”形容味道，不用来形容想法。"}], "explanations": {"全面": "“全面”指想问题周到、不遗漏，“你想得太不全面了”成立。", "高": "语义：“高”形容高度，不能形容想法的周全程度。", "烫": "语义：“烫”形容温度，不能形容想法。", "辣": "搭配：“辣”形容味道，不用来形容想法。"}, "sentence_index": 6, "correct_answer": "全面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他全面都湿透了。", "explanation": "这里应该用〈全身〉。整个身体用“全身”；“全面”指方面都顾到，不指身体。"}, {"text": "他全面以赴地准备比赛。", "explanation": "这里应该用〈全力〉。用尽力气去做用“全力以赴”；“全面”指方面，不能说“全面以赴”。"}, {"text": "汽车全面前进。", "explanation": "这里应该用〈全速〉。速度最快用“全速”；“全面”不能形容速度或前进的快慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22128, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次调查太很全面。", "corrected_sentence": "这次调查很全面。", "error_description": "错误：程度副词“很”前多加了“太”，两个程度副词不能连用。正确应为“这次调查很全面”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22128, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师全面得讲解了这道题。", "corrected_sentence": "老师全面地讲解了这道题。", "error_description": "错误：修饰动词“讲解”的状语后应用“地”，不用“得”。“得”用于动词或形容词之后的补语。正确应为“全面地讲解”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
