INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22130, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "力气的大小。", "primary_collocate": null, "pronunciation": "lì dù", "ipa": "li˥˩ tu˥˩", "syllable_count": 2, "sentences": [{"text": "他推门的力度很大，门一下就开了。", "target_word": "力度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刷牙时力度别太大，会伤牙齿。", "target_word": "力度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈拍我肩膀的力度正合适。", "target_word": "力度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "踢球要控制好脚的力度。", "target_word": "力度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生按着我的腿，问我这个力度疼不疼。", "target_word": "力度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打字的力度太大，键盘会坏的。", "target_word": "力度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子抱小猫的力度要轻。", "target_word": "力度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用很小的力度拉开了窗帘。", "target_word": "力度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跳绳的时候，手腕的力度很重要。", "target_word": "力度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你再加一点力度，就能把石头推开了。", "target_word": "力度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "力度|名词|力气的大小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30f964d1-cfc8-4ab7-9f81-00f306f69457') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22130, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "力度", "is_correct": true, "explanation": "正确：“力度”指力气的大小，与“推门的……很大”相合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与推门用的力气无关，“推门的颜色很大”说不通。"}, {"text": "亮度", "is_correct": false, "explanation": "语义：“亮度”指光线的明暗，与推门的用力无关。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”指冷热程度，与推门用的力气无关，“推门的温度很大”说不通。"}], "explanations": {"力度": "正确：“力度”指力气的大小，与“推门的……很大”相合。", "颜色": "语义：“颜色”与推门用的力气无关，“推门的颜色很大”说不通。", "亮度": "语义：“亮度”指光线的明暗，与推门的用力无关。", "温度": "语义：“温度”指冷热程度，与推门用的力气无关，“推门的温度很大”说不通。"}, "sentence_index": 0, "correct_answer": "力度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天空气的力度很高。", "explanation": "这里应该用〈湿度〉。“力度”指力气的大小，不用来说空气的潮湿程度。"}, {"text": "这种食物能提供很多力度。", "explanation": "这里应该用〈能量〉。“力度”指力气的大小，不指食物中储存的能量。"}, {"text": "这幅画的力度很鲜艳。", "explanation": "这里应该用〈色彩〉。“力度”指力气的大小，不指颜色的鲜艳程度，画面的颜色要用“色彩”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc597bcd-5819-488a-bfc6-a09fdb9ef0d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22130, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "力度", "is_correct": true, "explanation": "正确：“力度”指力气的大小，与“小孩子抱小猫的……要轻”相合。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指人或动物的重量，与抱小猫时用力的大小不相关。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指岁数，与抱小猫时的用力情况无关。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：“速度”说快慢，不用“轻”形容，“速度要轻”不合。"}], "explanations": {"力度": "正确：“力度”指力气的大小，与“小孩子抱小猫的……要轻”相合。", "体重": "语义：“体重”指人或动物的重量，与抱小猫时用力的大小不相关。", "年龄": "语义：“年龄”指岁数，与抱小猫时的用力情况无关。", "速度": "搭配：“速度”说快慢，不用“轻”形容，“速度要轻”不合。"}, "sentence_index": 6, "correct_answer": "力度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯茶的力度很合适。", "explanation": "这里应该用〈温度〉。“力度”指力气的大小，不用来说饮品的冷热。"}, {"text": "这篇文章的力度很多。", "explanation": "这里应该用〈字数〉。“力度”指力气的大小，不用来说文字的数量。"}, {"text": "这件衣服的力度很好看。", "explanation": "这里应该用〈颜色〉。“力度”指力气的大小，不用来形容衣服的颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc597bcd-5819-488a-bfc6-a09fdb9ef0d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22130, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈用很轻地力度拍孩子的背。", "corrected_sentence": "妈妈用很轻的力度拍孩子的背。", "error_description": "结构错误：“很轻”修饰名词“力度”，要用“的”，不能用“地”；应说“很轻的力度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc597bcd-5819-488a-bfc6-a09fdb9ef0d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22130, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用一根力度把门推开了。", "corrected_sentence": "他用一点力度把门推开了。", "error_description": "量词错误：“力度”是抽象名词，应该用量词“点”，不能用“根”；“根”多用于细长的物体。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc597bcd-5819-488a-bfc6-a09fdb9ef0d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
