INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22132, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "浪漫主义是一种想法，觉得世界很美好，像童话故事一样。", "primary_collocate": null, "pronunciation": "làng màn zhǔ yì", "ipa": "lɑŋ˥˩ man˥˩ ʈʂu˨˩˦ i˥˩", "syllable_count": 4, "sentences": [{"text": "他身上有一种浪漫主义情怀，总觉得生活像童话。", "target_word": "浪漫主义", "complexity_tier": "T3", "furigana": "làng màn zhǔ yì", "sentence_source": "generated"}, {"text": "她的生活里总有一点浪漫主义色彩。", "target_word": "浪漫主义", "complexity_tier": "T3", "furigana": "làng màn zhǔ yì", "sentence_source": "generated"}, {"text": "他对未来怀着一份浪漫主义憧憬。", "target_word": "浪漫主义", "complexity_tier": "T3", "furigana": "làng màn zhǔ yì", "sentence_source": "generated"}, {"text": "有人说她骨子里有浪漫主义情怀。", "target_word": "浪漫主义", "complexity_tier": "T3", "furigana": "làng màn zhǔ yì", "sentence_source": "generated"}, {"text": "他总用一种浪漫主义情怀看待世界。", "target_word": "浪漫主义", "complexity_tier": "T3", "furigana": "làng màn zhǔ yì", "sentence_source": "generated"}, {"text": "浪漫主义情怀让她相信，世界很美好。", "target_word": "浪漫主义", "complexity_tier": "T3", "furigana": "làng màn zhǔ yì", "sentence_source": "generated"}, {"text": "他身上浓厚的浪漫主义色彩，常让朋友们会心一笑。", "target_word": "浪漫主义", "complexity_tier": "T3", "furigana": "làng màn zhǔ yì", "sentence_source": "generated"}, {"text": "你的浪漫主义情怀很可贵，但这份工作需要踏实。", "target_word": "浪漫主义", "complexity_tier": "T3", "furigana": "làng màn zhǔ yì", "sentence_source": "generated"}, {"text": "她怀着浪漫主义情怀去旅行。", "target_word": "浪漫主义", "complexity_tier": "T3", "furigana": "làng màn zhǔ yì", "sentence_source": "generated"}, {"text": "年轻时他身上的浪漫主义色彩很浓。", "target_word": "浪漫主义", "complexity_tier": "T3", "furigana": "làng màn zhǔ yì", "sentence_source": "generated"}], "morphological_forms": [{"form": "浪漫主義", "label": "繁体"}, {"form": "浪漫主义者", "label": "复合"}], "register": "中性", "sense_fingerprint": "认为世界美好、像童话一样的人生态度与想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3313a1a0-cc7f-4011-8962-bd3ab5d2c9e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22132, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "浪漫主义", "is_correct": true, "explanation": "正确。“他身上有一种浪漫主义情怀，总觉得生活像童话”中，此处应填“浪漫主义”。"}, {"text": "现实", "is_correct": false, "explanation": "语义：“现实”与“总觉得生活像童话”的态度相反。"}, {"text": "机械", "is_correct": false, "explanation": "语义：“机械”指冷冰冰的操作，与童话般的生活感受冲突。"}, {"text": "农业", "is_correct": false, "explanation": "搭配：“农业情怀”不是常用搭配，与“情怀”一词不相配。"}], "explanations": {"浪漫主义": "正确。“他身上有一种浪漫主义情怀，总觉得生活像童话”中，此处应填“浪漫主义”。", "现实": "语义：“现实”与“总觉得生活像童话”的态度相反。", "机械": "语义：“机械”指冷冰冰的操作，与童话般的生活感受冲突。", "农业": "搭配：“农业情怀”不是常用搭配，与“情怀”一词不相配。"}, "sentence_index": 0, "correct_answer": "浪漫主义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "有人说她骨子里有浪漫主义的数据。", "explanation": "这里应该用〈情怀〉。浪漫主义指看待世界的态度，不能与「数据」搭配。"}, {"text": "有人说她是一个浪漫主义。", "explanation": "这里应该用〈浪漫主义者〉。浪漫主义指态度或思潮，指人要加“者”。"}, {"text": "她对大海满怀浪漫主义。", "explanation": "这里应该用〈向往〉。浪漫主义指看待世界的态度或思潮，不是可以“满怀”的心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3aee74ca-cee8-48a7-a1f0-2caa03801e6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22132, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浪漫主义", "is_correct": true, "explanation": "正确。“他身上浓厚的浪漫主义色彩”指带有理想化情调的气质，此处应填“浪漫主义”。"}, {"text": "硝烟", "is_correct": false, "explanation": "语义：硝烟与“会心一笑”的轻松氛围冲突。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：病毒与句中描述的气质无关，语义不通。"}, {"text": "煤炭", "is_correct": false, "explanation": "搭配：“色彩”前多用颜色或风格词，煤炭只表示物料，不作色彩的修饰语。"}], "explanations": {"浪漫主义": "正确。“他身上浓厚的浪漫主义色彩”指带有理想化情调的气质，此处应填“浪漫主义”。", "硝烟": "语义：硝烟与“会心一笑”的轻松氛围冲突。", "病毒": "语义：病毒与句中描述的气质无关，语义不通。", "煤炭": "搭配：“色彩”前多用颜色或风格词，煤炭只表示物料，不作色彩的修饰语。"}, "sentence_index": 6, "correct_answer": "浪漫主义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他和女友之间的浪漫主义很坚硬。", "explanation": "这里应该用〈甜蜜〉。浪漫主义形容情怀或氛围，不能与「很坚硬」搭配。"}, {"text": "他对被骗这件事很有浪漫主义情怀。", "explanation": "这里应该用〈警惕〉。浪漫主义指把世界看得美好的情怀，不能用来形容对被骗这件事的态度。"}, {"text": "他对数字的计算很有浪漫主义。", "explanation": "这里应该用〈精确〉。浪漫主义指重视感情与想象的态度，不用于形容计算的准确性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3aee74ca-cee8-48a7-a1f0-2caa03801e6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22132, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对爱情很有浪漫主义地情怀。", "corrected_sentence": "他对爱情很有浪漫主义情怀。", "error_description": "错误形式“浪漫主义地情怀”，正确形式“浪漫主义情怀”。“地”用于修饰动词、形容词，修饰名词“情怀”时不用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3aee74ca-cee8-48a7-a1f0-2caa03801e6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22132, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的文字很有浪漫主义地色彩。", "corrected_sentence": "她的文字很有浪漫主义色彩。", "error_description": "错误形式“浪漫主义地色彩”，正确形式“浪漫主义色彩”。“地”用于修饰动词、形容词，修饰名词“色彩”时不用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3aee74ca-cee8-48a7-a1f0-2caa03801e6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22134, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "稀疏", "is_correct": true, "explanation": "正确：稀疏指数量少、间隔大，与“密集”正相反。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软形容质地不硬，和“密集”没有反义关系。"}, {"text": "轻快", "is_correct": false, "explanation": "轻快形容动作或节奏灵活，和“密集”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线充足，和“密集”没有反义关系。"}], "correct_answer": "稀疏", "explanations": {"稀疏": "正确：稀疏指数量少、间隔大，与“密集”正相反。", "柔软": "柔软形容质地不硬，和“密集”没有反义关系。", "轻快": "轻快形容动作或节奏灵活，和“密集”没有反义关系。", "明亮": "明亮形容光线充足，和“密集”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc597bcd-5819-488a-bfc6-a09fdb9ef0d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22134, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "稀疏", "is_correct": true, "explanation": "正确：稀疏指数量少、间隔大，与“密集”正相反。"}, {"text": "甜美", "is_correct": false, "explanation": "甜美形容味道或声音好听，和“密集”没有反义关系。"}, {"text": "灿烂", "is_correct": false, "explanation": "灿烂形容光彩耀眼，和“密集”没有反义关系。"}, {"text": "晴朗", "is_correct": false, "explanation": "晴朗形容天气好，和“密集”没有反义关系。"}], "correct_answer": "稀疏", "explanations": {"稀疏": "正确：稀疏指数量少、间隔大，与“密集”正相反。", "甜美": "甜美形容味道或声音好听，和“密集”没有反义关系。", "灿烂": "灿烂形容光彩耀眼，和“密集”没有反义关系。", "晴朗": "晴朗形容天气好，和“密集”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc597bcd-5819-488a-bfc6-a09fdb9ef0d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22134, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很多东西挤在一起，靠得很近。", "primary_collocate": null, "pronunciation": "mì jí", "ipa": "mi˥˩ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "菜市场里人很密集，我们走得很慢。", "target_word": "密集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花园里的小花种得太密集了。", "target_word": "密集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高楼密集的城市，天空显得很小。", "target_word": "密集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼群密集地游过来，水都变黑了。", "target_word": "密集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书架上的书摆得很密集，放不下了。", "target_word": "密集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山下的房子很密集，连路都很窄。", "target_word": "密集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的树很密集，坐在下面很凉快。", "target_word": "密集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家附近的公交车站很密集。", "target_word": "密集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花丛里蜜蜂密集地飞着。", "target_word": "密集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课后，操场上的学生非常密集。", "target_word": "密集", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "密集型", "label": "复合"}, {"form": "人口密集", "label": "复合"}], "register": "中性", "sense_fingerprint": "很多东西挤在一起、靠得很近的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30f964d1-cfc8-4ab7-9f81-00f306f69457') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22134, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "密集", "is_correct": true, "explanation": "正确：密集（mì jí）指很多东西挤在一起，靠得很近。"}, {"text": "密技", "is_correct": false, "explanation": "密技（mì jì）只是第二个音节的声调不同，意思是秘密的技巧，和“密集”不是一回事。"}, {"text": "密计", "is_correct": false, "explanation": "密计（mì jì）与 jí 的声调不同，意思是秘密的计策，不是“挤在一起”。"}, {"text": "秘计", "is_correct": false, "explanation": "秘计（mì jì）的第二个音节声调与 jí 不同，意思是秘密的计谋。"}], "explanations": {"密集": "正确：密集（mì jí）指很多东西挤在一起，靠得很近。", "密技": "密技（mì jì）只是第二个音节的声调不同，意思是秘密的技巧，和“密集”不是一回事。", "密计": "密计（mì jì）与 jí 的声调不同，意思是秘密的计策，不是“挤在一起”。", "秘计": "秘计（mì jì）的第二个音节声调与 jí 不同，意思是秘密的计谋。"}, "sentence_index": null, "correct_answer": "密集"}, "level_3": {"options": [{"text": "密集", "is_correct": true, "explanation": "正确：“人很密集”指很多人挤在一起，所以“我们走得很慢”。"}, {"text": "空旷", "is_correct": false, "explanation": "语义：“空旷”形容地方空、没有人，和“走得很慢”的拥挤情景不符。"}, {"text": "寂静", "is_correct": false, "explanation": "语义：“寂静”形容安静无声，不是形容人挤在一起。"}, {"text": "苍白", "is_correct": false, "explanation": "体貌：“苍白”形容脸色，不能用来形容一群人挤在一起的样子。"}], "explanations": {"密集": "正确：“人很密集”指很多人挤在一起，所以“我们走得很慢”。", "空旷": "语义：“空旷”形容地方空、没有人，和“走得很慢”的拥挤情景不符。", "寂静": "语义：“寂静”形容安静无声，不是形容人挤在一起。", "苍白": "体貌：“苍白”形容脸色，不能用来形容一群人挤在一起的样子。"}, "sentence_index": 0, "correct_answer": "密集"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两国的关系很密集，合作很多。", "explanation": "这里应该用〈紧密〉。关系、联系要用紧密，密集只指许多东西或人挤在一起。"}, {"text": "老师讲课时，大家的思想都很密集。", "explanation": "这里应该用〈集中〉。思想、注意力要用集中，密集不能用来形容思想。"}, {"text": "这只猫的身材很密集，抱起来很重。", "explanation": "这里应该用〈胖〉。密集指许多东西挤在一起，不能形容猫的身材；形容猫身材圆润、抱起来很沉，要用胖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc597bcd-5819-488a-bfc6-a09fdb9ef0d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22134, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "密集", "is_correct": true, "explanation": "正确：“河边的树很密集”指树挤在一起，所以“坐在下面很凉快”。"}, {"text": "透明", "is_correct": false, "explanation": "语义：“透明”形容能看透的物体，不能用来形容树的分布。"}, {"text": "嘈杂", "is_correct": false, "explanation": "语义：“嘈杂”形容声音乱，不能用来形容树的密度。"}, {"text": "嘹亮", "is_correct": false, "explanation": "语义：“嘹亮”形容声音响亮，不能用来形容树。"}], "explanations": {"密集": "正确：“河边的树很密集”指树挤在一起，所以“坐在下面很凉快”。", "透明": "语义：“透明”形容能看透的物体，不能用来形容树的分布。", "嘈杂": "语义：“嘈杂”形容声音乱，不能用来形容树的密度。", "嘹亮": "语义：“嘹亮”形容声音响亮，不能用来形容树。"}, "sentence_index": 6, "correct_answer": "密集"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的声音很密集，全班都听得见。", "explanation": "这里应该用〈洪亮〉。密集指许多东西挤在一起，不能形容声音的大小；声音大要用洪亮。"}, {"text": "我们两家的关系很密集，常来常往。", "explanation": "这里应该用〈亲密〉。关系、感情要用亲密，密集只指许多东西或人挤在一起。"}, {"text": "这张桌子很密集，一个人就能搬走。", "explanation": "这里应该用〈轻〉。密集指许多东西挤在一起，不能形容桌子的重量；桌子轻、一个人就能搬走要用轻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc597bcd-5819-488a-bfc6-a09fdb9ef0d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22134, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车站前的自行车得密集，我们只能慢慢走。", "corrected_sentence": "车站前的自行车很密集，我们只能慢慢走。", "error_description": "用词错：程度副词“很”误写成“得”。“得”是补语标记，接在动词或形容词后面（如“种得太密集”“密集得很”），不能直接修饰形容词“密集”，应说“很密集”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc597bcd-5819-488a-bfc6-a09fdb9ef0d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22134, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山坡上有一片密集地小树林。", "corrected_sentence": "山坡上有一片密集的小树林。", "error_description": "结构错误：“密集”修饰“小树林”时要用“的”，不能用“地”。正确说法是“密集的小树林”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc597bcd-5819-488a-bfc6-a09fdb9ef0d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
