INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22138, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用来帮助记住或认出东西的符号。", "primary_collocate": null, "pronunciation": "jì hao", "ipa": "tɕi˥˩ xaʊ", "syllable_count": 2, "sentences": [{"text": "我在自己的杯子上贴了一个记号。", "target_word": "记号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在回家的路上留下了记号。", "target_word": "记号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在读到的那页做了记号。", "target_word": "记号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服上没有记号，我找不到是谁的。", "target_word": "记号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟用红笔在日历上画了记号。", "target_word": "记号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在树上做记号，这样回来时不会走错。", "target_word": "记号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在作业本上画了记号，提醒自己明天再看。", "target_word": "记号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "箱子上有蓝色的记号，一眼就能认出来。", "target_word": "记号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，不会的题要先做个记号。", "target_word": "记号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在雪地里插了小旗当记号。", "target_word": "记号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个记号", "label": "量词"}, {"form": "记号笔", "label": "复合"}, {"form": "記號", "label": "繁体"}], "register": "中性", "sense_fingerprint": "留在物品或路上、帮助记住或认出它的标记", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30f964d1-cfc8-4ab7-9f81-00f306f69457') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22138, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "记号", "is_correct": true, "explanation": "正确：记号指用来帮助记住或认出东西的符号，贴在杯子上正好用来认出是自己的杯子。"}, {"text": "云", "is_correct": false, "explanation": "语义：云在天上，不是能贴在杯子上的东西，“贴”和“云”对不上。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“贴”接的是看得见的物件，不能说“贴心情”。"}, {"text": "清晨", "is_correct": false, "explanation": "语义：清晨是一段时间，不是能贴在杯子上的实物。"}], "explanations": {"记号": "正确：记号指用来帮助记住或认出东西的符号，贴在杯子上正好用来认出是自己的杯子。", "云": "语义：云在天上，不是能贴在杯子上的东西，“贴”和“云”对不上。", "心情": "搭配：“贴”接的是看得见的物件，不能说“贴心情”。", "清晨": "语义：清晨是一段时间，不是能贴在杯子上的实物。"}, "sentence_index": 0, "correct_answer": "记号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的记号很高，考了九十分。", "explanation": "这里应该用〈分数〉。考试的得分要说分数；记号是用来做标记的符号，不能指得分。"}, {"text": "奶奶的记号很好，连我的生日都记得。", "explanation": "这里应该用〈记性〉。记性指记忆力的好坏，记号是用来做标记的符号，不能说“记号很好”。"}, {"text": "他把这一年的事都写进了记号里。", "explanation": "这里应该用〈日记〉。写下一年的事要说日记；记号是用来做标记的符号，不能装事情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc597bcd-5819-488a-bfc6-a09fdb9ef0d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22138, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "记号", "is_correct": true, "explanation": "正确：记号指在作业本上做的标记，正好用来提醒自己明天再看。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间是抽象的概念，不能画在作业本上。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“画”接的是看得见的痕迹，不能说“画声音”。"}, {"text": "回声", "is_correct": false, "explanation": "语义：回声是声音的反射，不能画在作业本上。"}], "explanations": {"记号": "正确：记号指在作业本上做的标记，正好用来提醒自己明天再看。", "时间": "语义：时间是抽象的概念，不能画在作业本上。", "声音": "搭配：“画”接的是看得见的痕迹，不能说“画声音”。", "回声": "语义：回声是声音的反射，不能画在作业本上。"}, "sentence_index": 6, "correct_answer": "记号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的电话记号是一串数字。", "explanation": "这里应该用〈号码〉。电话用的是号码，记号是用来标记的符号，不是一串数字。"}, {"text": "他忘了邮箱的记号，怎么也登不上去了。", "explanation": "这里应该用〈密码〉。密码是登录时输入的一组字符，记号只是帮助认出东西的标记，不能用来指登录邮箱的凭据。"}, {"text": "会后，他说出了自己的记号。", "explanation": "这里应该用〈感想〉。感想指听完或看完后的心得体会，可以说出来；记号是用来帮助认出东西的符号，不能用来指想法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc597bcd-5819-488a-bfc6-a09fdb9ef0d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22138, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在箱子的角落做了一只记号。", "corrected_sentence": "他在箱子的角落做了一个记号。", "error_description": "量词错误：“记号”要用量词“个”，说“一只记号”不对，“只”多用于动物和成对的东西。正确说法是“一个记号”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc597bcd-5819-488a-bfc6-a09fdb9ef0d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22138, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在盒子的盖子上做了一张记号。", "corrected_sentence": "他在盒子的盖子上做了一个记号。", "error_description": "量词错误：“记号”不用“张”来数，应该用“个”。“张”多用于纸张、桌子等平面的东西。正确说法是“一个记号”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc597bcd-5819-488a-bfc6-a09fdb9ef0d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22140, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc597bcd-5819-488a-bfc6-a09fdb9ef0d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
