INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22142, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指一个人在社会中所处的位置或等级。", "primary_collocate": null, "pronunciation": "dì wèi", "ipa": "ti˥˩ weɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他是大学教授，在社会上很有地位。", "target_word": "地位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在中国，医生的地位一般比较高。", "target_word": "地位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她工作很努力，终于提高了自己的地位。", "target_word": "地位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我们家，爷爷的地位最高，大家都听他的。", "target_word": "地位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的经济很好，在世界上的地位越来越高。", "target_word": "地位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不管地位高低，大家在法律面前都是平等的。", "target_word": "地位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他换了新工作，地位一下子变高了。", "target_word": "地位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在社会上，老师的地位很重要。", "target_word": "地位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不看重钱和地位，只想过简单的生活。", "target_word": "地位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去女人在家里没有什么地位。", "target_word": "地位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "社会地位", "label": "复合"}, {"form": "国际地位", "label": "复合"}], "register": "中性", "sense_fingerprint": "人在社会中所处的位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7441cee5-2e00-483a-8d58-1c3e5c5576de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22142, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地位", "is_correct": true, "explanation": "正确：教授在社会上的身份和分量，用“地位”最恰当。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“很有”修饰的是分量、能力之类的抽象义，“体积”指空间大小，不能这样修饰社会身份，句意不通。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“很有”修饰的是分量、能力之类的抽象义，“身高”是具体数值，不搭配。"}, {"text": "性别", "is_correct": false, "explanation": "语义：“性别”是人的生理或社会分类，不能说在社会上“很有性别”。"}], "explanations": {"地位": "正确：教授在社会上的身份和分量，用“地位”最恰当。", "体积": "搭配：“很有”修饰的是分量、能力之类的抽象义，“体积”指空间大小，不能这样修饰社会身份，句意不通。", "身高": "搭配：“很有”修饰的是分量、能力之类的抽象义，“身高”是具体数值，不搭配。", "性别": "语义：“性别”是人的生理或社会分类，不能说在社会上“很有性别”。"}, "sentence_index": 0, "correct_answer": "地位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座学校的地位在河边。", "explanation": "这里应该用〈位置〉。地位指社会身份或等级，学校的地理位置要用〈位置〉。"}, {"text": "他的速度很快，一下子就跑完了全程。", "explanation": "这里应该用〈速度〉。地位指社会中的位置，跑步的快慢要用〈速度〉。"}, {"text": "他的身体地位很好。", "explanation": "这里应该用〈状况〉。地位指社会中的位置，身体的好坏要用〈状况〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f474352a-c393-4fb5-801c-049a504dc0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22142, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地位", "is_correct": true, "explanation": "正确：换了新工作后社会上的地位提高，用“地位”最恰当。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“变高”不用于身高，身高说“长高”，换工作也不会改变身高。"}, {"text": "温度", "is_correct": false, "explanation": "语义：换工作不会使温度升高，句子语义不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄只会增长，换工作不会让年龄“变高”。"}], "explanations": {"地位": "正确：换了新工作后社会上的地位提高，用“地位”最恰当。", "身高": "搭配：“变高”不用于身高，身高说“长高”，换工作也不会改变身高。", "温度": "语义：换工作不会使温度升高，句子语义不通。", "年龄": "语义：年龄只会增长，换工作不会让年龄“变高”。"}, "sentence_index": 6, "correct_answer": "地位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种药的地位很大，很多病人都用。", "explanation": "这里应该用〈作用〉。地位指社会中的位置，药物的效果要用〈作用〉。"}, {"text": "这辆车的地位很快，开起来很舒服。", "explanation": "这里应该用〈速度〉。地位指社会中的位置，车子的快慢要用〈速度〉。"}, {"text": "这杯水的地位很高，我一口都没喝。", "explanation": "这里应该用〈温度〉。地位指社会中的位置，水的冷热要用〈温度〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f474352a-c393-4fb5-801c-049a504dc0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22142, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老人在村里很是地位，大家都尊敬他。", "corrected_sentence": "这位老人在村里很有地位，大家都尊敬他。", "error_description": "“地位”前面应用动词“有”，说“很有地位”。“是”不能直接带“地位”作宾语，“很是地位”不成词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f474352a-c393-4fb5-801c-049a504dc0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22142, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一个很有地位人。", "corrected_sentence": "他是一个很有地位的人。", "error_description": "“地位”修饰“人”时要加“的”，应说“很有地位的人”。漏掉“的”是常见错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f474352a-c393-4fb5-801c-049a504dc0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
