INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22146, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个地方的最中间或最重要的部分。", "primary_collocate": null, "pronunciation": "zhōng xīn", "ipa": "/ʈ͡ʂʊŋ˥ ɕin˥/", "syllable_count": 2, "sentences": [{"text": "我家住在城市的中心。", "target_word": "中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的中心有一个大广场。", "target_word": "中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车站就在城市的中心。", "target_word": "中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在小镇的中心见面吧。", "target_word": "中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园的中心有一棵大树。", "target_word": "中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从这里走到广场中心要十分钟。", "target_word": "中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老城的中心有很多旧房子。", "target_word": "中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村子的中心有一口老井。", "target_word": "中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在这座城市的中心工作。", "target_word": "中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校在这个区的中心，很好找。", "target_word": "中心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "中心点", "label": "复合"}], "register": "中性", "sense_fingerprint": "一个地方最中间、最重要的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f432ec0-4827-4655-ae2d-bca2ba58dc77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22146, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "中心", "is_correct": true, "explanation": "正确：zhōng xīn，指一个地方最中间或最重要的部分。"}, {"text": "重心", "is_correct": false, "explanation": "声调不同：重心 zhòng xīn 首字为第四声，中心 zhōng xīn 首字为第一声，意思是物体重量集中的点，不是中心。"}, {"text": "中兴", "is_correct": false, "explanation": "韵尾不同：zhōng xīng（ng）与 zhōng xīn（n），意思是国家或事业再度兴盛，不是中心。"}, {"text": "中音", "is_correct": false, "explanation": "声母不同：yīn 与 xīn（零声母与 x），意思是声乐中的中等音域，不是中心。"}], "explanations": {"中心": "正确：zhōng xīn，指一个地方最中间或最重要的部分。", "重心": "声调不同：重心 zhòng xīn 首字为第四声，中心 zhōng xīn 首字为第一声，意思是物体重量集中的点，不是中心。", "中兴": "韵尾不同：zhōng xīng（ng）与 zhōng xīn（n），意思是国家或事业再度兴盛，不是中心。", "中音": "声母不同：yīn 与 xīn（零声母与 x），意思是声乐中的中等音域，不是中心。"}, "sentence_index": null, "correct_answer": "中心"}, "level_3": {"options": [{"text": "中心", "is_correct": true, "explanation": "正确：“城市的中心”指城市最中间的地带，人可以住在那里。"}, {"text": "历史", "is_correct": false, "explanation": "语义：“住在”需要居住的地点，“历史”不是可以居住的地方。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“住在”后接处所，“价格”不能作为居住的地点。"}, {"text": "文化", "is_correct": false, "explanation": "配价：“住在”要求处所宾语，“城市的文化”不是可以居住的地点。"}], "explanations": {"中心": "正确：“城市的中心”指城市最中间的地带，人可以住在那里。", "历史": "语义：“住在”需要居住的地点，“历史”不是可以居住的地方。", "价格": "搭配：“住在”后接处所，“价格”不能作为居住的地点。", "文化": "配价：“住在”要求处所宾语，“城市的文化”不是可以居住的地点。"}, "sentence_index": 0, "correct_answer": "中心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们家装了一台中心空调，夏天很凉快。", "explanation": "这里应该用〈中央〉。固定说法是“中央空调”，“中心”不修饰空调。"}, {"text": "这家公司掌握了中心技术，产品很有竞争力。", "explanation": "这里应该用〈核心〉。“核心技术”是固定说法，“中心技术”不这么用。"}, {"text": "这些水果要通过中心商才能运到市场。", "explanation": "这里应该用〈中间〉。“中间商”指买卖之间的中介人，“中心商”不成词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc3866cd-50b2-4a65-ad2d-a32933313adb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22146, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中心", "is_correct": true, "explanation": "正确：“老城的中心”指老城的中心地带，那里有很多旧房子，符合句意。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：城市没有脾气，“脾气”只用于人。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”描述人或物体的高矮，老城没有身高这一外形。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“老城的体重”不成搭配，体重只说人或动物。"}], "explanations": {"中心": "正确：“老城的中心”指老城的中心地带，那里有很多旧房子，符合句意。", "脾气": "语义：城市没有脾气，“脾气”只用于人。", "身高": "体貌：“身高”描述人或物体的高矮，老城没有身高这一外形。", "体重": "搭配：“老城的体重”不成搭配，体重只说人或动物。"}, "sentence_index": 6, "correct_answer": "中心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们约在下午的中心见面，别迟到了。", "explanation": "这里的“中心”指时间上的正中，而这个义项的“中心”指地方的最中间或最重要的部分，不指时间。"}, {"text": "这个问题很中心，我们得先解决。", "explanation": "“中心”是名词，不能直接受副词“很”修饰表示程度；这里要表达“重要”，应说“很重要”。"}, {"text": "他总是中心地反对我的意见。", "explanation": "“中心”不表示态度的坚决，不能作状语修饰动词“反对”，应说“坚决地反对”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc3866cd-50b2-4a65-ad2d-a32933313adb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22146, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把车停城市的中心。", "corrected_sentence": "我们把车停在城市的中心。", "error_description": "介词错误：处所短语前的“在”不能省，“把车停”后必须用“在”引出地点，应为“把车停在城市的中心”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc3866cd-50b2-4a65-ad2d-a32933313adb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22146, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老城有一条明显的中心。", "corrected_sentence": "老城有一个明显的中心。", "error_description": "量词错误：“中心”指一个区域，应用量词“个”，不能用“条”（条多用于长条形事物）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc3866cd-50b2-4a65-ad2d-a32933313adb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
