INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22148, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让别人做他不想做的事。", "primary_collocate": null, "pronunciation": "pò shǐ", "ipa": "/pʰɔ˥˩ ʂɻ̩˨˩˦/", "syllable_count": 2, "sentences": [{"text": "大雨迫使比赛推迟了。", "target_word": "迫使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格太高，迫使很多人不再买房。", "target_word": "迫使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作太忙迫使他放弃了旅行。", "target_word": "迫使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生意不好，迫使老板关掉了小店。", "target_word": "迫使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雪迫使飞机晚点了几个小时。", "target_word": "迫使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里很穷，迫使他早早出去工作。", "target_word": "迫使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有别的办法，迫使我们改变了计划。", "target_word": "迫使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏天气迫使游客留在酒店里。", "target_word": "迫使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "身体不好迫使她离开了喜欢的工作。", "target_word": "迫使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师不能迫使学生做不想做的事。", "target_word": "迫使", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "因情况或压力使人不得不做不想做的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa75729c-4fdb-4353-ab48-5298e7732270') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22148, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "迫使", "is_correct": true, "explanation": "正确：“大雨迫使比赛推迟了”，指大雨使比赛不得不推迟。"}, {"text": "批准", "is_correct": false, "explanation": "配价：“批准”的主语须是有权力的人或机构，大雨不能批准比赛推迟。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：“祝贺”表示庆祝，与比赛推迟的语境不符。"}, {"text": "允许", "is_correct": false, "explanation": "语义：“允许”是同意，大雨不能允许比赛推迟。"}], "explanations": {"迫使": "正确：“大雨迫使比赛推迟了”，指大雨使比赛不得不推迟。", "批准": "配价：“批准”的主语须是有权力的人或机构，大雨不能批准比赛推迟。", "祝贺": "语义：“祝贺”表示庆祝，与比赛推迟的语境不符。", "允许": "语义：“允许”是同意，大雨不能允许比赛推迟。"}, "sentence_index": 0, "correct_answer": "迫使"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个好消息迫使他很快乐。", "explanation": "这里应该用〈让〉。迫使是强迫他人去做不情愿的事，后面要接动作；表示心情要用“让”。"}, {"text": "这首歌好听，迫使人想跟着唱。", "explanation": "这里应该用〈吸引〉。迫使是强迫人做不情愿的事，“想跟着唱”是主动的，不能用迫使。"}, {"text": "孩子很喜欢画画，迫使他每天都主动拿起画笔。", "explanation": "这里应该用〈鼓励〉。迫使是强迫人做不情愿的事，“主动”拿起画笔是自愿的，不能用迫使。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22148, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "迫使", "is_correct": true, "explanation": "正确：“没有别的办法，迫使我们改变了计划”，指在无奈中被逼改变计划。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”表示称赞，与“没有别的办法”的语境不符。"}, {"text": "安慰", "is_correct": false, "explanation": "语义：“安慰”是劝慰，与“改变计划”的语境不符。"}, {"text": "颁布", "is_correct": false, "explanation": "搭配：“颁布”用于法令、规定，不能用于“我们”的计划。"}], "explanations": {"迫使": "正确：“没有别的办法，迫使我们改变了计划”，指在无奈中被逼改变计划。", "赞美": "语义：“赞美”表示称赞，与“没有别的办法”的语境不符。", "安慰": "语义：“安慰”是劝慰，与“改变计划”的语境不符。", "颁布": "搭配：“颁布”用于法令、规定，不能用于“我们”的计划。"}, "sentence_index": 6, "correct_answer": "迫使"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他迫使这张桌子站起来。", "explanation": "这里应该用〈搬〉。桌子不能被迫站起来，应说“搬”或“抬”。"}, {"text": "大雨迫使阳光出来了。", "explanation": "这里不通：大雨不会迫使阳光出来，应说“大雨过后阳光出来了”。"}, {"text": "我迫使我的衣服很干净。", "explanation": "这里应该用〈洗〉。衣服不能被迫干净，应说“把衣服洗干净”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22148, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "经济危机使迫使很多工厂停产了。", "corrected_sentence": "经济危机迫使很多工厂停产了。", "error_description": "重复使役：“使”与“迫使”都表示使令，不能连用，应去掉“使”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22148, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场大火把迫使我们离开了家。", "corrected_sentence": "这场大火迫使我们离开了家。", "error_description": "结构错误：“迫使”不能放在“把”字之后，“把”字结构不能带“迫使”，应去掉“把”，说“这场大火迫使我们离开了家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
