INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22150, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把故事变成动作演给大家看。", "primary_collocate": null, "pronunciation": "biǎo yǎn", "ipa": "piɑʊ˨˩˦ jɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "小朋友们表演《三只小猪》的故事。", "target_word": "表演", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们来表演这个故事吧。", "target_word": "表演", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他用动作表演小狗跑步。", "target_word": "表演", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们在课堂上表演课文。", "target_word": "表演", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你能表演一下这只小鸟吗？", "target_word": "表演", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她表演得很像，大家都笑了。", "target_word": "表演", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们分角色表演。", "target_word": "表演", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们在教室里表演了一个短剧。", "target_word": "表演", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喜欢表演故事给弟弟看。", "target_word": "表演", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟不用说话，只用动作表演。", "target_word": "表演", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "表演了", "label": "体标"}, {"form": "表演过", "label": "体标"}, {"form": "表演者", "label": "复合"}], "register": "中性", "sense_fingerprint": "用动作把故事演给别人看", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16210783-d732-40a2-80fa-3855ab679b2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22150, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "表演", "is_correct": true, "explanation": "表演：把故事变成动作演给大家看，与句意一致。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”要接歌曲，不能说“唱《三只小猪》的故事”。"}, {"text": "参加", "is_correct": false, "explanation": "配价：“参加”要带活动作宾语，“故事”不是活动，不能直接作宾语。"}, {"text": "演奏", "is_correct": false, "explanation": "搭配：“演奏”接的是乐曲，不能说“演奏《三只小猪》的故事”。"}], "explanations": {"表演": "表演：把故事变成动作演给大家看，与句意一致。", "唱": "搭配：“唱”要接歌曲，不能说“唱《三只小猪》的故事”。", "参加": "配价：“参加”要带活动作宾语，“故事”不是活动，不能直接作宾语。", "演奏": "搭配：“演奏”接的是乐曲，不能说“演奏《三只小猪》的故事”。"}, "sentence_index": 0, "correct_answer": "表演"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用一封信表演了她的心意。", "explanation": "这里应该用〈表达〉。表演是用动作把故事演给别人看，表达心意要用表达。"}, {"text": "她的论文下个月将在杂志上表演。", "explanation": "这里应该用〈发表〉。表演是用动作把故事演给别人看，论文要用发表。"}, {"text": "他表演了一台旧电脑。", "explanation": "这里应该用〈修理〉。表演是用动作把故事演给大家看，修理电脑要用修理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b56b74d8-f574-424d-9635-f728518e07a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22150, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "表演", "is_correct": true, "explanation": "表演：按角色把故事演给大家看，与句意一致。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：“烹饪”指做菜，与“分角色”的活动无关。"}, {"text": "指挥", "is_correct": false, "explanation": "搭配：“指挥”的对象是乐队、合唱团等，不能说“分角色指挥”。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”是水中运动，与分角色的活动无关。"}], "explanations": {"表演": "表演：按角色把故事演给大家看，与句意一致。", "烹饪": "语义：“烹饪”指做菜，与“分角色”的活动无关。", "指挥": "搭配：“指挥”的对象是乐队、合唱团等，不能说“分角色指挥”。", "游泳": "语义：“游泳”是水中运动，与分角色的活动无关。"}, "sentence_index": 6, "correct_answer": "表演"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她明天要表演运动会。", "explanation": "这里应该用〈参加〉。表演是用动作把故事演给大家看，参加运动会要用参加。"}, {"text": "她表演了一锅汤。", "explanation": "这里应该用〈煮〉。表演是用动作把故事演给大家看，煮汤要用煮。"}, {"text": "他把这首诗表演成英文。", "explanation": "这里应该用〈翻译〉。表演是用动作把故事演给大家看，把诗转换成外文要用翻译。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b56b74d8-f574-424d-9635-f728518e07a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22150, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们表演地很生动。", "corrected_sentence": "孩子们表演得很生动。", "error_description": "结构错误：表演的补语结构要用“得”，不能用“地”。应说“表演得很生动”，“表演地很生动”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b56b74d8-f574-424d-9635-f728518e07a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22150, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从来不表演过这个故事。", "corrected_sentence": "我从来没表演过这个故事。", "error_description": "错误在于否定词用了“不”。表示“从来没有过某种经历”要用“没”，应说“从来没表演过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b56b74d8-f574-424d-9635-f728518e07a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
