INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22152, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西拆开再重新组合起来。", "primary_collocate": null, "pronunciation": "chóng gòu", "ipa": "ʈʂʰʊŋ˧˥ kou˥˩", "syllable_count": 2, "sentences": [{"text": "这段代码太乱，我们得重构它。", "target_word": "重构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把文章拆开，重构了每一段。", "target_word": "重构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们重构这个句子，意思不变。", "target_word": "重构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司决定重构旧系统，让它更好用。", "target_word": "重构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这篇作文很乱，你可以重构一下。", "target_word": "重构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工程师先拆开程序，再重构它。", "target_word": "重构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们把旧计划重构了，现在更清楚。", "target_word": "重构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "重构以后，这个软件跑得更快。", "target_word": "重构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用一个周末重构了整个网站。", "target_word": "重构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "写好的段落太乱，请重构后再交。", "target_word": "重构", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "重构了", "label": "体标"}, {"form": "重构过", "label": "体标"}, {"form": "重構", "label": "繁体"}], "register": "书面", "sense_fingerprint": "重构|action|把东西拆开再重新组合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c39c2f0b-1c7d-4288-9529-c42fc1d1b19a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22152, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重构", "is_correct": true, "explanation": "重构：拆开再重新组合，改善结构，与“太乱，需要整理”相符。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：欣赏是觉得好而称赞，与“代码太乱”的评价正相反。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：庆祝是为好事高兴，代码混乱没有值得庆祝的地方。"}, {"text": "背诵", "is_correct": false, "explanation": "搭配：背诵的对象是课文、诗词等，不能说“背诵代码”。"}], "explanations": {"重构": "重构：拆开再重新组合，改善结构，与“太乱，需要整理”相符。", "欣赏": "语义：欣赏是觉得好而称赞，与“代码太乱”的评价正相反。", "庆祝": "语义：庆祝是为好事高兴，代码混乱没有值得庆祝的地方。", "背诵": "搭配：背诵的对象是课文、诗词等，不能说“背诵代码”。"}, "sentence_index": 0, "correct_answer": "重构"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他重构了一场比赛，大家都很兴奋。", "explanation": "这里应该用〈组织〉。组织比赛是安排活动，重构指拆开再重新组合有结构的东西，不能用于比赛。"}, {"text": "我们一起重构了晚饭，味道很好。", "explanation": "这里应该用〈做〉。晚饭是做出来的，重构指拆开再重新组合有结构的东西，不能用于做饭。"}, {"text": "因为下雨，周末的郊游重构了。", "explanation": "这里应该用〈取消〉。下雨时郊游应当取消，重构指拆开再重新组合有结构的东西，不能用于停办活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '691f3f1c-d45d-444e-963e-277b3753efa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22152, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重构", "is_correct": true, "explanation": "重构：拆开再重新组合，与“把旧计划改好，现在更清楚”相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说“吃了计划”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱指发出歌声，与修改计划无关，句子说不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣物等，不能说“洗了计划”。"}], "explanations": {"重构": "重构：拆开再重新组合，与“把旧计划改好，现在更清楚”相符。", "吃": "搭配：“吃”的对象是食物，不能说“吃了计划”。", "唱": "语义：唱指发出歌声，与修改计划无关，句子说不通。", "洗": "搭配：“洗”的对象是衣物等，不能说“洗了计划”。"}, "sentence_index": 6, "correct_answer": "重构"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这壶水烧开以后，我们重构了它。", "explanation": "这里应该用〈加热〉。水要靠加热来处理，重构指拆开再重新组合有结构的东西，不能用于水。"}, {"text": "他每天都给花重构一次。", "explanation": "这里应该用〈浇〉。给花浇水是浇灌，重构指拆开再重新组合结构，不能用于花。"}, {"text": "妈妈重构了一锅粥，味道很好。", "explanation": "这里应该用〈煮〉。粥是煮出来的，重构指拆开再重新组合结构，不能用于做饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '691f3f1c-d45d-444e-963e-277b3753efa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22152, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们重构了过这个模块，效果很好。", "corrected_sentence": "我们重构过这个模块，效果很好。", "error_description": "错误：“了”与“过”重复。“过”已表示曾经做过，不能再加“了”，应说“重构过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '691f3f1c-d45d-444e-963e-277b3753efa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22152, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他重构了很快，大家都很惊讶。", "corrected_sentence": "他重构得很快，大家都很惊讶。", "error_description": "错误：“了”误用。动词后表示程度的补语要用“得”，不能用“了”。应说“重构得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '691f3f1c-d45d-444e-963e-277b3753efa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22154, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "过时", "is_correct": true, "explanation": "正确：“过时”与“流行”相对，指事物不再受欢迎，符合“短视频很流行”的对立。"}, {"text": "柔软", "is_correct": false, "explanation": "“柔软”指质地不硬，与“流行”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”指光线充足或颜色鲜亮，与“流行”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”指没有声音或不吵闹，与“流行”没有反义关系。"}], "correct_answer": "过时", "explanations": {"过时": "正确：“过时”与“流行”相对，指事物不再受欢迎，符合“短视频很流行”的对立。", "柔软": "“柔软”指质地不硬，与“流行”没有反义关系。", "明亮": "“明亮”指光线充足或颜色鲜亮，与“流行”没有反义关系。", "安静": "“安静”指没有声音或不吵闹，与“流行”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee911bcc-5f51-4212-b250-ee73f2686fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
