INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22160, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一排东西，一个接一个排好。", "primary_collocate": null, "pronunciation": "xù liè", "ipa": "ɕy˥˩ ljɛ˥˩", "syllable_count": 2, "sentences": [{"text": "老师把卡片排成一个序列。", "target_word": "序列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请按这个序列把积木摆好。", "target_word": "序列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个数字序列是二、四、六、八。", "target_word": "序列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把照片排成了一个长序列。", "target_word": "序列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个序列里少了一张图片。", "target_word": "序列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们看着颜色序列，说出下一个颜色。", "target_word": "序列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你找出这个序列的规律。", "target_word": "序列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红、黄、蓝是一个序列，下一个是红。", "target_word": "序列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上的石头排成一个序列，一直到门口。", "target_word": "序列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把书按大小排成序列，最高的在左边。", "target_word": "序列", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个序列", "label": "量词"}], "register": "中性", "sense_fingerprint": "一个接一个排好的一排东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f432ec0-4827-4655-ae2d-bca2ba58dc77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22160, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "风气", "is_correct": false, "explanation": "搭配：“排成”需要可以按次序摆放的具体事物，不能说“排成一个风气”。"}, {"text": "序列", "is_correct": true, "explanation": "“排成一个序列”指卡片按次序排成一排，符合句意。"}, {"text": "大学", "is_correct": false, "explanation": "语义：大学是机构，不是卡片可以排成的一排东西。"}, {"text": "二货", "is_correct": false, "explanation": "语域：“二货”是俗语，不能用在这种中性的描述中。"}], "explanations": {"风气": "搭配：“排成”需要可以按次序摆放的具体事物，不能说“排成一个风气”。", "序列": "“排成一个序列”指卡片按次序排成一排，符合句意。", "大学": "语义：大学是机构，不是卡片可以排成的一排东西。", "二货": "语域：“二货”是俗语，不能用在这种中性的描述中。"}, "sentence_index": 0, "correct_answer": "序列"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个序列的电影很好看。", "explanation": "这里应该用〈系列〉。序列指按次序排好的一排东西，不指一组相关的作品。"}, {"text": "游客们在售票口排起了一个长序列。", "explanation": "这里应该用〈队伍〉。序列指按次序排好的一排东西，说人排队时用队伍或长队，不说序列。"}, {"text": "他这次考试的序列是第三。", "explanation": "这里应该用〈名次〉。序列指按次序排好的一排东西，说考试的排名要用名次，不说序列。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc3866cd-50b2-4a65-ad2d-a32933313adb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22160, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：一块石头是单个实物，没有可以找出的排列规律。"}, {"text": "序列", "is_correct": true, "explanation": "“这个序列的规律”指有先后次序的一排事物的规律，符合句意。"}, {"text": "电话", "is_correct": false, "explanation": "语义：电话是单个器具，没有可以找出的排列规律。"}, {"text": "拳头", "is_correct": false, "explanation": "语义：拳头是单个身体部位，不存在可以找出的排列规律。"}], "explanations": {"石头": "语义：一块石头是单个实物，没有可以找出的排列规律。", "序列": "“这个序列的规律”指有先后次序的一排事物的规律，符合句意。", "电话": "语义：电话是单个器具，没有可以找出的排列规律。", "拳头": "语义：拳头是单个身体部位，不存在可以找出的排列规律。"}, "sentence_index": 6, "correct_answer": "序列"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "班里的序列上有二十个人。", "explanation": "这里应该用〈名单〉。序列指按次序排好的一排东西，不指记录人名的册子。"}, {"text": "这本书的序列写得很清楚。", "explanation": "这里应该用〈目录〉。序列指按次序排好的一排东西，说书前列出章节的清单要用目录，不说序列。"}, {"text": "宴会上的序列安排得很讲究。", "explanation": "这里应该用〈座次〉。序列指按次序排好的一排东西，说宴席上的座位次序要用座次，不说序列。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc3866cd-50b2-4a65-ad2d-a32933313adb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22160, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师把练习题按难度排成一本序列。", "corrected_sentence": "老师把练习题按难度排成一个序列。", "error_description": "量词错误：序列的量词应为“个”，写成“本”不对，“本”用于书籍等，不能用来修饰序列。正确说法是“一个序列”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc3866cd-50b2-4a65-ad2d-a32933313adb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22160, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把饼干按大小摆成一块序列。", "corrected_sentence": "妈妈把饼干按大小摆成一个序列。", "error_description": "量词错误：序列应用量词“个”，“块”用于块状的东西，不能用来修饰序列。正确说法是“一个序列”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc3866cd-50b2-4a65-ad2d-a32933313adb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
