INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22172, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "觉得别人说的话或做的事不对，问别人为什么这样做。", "primary_collocate": null, "pronunciation": "zhì yí", "ipa": "ʈʂɻ˥˩ i˧˥", "syllable_count": 2, "sentences": [{"text": "弟弟质疑我的做法，问我为什么这样。", "target_word": "质疑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明质疑老师，为什么今天作业这么多？", "target_word": "质疑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈质疑我说的话，不太相信。", "target_word": "质疑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很少质疑朋友的决定。", "target_word": "质疑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们质疑他的做法，都觉得不公平。", "target_word": "质疑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我质疑过爸爸的办法，他听了笑了。", "target_word": "质疑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她质疑我为什么迟到，我说路上堵车。", "target_word": "质疑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客人质疑价格太高，老板就解释了。", "target_word": "质疑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩子也会质疑大人的话。", "target_word": "质疑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你为什么总是质疑我？", "target_word": "质疑", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "质疑了", "label": "体标（了）"}, {"form": "质疑过", "label": "体标（过）"}], "register": "通用", "sense_fingerprint": "觉得别人的话或做法不对而追问原因", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3bb4101-1a05-429f-bb62-2e9dec135805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22172, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "质疑", "is_correct": true, "explanation": "质疑：觉得别人的话或做法不对，追问原因。"}, {"text": "制衣", "is_correct": false, "explanation": "yī（第一声）与 yí（第二声）声调不同，制衣的意思是做衣服。"}, {"text": "致意", "is_correct": false, "explanation": "yì（第四声）与 yí（第二声）声调不同，致意的意思是表示问候或敬意。"}, {"text": "执意", "is_correct": false, "explanation": "zhí 与 zhì、yì 与 yí 声调都不同，执意的意思是坚持要做某事。"}, {"text": "事宜", "is_correct": false, "explanation": "shì 与 zhì 声母不同（sh 与 zh），意思是有关的具体事务。"}], "explanations": {"质疑": "质疑：觉得别人的话或做法不对，追问原因。", "制衣": "yī（第一声）与 yí（第二声）声调不同，制衣的意思是做衣服。", "致意": "yì（第四声）与 yí（第二声）声调不同，致意的意思是表示问候或敬意。", "执意": "zhí 与 zhì、yì 与 yí 声调都不同，执意的意思是坚持要做某事。", "事宜": "shì 与 zhì 声母不同（sh 与 zh），意思是有关的具体事务。"}, "sentence_index": null, "correct_answer": "质疑"}, "level_3": {"options": [{"text": "庆祝", "is_correct": false, "explanation": "搭配：“庆祝”的对象是节日或事件，不能庆祝“做法”。"}, {"text": "质疑", "is_correct": true, "explanation": "符合语境：后半句“问我为什么这样”正是追问原因，与“质疑”的意思一致。"}, {"text": "回收", "is_correct": false, "explanation": "语义：“回收”针对废旧物品，不能用于“做法”。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的对象是场所或展览，不能参观“我的做法”。"}], "explanations": {"庆祝": "搭配：“庆祝”的对象是节日或事件，不能庆祝“做法”。", "质疑": "符合语境：后半句“问我为什么这样”正是追问原因，与“质疑”的意思一致。", "回收": "语义：“回收”针对废旧物品，不能用于“做法”。", "参观": "搭配：“参观”的对象是场所或展览，不能参观“我的做法”。"}, "sentence_index": 0, "correct_answer": "质疑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一直质疑这盏灯。", "explanation": "这里应该用〈擦〉。质疑用于别人的话或做法，擦灯要用〈擦〉。"}, {"text": "我们质疑了他的雨伞。", "explanation": "这里应该用〈撑〉。质疑用于别人的话或做法，撑雨伞要用〈撑〉。"}, {"text": "我一直质疑这只鸟。", "explanation": "这里应该用〈喂〉。质疑用于别人的话或做法，喂鸟要用〈喂〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c637796c-a5c4-4428-b297-958328aab9a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22172, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原谅", "is_correct": false, "explanation": "配价：“原谅”的对象是人或过错，“为什么迟到”是问句，不能被原谅。"}, {"text": "质疑", "is_correct": true, "explanation": "符合语境：后半句“我说路上堵车”是对追问的回应，与“质疑”的意思一致。"}, {"text": "欢迎", "is_correct": false, "explanation": "配价：“欢迎”的对象是人或到来的事，不能欢迎一个“为什么迟到”的问题。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”表示称赞，与“迟到”这种过失的语境相冲突。"}], "explanations": {"原谅": "配价：“原谅”的对象是人或过错，“为什么迟到”是问句，不能被原谅。", "质疑": "符合语境：后半句“我说路上堵车”是对追问的回应，与“质疑”的意思一致。", "欢迎": "配价：“欢迎”的对象是人或到来的事，不能欢迎一个“为什么迟到”的问题。", "赞美": "语义：“赞美”表示称赞，与“迟到”这种过失的语境相冲突。"}, "sentence_index": 6, "correct_answer": "质疑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我一直质疑这块蛋糕。", "explanation": "这里应该用〈品尝〉。质疑用于别人的话或做法，吃蛋糕要用〈品尝〉。"}, {"text": "我一直质疑这条狗。", "explanation": "这里应该用〈怕〉。质疑用于别人的话或做法，怕狗的情绪要用〈怕〉。"}, {"text": "工人质疑了这台电脑。", "explanation": "这里应该用〈修理〉。质疑不能用于机器，修理电脑要用〈修理〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c637796c-a5c4-4428-b297-958328aab9a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22172, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈对质疑我的做法，问我为什么要这样。", "corrected_sentence": "妈妈质疑我的做法，问我为什么要这样。", "error_description": "错误在介词：“对”后须接名词性成分，不能接动词短语“质疑我的做法”；去掉“对”，应为“妈妈质疑我的做法，问我为什么要这样。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c637796c-a5c4-4428-b297-958328aab9a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22172, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从没质疑了老师的话。", "corrected_sentence": "他从没质疑过老师的话。", "error_description": "“从没”表示从未有过的经历，与之搭配的体标应为“过”，不能用“了”。错误形式“质疑了”，正确形式“质疑过”，只需把“了”改为“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c637796c-a5c4-4428-b297-958328aab9a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
