INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22176, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "先锋派是一群喜欢用新方法搞艺术的人。", "primary_collocate": null, "pronunciation": "xiān fēng pài", "ipa": "ɕjɛn fɤŋ pʰaɪ", "syllable_count": 3, "sentences": [{"text": "他们是一群先锋派，什么都想试试。", "target_word": "先锋派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先锋派的朋友们在公园里演出了。", "target_word": "先锋派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我哥哥是先锋派，总爱用旧东西做画。", "target_word": "先锋派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那几个先锋派把教室变成了小剧场。", "target_word": "先锋派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先锋派每次演出，都有人来看热闹。", "target_word": "先锋派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先锋派的房间里全是怪画。", "target_word": "先锋派", "complexity_tier": "T3", "furigana": "xiān fēng pài de fáng jiān lǐ quán shì guài huà。", "sentence_source": "generated"}, {"text": "先锋派说，艺术不一定要好看。", "target_word": "先锋派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他和先锋派的朋友一起做了个展览。", "target_word": "先锋派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先锋派喜欢在街上画画，不在画室里。", "target_word": "先锋派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多人不懂先锋派，可是我觉得有意思。", "target_word": "先锋派", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "一群喜欢用新方法搞艺术的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3bb4101-1a05-429f-bb62-2e9dec135805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22176, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "先锋派", "is_correct": true, "explanation": "先锋派：一群喜欢用新方法搞艺术的人，与“什么都想试试”相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：一群石头不会“什么都想试试”，句意不通。"}, {"text": "粮食", "is_correct": false, "explanation": "搭配：“群”不计量“粮食”，“一群粮食”不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会“想试试”，句意不通。"}], "explanations": {"先锋派": "先锋派：一群喜欢用新方法搞艺术的人，与“什么都想试试”相符。", "石头": "语义：一群石头不会“什么都想试试”，句意不通。", "粮食": "搭配：“群”不计量“粮食”，“一群粮食”不通。", "桌子": "语义：桌子不会“想试试”，句意不通。"}, "sentence_index": 0, "correct_answer": "先锋派"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那一只先锋派把教室变成了小剧场。", "explanation": "这里应该用〈群〉。“只”用于动物，不用于一群人。"}, {"text": "那一条先锋派把教室变成了小剧场。", "explanation": "这里应该用〈群〉。“条”用于细长的东西，不用于人群。"}, {"text": "那一头先锋派把教室变成了小剧场。", "explanation": "这里应该用〈群〉。“头”用于牲畜，不用于人群。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c637796c-a5c4-4428-b297-958328aab9a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22176, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "先锋派", "is_correct": true, "explanation": "先锋派：一群人，能够发表主张，“先锋派说”说得通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不会发表意见，“窗户说”句意不通。"}, {"text": "粉笔", "is_correct": false, "explanation": "语义：粉笔不会发表意见，“粉笔说”句意不通。"}, {"text": "汽油", "is_correct": false, "explanation": "配价：“说”要求有言语能力的主语，“汽油”不能作施事。"}], "explanations": {"先锋派": "先锋派：一群人，能够发表主张，“先锋派说”说得通。", "窗户": "语义：窗户不会发表意见，“窗户说”句意不通。", "粉笔": "语义：粉笔不会发表意见，“粉笔说”句意不通。", "汽油": "配价：“说”要求有言语能力的主语，“汽油”不能作施事。"}, "sentence_index": 6, "correct_answer": "先锋派"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "车间里的先锋派都在加班。", "explanation": "这里应该用〈工人〉。先锋派指喜欢用新方法搞艺术的人，不指车间里的工人。"}, {"text": "景区门口的先锋派排起了长队。", "explanation": "这里应该用〈游客〉。先锋派指搞艺术的人，不指景区里排队的游客。"}, {"text": "厨房里的先锋派在炒菜。", "explanation": "这里应该用〈厨师〉。先锋派指搞艺术的人，不指炒菜的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c637796c-a5c4-4428-b297-958328aab9a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22176, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我认识一只先锋派。", "corrected_sentence": "我认识一群先锋派。", "error_description": "错误在量词：“一只先锋派”中，“只”用于动物，指一群人应用“群”。应改为“一群先锋派”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c637796c-a5c4-4428-b297-958328aab9a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22176, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天遇到了几个的先锋派。", "corrected_sentence": "我昨天遇到了几个先锋派。", "error_description": "错误在结构助词：数量短语“几个”后不能直接加“的”修饰“先锋派”，应删去“的”。应为“几个先锋派”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c637796c-a5c4-4428-b297-958328aab9a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
