INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22180, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "机会指可以做一件好事情的有利条件或恰当的时候。", "primary_collocate": null, "pronunciation": "jī huì", "ipa": "tɕi˥ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "今天我有机会去北京。", "target_word": "机会", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你什么时候有机会来我家玩？", "target_word": "机会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是我学汉语的好机会。", "target_word": "机会", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想有机会去中国看看。", "target_word": "机会", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学生们都有机会唱歌。", "target_word": "机会", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "周末是我们见面的好机会。", "target_word": "机会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她有机会和明星一起工作，非常高兴。", "target_word": "机会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "住在中国，我有很多机会说汉语。", "target_word": "机会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个机会很好，你不要不去。", "target_word": "机会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我给你一个机会，你再试一次。", "target_word": "机会", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "機會", "label": "繁体"}, {"form": "个", "label": "量词"}, {"form": "次", "label": "量词"}], "register": "中性", "sense_fingerprint": "机会·名词·可以做好事的有利条件或时机", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79963f23-daa7-47ea-a422-83820dc3fd66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22180, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "机会", "is_correct": true, "explanation": "正确。机会指可以做一件好事情的有利条件或恰当的时候，读作 jī huì。"}, {"text": "集会", "is_correct": false, "explanation": "jí（第二声）与 jī（第一声）声调不同，集会指人们聚集在一起开会。"}, {"text": "击毁", "is_correct": false, "explanation": "huǐ（第三声）与 huì（第四声）声调不同，击毁指打坏、摧毁。"}, {"text": "几回", "is_correct": false, "explanation": "jǐ 与 jī、huí 与 huì 声调都不同，几回指几次。"}, {"text": "知会", "is_correct": false, "explanation": "zhī 与 jī 声母不同（zh 与 j），知会指通知。"}], "explanations": {"机会": "正确。机会指可以做一件好事情的有利条件或恰当的时候，读作 jī huì。", "集会": "jí（第二声）与 jī（第一声）声调不同，集会指人们聚集在一起开会。", "击毁": "huǐ（第三声）与 huì（第四声）声调不同，击毁指打坏、摧毁。", "几回": "jǐ 与 jī、huí 与 huì 声调都不同，几回指几次。", "知会": "zhī 与 jī 声母不同（zh 与 j），知会指通知。"}, "sentence_index": null, "correct_answer": "机会"}, "level_3": {"options": [{"text": "机会", "is_correct": true, "explanation": "正确。“有……去北京”表示有条件去做某事，“机会”符合语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不能作为去北京的条件，句子语义不通。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“有感情”不能表示去北京的凭借，两者不搭配。"}, {"text": "雨", "is_correct": false, "explanation": "语义：“雨”与去北京的条件无关，句子语义不通。"}], "explanations": {"机会": "正确。“有……去北京”表示有条件去做某事，“机会”符合语境。", "石头": "语义：“石头”不能作为去北京的条件，句子语义不通。", "感情": "搭配：“有感情”不能表示去北京的凭借，两者不搭配。", "雨": "语义：“雨”与去北京的条件无关，句子语义不通。"}, "sentence_index": 0, "correct_answer": "机会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想等机会成熟的时候去中国看看。", "explanation": "这里应该用〈时机〉。“时机成熟”是固定说法，指做事的恰当时候；“机会成熟”不如“时机成熟”自然，此处应用〈时机〉。"}, {"text": "我想空出一点机会去中国看看。", "explanation": "这里应该用〈时间〉。“空出”后接的是可以腾出的时段，应说“空出一点时间去中国看看”；“机会”指做好事情的机遇，不与“空出”搭配。"}, {"text": "我想有一只机会去中国看看。", "explanation": "量词用错。“机会”是抽象名词，应用〈次〉或〈个〉，不能用〈只〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22180, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "机会", "is_correct": true, "explanation": "正确。机会指可以做一件好事情的有利条件或恰当的时候，读作 jī huì。"}, {"text": "寄回", "is_correct": false, "explanation": "jì（第四声）与 jī（第一声）声调不同，huí（第二声）与 huì（第四声）也不同，寄回指寄送返还。"}, {"text": "挤回", "is_correct": false, "explanation": "jǐ 与 jī、huí 与 huì 声调都不同，挤回指用力推回或挤回去。"}, {"text": "支会", "is_correct": false, "explanation": "zhī 与 jī 声母不同（zh 与 j），支会指分会。"}], "explanations": {"机会": "正确。机会指可以做一件好事情的有利条件或恰当的时候，读作 jī huì。", "寄回": "jì（第四声）与 jī（第一声）声调不同，huí（第二声）与 huì（第四声）也不同，寄回指寄送返还。", "挤回": "jǐ 与 jī、huí 与 huì 声调都不同，挤回指用力推回或挤回去。", "支会": "zhī 与 jī 声母不同（zh 与 j），支会指分会。"}, "sentence_index": null, "correct_answer": "机会"}, "level_3": {"options": [{"text": "机会", "is_correct": true, "explanation": "正确。“有……和明星一起工作”表示有条件去做某事，符合“机会”。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”不能和人“一起工作”，句子语义不通。"}, {"text": "烦恼", "is_correct": false, "explanation": "语义：“烦恼”与后句“非常高兴”的情感相冲突。"}, {"text": "病", "is_correct": false, "explanation": "搭配：“有病”不能作为“和明星一起工作”的条件，搭配不当。"}], "explanations": {"机会": "正确。“有……和明星一起工作”表示有条件去做某事，符合“机会”。", "冰箱": "语义：“冰箱”不能和人“一起工作”，句子语义不通。", "烦恼": "语义：“烦恼”与后句“非常高兴”的情感相冲突。", "病": "搭配：“有病”不能作为“和明星一起工作”的条件，搭配不当。"}, "sentence_index": 6, "correct_answer": "机会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我给你一台机会，请你好好利用。", "explanation": "量词用错。〈台〉用于机器、仪器等，不用于“机会”，应用〈个〉或〈次〉。"}, {"text": "他给了我一辆机会，我很感谢。", "explanation": "量词用错。〈辆〉用于车辆，不用于“机会”，应用〈个〉或〈次〉。"}, {"text": "这个周末我们可以抽机会一起去逛街。", "explanation": "这里应该用〈时间〉。“抽时间”是固定说法，指从安排中腾出一段时间做某事；“机会”指做好事情的机遇，不说“抽机会”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22180, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明年我希望有一只机会回老家看看。", "corrected_sentence": "明年我希望有一次机会回老家看看。", "error_description": "“机会”的量词应为“次”或“个”，不能用“只”。应说“有一次机会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22180, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈给了我一个学汉语机会。", "corrected_sentence": "妈妈给了我一个学汉语的机会。", "error_description": "“学汉语”修饰“机会”，中间需要结构助词“的”。应说“学汉语的机会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
