INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22184, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "演奏者就是表演音乐的人。", "primary_collocate": null, "pronunciation": "yǎn zòu zhě", "ipa": "jɛn˨˩˦ tsou˥˩ tʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "他是一位很有名的钢琴演奏者。", "target_word": "演奏者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演奏者都穿着黑色的衣服。", "target_word": "演奏者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小提琴演奏者站在舞台中间。", "target_word": "演奏者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个乐队有五位演奏者。", "target_word": "演奏者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演奏者在台上拉了一首很美的曲子。", "target_word": "演奏者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演奏者的手指动得很快。", "target_word": "演奏者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我妹妹想长大后做一个演奏者。", "target_word": "演奏者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演奏者向观众鞠了一躬。", "target_word": "演奏者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "街上的演奏者吸引了很多路人。", "target_word": "演奏者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演奏者每天都要练习好几个小时。", "target_word": "演奏者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "钢琴演奏者", "label": "复合"}], "register": "中性", "sense_fingerprint": "表演音乐的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71584119-e87a-4451-ae5e-3e7d6f74b1be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22184, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "演奏者", "is_correct": true, "explanation": "演奏者指表演音乐的人，与“钢琴”搭配，指钢琴演奏家，句意通顺。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师是做饭的人，与“钢琴”无关，句子说的是音乐表演者。"}, {"text": "司机", "is_correct": false, "explanation": "语义：司机是开车的人，不能是“钢琴”方面的人，句意不通。"}, {"text": "乐谱", "is_correct": false, "explanation": "搭配：“一位”用于指人，乐谱不能用“位”计量。"}], "explanations": {"演奏者": "演奏者指表演音乐的人，与“钢琴”搭配，指钢琴演奏家，句意通顺。", "厨师": "语义：厨师是做饭的人，与“钢琴”无关，句子说的是音乐表演者。", "司机": "语义：司机是开车的人，不能是“钢琴”方面的人，句意不通。", "乐谱": "搭配：“一位”用于指人，乐谱不能用“位”计量。"}, "sentence_index": 0, "correct_answer": "演奏者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那位演奏者在厨房里炒菜。", "explanation": "这里应该用〈厨师〉。演奏者指表演音乐的人，在厨房炒菜的是厨师。"}, {"text": "这出话剧的演奏者演得很好。", "explanation": "这里应该用〈演员〉。话剧里表演的人称演员，演奏者只指表演音乐的人。"}, {"text": "这位演奏者在医院里给病人看病。", "explanation": "这里应该用〈医生〉。演奏者指表演音乐的人，给病人看病的是医生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22184, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "演奏者", "is_correct": true, "explanation": "演奏者是表演音乐的人，可以作为“做一个”的职业，句意通顺。"}, {"text": "乐器", "is_correct": false, "explanation": "搭配：“做”后接的应是人或职业，乐器不能被“做”成职业。"}, {"text": "乐谱", "is_correct": false, "explanation": "语义：乐谱是记录曲子的符号，不是可以去“做”的职业。"}, {"text": "观众", "is_correct": false, "explanation": "语义：观众是看演出的人，不是职业，与“想长大后做”不符。"}], "explanations": {"演奏者": "演奏者是表演音乐的人，可以作为“做一个”的职业，句意通顺。", "乐器": "搭配：“做”后接的应是人或职业，乐器不能被“做”成职业。", "乐谱": "语义：乐谱是记录曲子的符号，不是可以去“做”的职业。", "观众": "语义：观众是看演出的人，不是职业，与“想长大后做”不符。"}, "sentence_index": 6, "correct_answer": "演奏者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位演奏者在空中翻了三个跟头。", "explanation": "这里应该用〈表演者〉。演奏者只指表演音乐的人，杂技表演者不能称演奏者。"}, {"text": "这位演奏者在晚会上宣布下一个节目。", "explanation": "这里应该用〈主持人〉。宣布节目的是主持人，演奏者是演奏音乐的人。"}, {"text": "这位演奏者在操场上教学生跑步。", "explanation": "这里应该用〈体育老师〉。教学生跑步的是体育老师，演奏者只指表演音乐的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22184, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只钢琴演奏者刚刚获奖。", "corrected_sentence": "那位钢琴演奏者刚刚获奖。", "error_description": "量词错误：指人的“钢琴演奏者”应用“位”，“只”不用于计量人，应把“那只”改为“那位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22184, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位很有才华演奏者在音乐会上很紧张。", "corrected_sentence": "这位很有才华的演奏者在音乐会上很紧张。", "error_description": "修饰语与中心语之间漏了“的”：“很有才华”修饰“演奏者”时要加“的”，应为“很有才华的演奏者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22186, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "升", "is_correct": true, "explanation": "升与降是一对反义词，表示从下往上移动，与“从山顶降到山脚”的方向相反。"}, {"text": "走", "is_correct": false, "explanation": "走指步行或行进，只表示移动，不是与“降”相对的方向义。"}, {"text": "飞", "is_correct": false, "explanation": "飞指在空中飞行，不是与“降”相对的方向义。"}, {"text": "跑", "is_correct": false, "explanation": "跑指快速移动，不表示与“降”相对的方向。"}], "correct_answer": "升", "explanations": {"升": "升与降是一对反义词，表示从下往上移动，与“从山顶降到山脚”的方向相反。", "走": "走指步行或行进，只表示移动，不是与“降”相对的方向义。", "飞": "飞指在空中飞行，不是与“降”相对的方向义。", "跑": "跑指快速移动，不表示与“降”相对的方向。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22186, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "升", "is_correct": true, "explanation": "升与降是一对反义词，表示从下往上移动，与“跳伞的人从飞机上降到草地”的方向相反。"}, {"text": "游", "is_correct": false, "explanation": "游指在水中游动，不表示与“降”相对的方向。"}, {"text": "站", "is_correct": false, "explanation": "站指站立不动，与“降”不构成反义关系。"}, {"text": "玩", "is_correct": false, "explanation": "玩指嬉戏娱乐，与“降”的移动方向无关。"}], "correct_answer": "升", "explanations": {"升": "升与降是一对反义词，表示从下往上移动，与“跳伞的人从飞机上降到草地”的方向相反。", "游": "游指在水中游动，不表示与“降”相对的方向。", "站": "站指站立不动，与“降”不构成反义关系。", "玩": "玩指嬉戏娱乐，与“降”的移动方向无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22186, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从上往下走。", "primary_collocate": null, "pronunciation": "jiàng", "ipa": "tɕjɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "我们坐缆车从山顶降到了山脚。", "target_word": "降", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "登山队完成任务后，从山顶降到了营地。", "target_word": "降", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "消防员用绳子从楼顶降到了三楼。", "target_word": "降", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "直升机从山顶慢慢降到了草地上。", "target_word": "降", "complexity_tier": "T3", "furigana": "zhí shēng jī cóng shān dǐng màn màn jiàng dào le cǎo dì shàng.", "sentence_source": "generated"}, {"text": "工人坐着吊篮，从高楼的顶部降到了地面。", "target_word": "降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "救援队用绳子把受伤的人降到了谷底。", "target_word": "降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吊车把大箱子从空中慢慢降到了船上。", "target_word": "降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停了，山顶的云慢慢降到了半山腰。", "target_word": "降", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他顺着绳子从窗口降到了院子里。", "target_word": "降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跳伞的人从飞机上降到了草地上。", "target_word": "降", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "降了", "label": "体标（了）"}, {"form": "降过", "label": "体标（过）"}, {"form": "降落", "label": "复合词"}], "register": "中性", "sense_fingerprint": "人或物沿着高处向下移动到低处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8e754af-a1d8-4f78-a77f-c537910b3253') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22186, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "降", "is_correct": true, "explanation": "降 jiàng 指从上往下走，是本题的目标词。"}, {"text": "讲", "is_correct": false, "explanation": "jiǎng（第三声）与 jiàng（第四声）声调不同，讲的意思是说话。"}, {"text": "江", "is_correct": false, "explanation": "jiāng（第一声）与 jiàng（第四声）声调不同，江的意思是河流。"}, {"text": "奖", "is_correct": false, "explanation": "jiǎng（第三声）与 jiàng（第四声）声调不同，奖的意思是奖励。"}, {"text": "见", "is_correct": false, "explanation": "jiàn 与 jiàng 韵尾不同（-n 与 -ng），见的意思是看见。"}, {"text": "向", "is_correct": false, "explanation": "xiàng 与 jiàng 声母不同（x 与 j），向的意思是朝着。"}], "explanations": {"降": "降 jiàng 指从上往下走，是本题的目标词。", "讲": "jiǎng（第三声）与 jiàng（第四声）声调不同，讲的意思是说话。", "江": "jiāng（第一声）与 jiàng（第四声）声调不同，江的意思是河流。", "奖": "jiǎng（第三声）与 jiàng（第四声）声调不同，奖的意思是奖励。", "见": "jiàn 与 jiàng 韵尾不同（-n 与 -ng），见的意思是看见。", "向": "xiàng 与 jiàng 声母不同（x 与 j），向的意思是朝着。"}, "sentence_index": null, "correct_answer": "降"}, "level_3": {"options": [{"text": "降", "is_correct": true, "explanation": "降：有控制地从高处向低处移动，与缆车从山顶到山脚的下行相符。"}, {"text": "升", "is_correct": false, "explanation": "语义：升指向上移动，与从山顶到山脚的向下方向相反。"}, {"text": "飞", "is_correct": false, "explanation": "搭配：“飞”多用于鸟、飞机等能飞的东西，缆车载人不说“飞”。"}, {"text": "摔", "is_correct": false, "explanation": "语义：摔指意外跌落，与“坐缆车”这种有控制的下行矛盾。"}], "explanations": {"降": "降：有控制地从高处向低处移动，与缆车从山顶到山脚的下行相符。", "升": "语义：升指向上移动，与从山顶到山脚的向下方向相反。", "飞": "搭配：“飞”多用于鸟、飞机等能飞的东西，缆车载人不说“飞”。", "摔": "语义：摔指意外跌落，与“坐缆车”这种有控制的下行矛盾。"}, "sentence_index": 0, "correct_answer": "降"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们沿着山路降到了山顶。", "explanation": "这里应该用〈上〉。上指向高处移动，到山顶是向上；降指向下移动，不能说“降到山顶”。"}, {"text": "他把画降到了墙上。", "explanation": "这里应该用〈挂〉。挂指把物体固定在高处，画挂在墙上；降指从高处向下移动，不能用来指挂画。"}, {"text": "他把书包降到了桌子上。", "explanation": "这里应该用〈放〉。放指把东西安置到某处，没有从上往下移动的意思；书包放在桌上不说降。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22186, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "降", "is_correct": true, "explanation": "降 jiàng 指从上往下走，是本题的目标词。"}, {"text": "姜", "is_correct": false, "explanation": "jiāng（第一声）与 jiàng（第四声）声调不同，姜的意思是生姜。"}, {"text": "健", "is_correct": false, "explanation": "jiàn 与 jiàng 韵尾不同（-n 与 -ng），健的意思是健康。"}, {"text": "建", "is_correct": false, "explanation": "jiàn 与 jiàng 韵尾不同（-n 与 -ng），建的意思是建造。"}, {"text": "项", "is_correct": false, "explanation": "xiàng 与 jiàng 声母不同（x 与 j），项的意思是项目或条款。"}], "explanations": {"降": "降 jiàng 指从上往下走，是本题的目标词。", "姜": "jiāng（第一声）与 jiàng（第四声）声调不同，姜的意思是生姜。", "健": "jiàn 与 jiàng 韵尾不同（-n 与 -ng），健的意思是健康。", "建": "jiàn 与 jiàng 韵尾不同（-n 与 -ng），建的意思是建造。", "项": "xiàng 与 jiàng 声母不同（x 与 j），项的意思是项目或条款。"}, "sentence_index": null, "correct_answer": "降"}, "level_3": {"options": [{"text": "降", "is_correct": true, "explanation": "降：有控制地从高处慢慢移到低处，符合吊车把箱子吊到船上的动作。"}, {"text": "跳", "is_correct": false, "explanation": "搭配：“跳”的主体是人或动物，不能用于大箱子。"}, {"text": "掉", "is_correct": false, "explanation": "语义：掉指意外落下，与“吊车慢慢”的受控动作矛盾。"}, {"text": "游", "is_correct": false, "explanation": "搭配：“游”指在水中移动，不能用于吊车运送箱子。"}], "explanations": {"降": "降：有控制地从高处慢慢移到低处，符合吊车把箱子吊到船上的动作。", "跳": "搭配：“跳”的主体是人或动物，不能用于大箱子。", "掉": "语义：掉指意外落下，与“吊车慢慢”的受控动作矛盾。", "游": "搭配：“游”指在水中移动，不能用于吊车运送箱子。"}, "sentence_index": 6, "correct_answer": "降"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那块石头降到了河底。", "explanation": "这里应该用〈沉〉。沉指物体没入水中向下坠落，石头沉底用“沉”；“降”指有控制地下降，不用于石头自己下坠。"}, {"text": "他从滑梯上降到了地上。", "explanation": "这里应该用〈滑〉。滑指顺着斜面滑下，滑梯上的人用“滑”；“降”指有控制地下降，不说这种滑下。"}, {"text": "杯子从桌上降到了地上。", "explanation": "这里应该用〈掉〉。掉指物体不慎落下，杯子从桌上落地用“掉”；“降”不用于不慎落下的物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22186, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "飞机慢慢降了跑道上。", "corrected_sentence": "飞机慢慢降到了跑道上。", "error_description": "“降”后接处所要用“到”，应说“降到了跑道上”；漏掉“到”直接说“降了跑道上”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22186, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把木箱降了到地面上。", "corrected_sentence": "工人把木箱降到了地面上。", "error_description": "补语“到”之后才接“了”，应说“降到了地面上”；“了”放在“到”前说“降了到地面上”，语序不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22194, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "旧", "is_correct": true, "explanation": "反义：旧指不新的、用过的，与“全新”相对。"}, {"text": "陡峭", "is_correct": false, "explanation": "无关：陡峭与全新不构成反义关系。"}, {"text": "响亮", "is_correct": false, "explanation": "无关：响亮与全新不构成反义关系。"}, {"text": "温柔", "is_correct": false, "explanation": "无关：温柔与全新不构成反义关系。"}], "correct_answer": "旧", "explanations": {"旧": "反义：旧指不新的、用过的，与“全新”相对。", "陡峭": "无关：陡峭与全新不构成反义关系。", "响亮": "无关：响亮与全新不构成反义关系。", "温柔": "无关：温柔与全新不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22194, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "陈旧", "is_correct": true, "explanation": "反义：陈旧指旧的、过时的，与“全新”相对。"}, {"text": "缓慢", "is_correct": false, "explanation": "无关：缓慢与全新不构成反义关系。"}, {"text": "寒冷", "is_correct": false, "explanation": "无关：寒冷与全新不构成反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "无关：安静与全新不构成反义关系。"}], "correct_answer": "陈旧", "explanations": {"陈旧": "反义：陈旧指旧的、过时的，与“全新”相对。", "缓慢": "无关：缓慢与全新不构成反义关系。", "寒冷": "无关：寒冷与全新不构成反义关系。", "安静": "无关：安静与全新不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22194, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "全部都是新的，没有旧的。", "primary_collocate": null, "pronunciation": "quán xīn", "ipa": "tɕʰɥɛn˧˥ ɕin˥", "syllable_count": 2, "sentences": [{"text": "我买了一部全新的手机。", "target_word": "全新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这双鞋是全新的，我还没穿过。", "target_word": "全新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里的家具都是全新的。", "target_word": "全新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新年到了，他换上全新的衣服。", "target_word": "全新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台电脑是全新的，一点儿也不旧。", "target_word": "全新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校给每个班换了全新的桌子。", "target_word": "全新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬家以后，我们要买全新的沙发。", "target_word": "全新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把旧车卖了，开着全新的车回家。", "target_word": "全新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盒子打开后，里面是全新的杯子。", "target_word": "全新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈给弟弟买了一辆全新的自行车。", "target_word": "全新", "complexity_tier": "T3", "furigana": "mā ma gěi dì di mǎi le yí liàng quán xīn de zì xíng chē", "sentence_source": "generated"}], "morphological_forms": [{"form": "全新的", "label": "定语形式"}], "register": "中性", "sense_fingerprint": "整个都是新的、没有用过的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71584119-e87a-4451-ae5e-3e7d6f74b1be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22194, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全新", "is_correct": true, "explanation": "正确：全新指整个都是新的、没有用过，修饰“手机”，符合句意。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：手机没有情绪，“悲伤的手机”不成立。"}, {"text": "饥饿", "is_correct": false, "explanation": "搭配：“饥饿”形容人或动物，不能修饰“手机”。"}, {"text": "苦涩", "is_correct": false, "explanation": "搭配：“苦涩”形容味道，不能修饰“手机”。"}], "explanations": {"全新": "正确：全新指整个都是新的、没有用过，修饰“手机”，符合句意。", "悲伤": "语义：手机没有情绪，“悲伤的手机”不成立。", "饥饿": "搭配：“饥饿”形容人或动物，不能修饰“手机”。", "苦涩": "搭配：“苦涩”形容味道，不能修饰“手机”。"}, "sentence_index": 0, "correct_answer": "全新"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "清晨的山上空气很全新，吸一口很舒服。", "explanation": "这里应该用〈新鲜〉。全新说东西从未用过，空气的清爽要用新鲜。"}, {"text": "我的爷爷很全新，他都八十岁了。", "explanation": "这里应该用〈精神〉。全新指东西全部是新的，不能用来形容人；形容老人有活力要用精神。"}, {"text": "这双鞋穿过很多次，现在却是全新的。", "explanation": "这里应该用〈新〉。全新指从未用过；穿过很多次的鞋只能说还很新，不能说全新。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22194, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全新", "is_correct": true, "explanation": "正确：全新表示从未用过的，与“买”搭配，符合句意。"}, {"text": "免费", "is_correct": false, "explanation": "语义：“要买”与“免费”矛盾，买东西不能是免费的。"}, {"text": "生锈", "is_correct": false, "explanation": "语义：“生锈”指金属变旧、损坏，与“搬家后要买新沙发”的语境矛盾。"}, {"text": "发霉", "is_correct": false, "explanation": "语义：发霉的沙发不能拿来买，与“要买”的语境矛盾。"}], "explanations": {"全新": "正确：全新表示从未用过的，与“买”搭配，符合句意。", "免费": "语义：“要买”与“免费”矛盾，买东西不能是免费的。", "生锈": "语义：“生锈”指金属变旧、损坏，与“搬家后要买新沙发”的语境矛盾。", "发霉": "语义：发霉的沙发不能拿来买，与“要买”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "全新"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台收音机用了五年，现在却是全新的。", "explanation": "这里应该用〈新〉。全新指从未用过；用了五年的收音机只能说外观还很新，不能说全新。"}, {"text": "我家的小猫很全新，它陪我们生活了三年。", "explanation": "这里应该用〈活泼〉。全新指东西全部是新的，不能用来形容动物；形容小猫的状态要用活泼。"}, {"text": "这把椅子坐了十年，现在却是全新的。", "explanation": "这里应该用〈完好〉。全新指从未用过；坐了十年的椅子只能说保存完好，不能说全新。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22194, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她穿上了一双全新了运动鞋。", "corrected_sentence": "她穿上了一双全新的运动鞋。", "error_description": "错误：“全新”后面接了“了”。正确：应为“全新的运动鞋”。形容词修饰名词时要用“的”，不能用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22194, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把厨房装修成了全新地样子。", "corrected_sentence": "他把厨房装修成了全新的样子。", "error_description": "错误：“全新”修饰名词“样子”时，结构助词用了“地”。正确：应为“全新的样子”。“地”用于修饰动词，修饰名词要用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22200, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "封闭式", "is_correct": true, "explanation": "“封闭式”与“开放式”相反，指空间或设施不敞开，人不能自由进入使用。"}, {"text": "陈旧", "is_correct": false, "explanation": "“陈旧”指东西老旧，与“开放”没有反义关系。"}, {"text": "粗糙", "is_correct": false, "explanation": "“粗糙”说表面质地，与“开放”无关。"}, {"text": "懒散", "is_correct": false, "explanation": "“懒散”说人的作风，不是“开放”的反义词。"}], "correct_answer": "封闭式", "explanations": {"封闭式": "“封闭式”与“开放式”相反，指空间或设施不敞开，人不能自由进入使用。", "陈旧": "“陈旧”指东西老旧，与“开放”没有反义关系。", "粗糙": "“粗糙”说表面质地，与“开放”无关。", "懒散": "“懒散”说人的作风，不是“开放”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22200, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "封闭式", "is_correct": true, "explanation": "“封闭式”与“开放式”相反，指空间或设施封闭，不允许人自由进入使用。"}, {"text": "狭小", "is_correct": false, "explanation": "“狭小”只说空间小，与“开放”不构成反义关系。"}, {"text": "单一", "is_correct": false, "explanation": "“单一”与“多样”相对，不是“开放”的反义词。"}, {"text": "独特", "is_correct": false, "explanation": "“独特”强调与众不同，与“开放”没有反义关系。"}], "correct_answer": "封闭式", "explanations": {"封闭式": "“封闭式”与“开放式”相反，指空间或设施封闭，不允许人自由进入使用。", "狭小": "“狭小”只说空间小，与“开放”不构成反义关系。", "单一": "“单一”与“多样”相对，不是“开放”的反义词。", "独特": "“独特”强调与众不同，与“开放”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22200, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "可以让人进去或使用，不关起来。", "primary_collocate": null, "pronunciation": "kāi fàng shì", "ipa": "kʰaɪ˥ fɑŋ˥˩ ʂɻ̩˥˩", "syllable_count": 3, "sentences": [{"text": "我家的厨房是开放式的，和客厅连在一起。", "target_word": "开放式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个开放式阳台没有墙，也没有玻璃窗。", "target_word": "开放式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的开放式图书馆，学生可以随便进去看书。", "target_word": "开放式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公园是开放式的，没有大门，也不收门票。", "target_word": "开放式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开放式的办公室里没有墙，同事们坐在一起。", "target_word": "开放式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们住在开放式的小区里，外面的人可以走进来。", "target_word": "开放式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开放式厨房很流行，做饭时还能和家人聊天。", "target_word": "开放式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座开放式花园全天不关门，大家随时可以进来。", "target_word": "开放式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们想要开放式的书架，不要带门的柜子。", "target_word": "开放式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开放式停车场没有屋顶，雨天车会湿。", "target_word": "开放式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开放式厨房", "label": "复合"}], "register": "中性", "sense_fingerprint": "空间或设施不封闭、不上锁、人可自由进出使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71584119-e87a-4451-ae5e-3e7d6f74b1be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22200, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开放式", "is_correct": true, "explanation": "“开放式”指厨房不设墙、与客厅相通，与“和客厅连在一起”相符。"}, {"text": "封闭式", "is_correct": false, "explanation": "语义：“封闭式”厨房与客厅不相通，与“连在一起”矛盾。"}, {"text": "严实的", "is_correct": false, "explanation": "体貌：“严实”形容遮挡得密不透风的样子，与“连在一起”的状态不符。"}, {"text": "独立的", "is_correct": false, "explanation": "语义：“独立”的厨房与客厅分开，与“连在一起”冲突。"}], "explanations": {"开放式": "“开放式”指厨房不设墙、与客厅相通，与“和客厅连在一起”相符。", "封闭式": "语义：“封闭式”厨房与客厅不相通，与“连在一起”矛盾。", "严实的": "体貌：“严实”形容遮挡得密不透风的样子，与“连在一起”的状态不符。", "独立的": "语义：“独立”的厨房与客厅分开，与“连在一起”冲突。"}, "sentence_index": 0, "correct_answer": "开放式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小区是开放式的，大门却每天晚上都锁得紧紧的。", "explanation": "这里的“开放式”指可以进出、不关起来，句中却说大门每天晚上都锁得紧紧的，前后矛盾；此处应指“封闭式”。"}, {"text": "这扇窗户是开放式的，所以冬天一直紧紧关着。", "explanation": "这里的“开放式”指可以进出、不关起来，句中却说窗户冬天一直紧紧关着，前后矛盾；此处应指“封闭式”。"}, {"text": "我的姐姐是开放式的人，喜欢和陌生人聊天。", "explanation": "这里应该用〈开朗〉。形容性格用“开朗”，“开放式”只形容空间、设施或方式，不用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22200, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开放式", "is_correct": true, "explanation": "“开放式”厨房不设墙，做饭时可以和家人聊天，与后句相合。"}, {"text": "密闭式", "is_correct": false, "explanation": "语义：“密闭式”厨房与外界隔绝，做饭时无法和家人聊天，与后句矛盾。"}, {"text": "关闭的", "is_correct": false, "explanation": "语义：“关闭的”厨房把人隔在里面，与“还能和家人聊天”冲突。"}, {"text": "闭塞的", "is_correct": false, "explanation": "语义：“闭塞”的厨房与外界隔绝，做饭时难以和家人聊天，与后句矛盾。"}], "explanations": {"开放式": "“开放式”厨房不设墙，做饭时可以和家人聊天，与后句相合。", "密闭式": "语义：“密闭式”厨房与外界隔绝，做饭时无法和家人聊天，与后句矛盾。", "关闭的": "语义：“关闭的”厨房把人隔在里面，与“还能和家人聊天”冲突。", "闭塞的": "语义：“闭塞”的厨房与外界隔绝，做饭时难以和家人聊天，与后句矛盾。"}, "sentence_index": 6, "correct_answer": "开放式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店是开放式的，门口却一直锁着，顾客根本进不去。", "explanation": "这里的“开放式”指可以进入、不关起来，句中却说门口一直锁着、顾客进不去，前后矛盾；此处应指“封闭式”。"}, {"text": "这家店的老板是开放式的人，什么事都愿意听顾客的。", "explanation": "这里应该用〈随和〉。形容人的脾气用“随和”，“开放式”只形容空间、设施或方式，不用于人。"}, {"text": "他的心胸是开放式的，见到不同的人都很友好。", "explanation": "这里应该用〈开阔〉。形容心胸用“开阔”，不用“开放式”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22200, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这间教室是开放式，学生随时可以进来。", "corrected_sentence": "这间教室是开放式的，学生随时可以进来。", "error_description": "“开放式”作谓语时后面要加“的”，应说“是开放式的”，不能说“是开放式”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22200, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家商场采用很开放式布局，顾客可以自由走动。", "corrected_sentence": "这家商场采用开放式布局，顾客可以自由走动。", "error_description": "“很”不能修饰“开放式”这类分类形容词，应说“采用开放式布局”，去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
