INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22202, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "电子音乐是用电脑和机器做出来的音乐。", "primary_collocate": null, "pronunciation": "diàn zǐ yīn yuè", "ipa": "tjɛn˥˩ tsɨ˨˩˦ in˥ ɥɛ˥˩", "syllable_count": 4, "sentences": [{"text": "电子音乐是用机器做出来的。", "target_word": "电子音乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我弟弟每天都听电子音乐。", "target_word": "电子音乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你喜欢摇滚还是电子音乐？", "target_word": "电子音乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首电子音乐没有人唱歌。", "target_word": "电子音乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用电脑做了一段电子音乐。", "target_word": "电子音乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跳舞的时候，大家爱听电子音乐。", "target_word": "电子音乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电子音乐听起来很有未来的感觉。", "target_word": "电子音乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们放了一首电子音乐。", "target_word": "电子音乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把电子音乐的声音开得很大。", "target_word": "电子音乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候我只听过古典音乐，没听过电子音乐。", "target_word": "电子音乐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一首电子音乐", "label": "量词"}, {"form": "一段电子音乐", "label": "量词"}, {"form": "電子音樂", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用电脑和机器做出来的音乐（通俗说法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71584119-e87a-4451-ae5e-3e7d6f74b1be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22202, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电子音乐", "is_correct": true, "explanation": "电子音乐是用电脑和机器做出来的音乐，与句中“机器做出来的”呼应。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海是自然形成的，不是机器做出来的。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情是人的情绪，不是用机器做出来的，与句意不符。"}, {"text": "春天", "is_correct": false, "explanation": "搭配：“做出来”的对象应是人造物，春天是季节，不能这样说。"}], "explanations": {"电子音乐": "电子音乐是用电脑和机器做出来的音乐，与句中“机器做出来的”呼应。", "大海": "语义：大海是自然形成的，不是机器做出来的。", "心情": "语义：心情是人的情绪，不是用机器做出来的，与句意不符。", "春天": "搭配：“做出来”的对象应是人造物，春天是季节，不能这样说。"}, "sentence_index": 0, "correct_answer": "电子音乐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位电子音乐是我的老师。", "explanation": "这里应该用〈老师〉。电子音乐是音乐，不是人，不能说是老师。"}, {"text": "这首电子音乐能帮我们洗衣服。", "explanation": "这里应该用〈机器〉。电子音乐是音乐作品，不能用来洗衣服，洗衣服的是机器。"}, {"text": "这首电子音乐有六根弦。", "explanation": "这里应该用〈吉他〉。电子音乐不是乐器，没有弦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22202, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电子音乐", "is_correct": true, "explanation": "电子音乐是听起来有未来感的音乐，主语可以是音乐，句意通顺。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是教学用书，不能“听起来”有某种感觉。"}, {"text": "饭菜", "is_correct": false, "explanation": "搭配：“听起来”的主语应是声音、音乐或说法，饭菜不能用“听起来”。"}, {"text": "运动鞋", "is_correct": false, "explanation": "语义：运动鞋是穿的东西，不能“听起来”有什么感觉。"}], "explanations": {"电子音乐": "电子音乐是听起来有未来感的音乐，主语可以是音乐，句意通顺。", "课本": "语义：课本是教学用书，不能“听起来”有某种感觉。", "饭菜": "搭配：“听起来”的主语应是声音、音乐或说法，饭菜不能用“听起来”。", "运动鞋": "语义：运动鞋是穿的东西，不能“听起来”有什么感觉。"}, "sentence_index": 6, "correct_answer": "电子音乐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一台新的电子音乐。", "explanation": "这里应该用〈电子产品〉。电子音乐是音乐，不是可以买的设备。"}, {"text": "这家餐厅的电子音乐很好吃。", "explanation": "这里应该用〈菜〉。电子音乐是用来听的，不能吃。"}, {"text": "那位厨师用电子音乐炒了一盘菜。", "explanation": "这里应该用〈食材〉。电子音乐是音乐作品，不能用来炒菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22202, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只电子音乐是他用电脑做的。", "corrected_sentence": "这首电子音乐是他用电脑做的。", "error_description": "量词错误：音乐作品应用“首”，“只”多用于动物或小件物品，应把“这只”改为“这首”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22202, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这首很好听电子音乐是我做的。", "corrected_sentence": "这首很好听的电子音乐是我做的。", "error_description": "修饰语与中心语之间漏了“的”：“很好听”修饰“电子音乐”时要加“的”，应为“很好听的电子音乐”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
