INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22204, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "频谱就像彩虹，它把声音或光分成不同部分，让我们看到它们有多少低的部分和高的部分。", "primary_collocate": null, "pronunciation": "pín pǔ", "ipa": "pʰin˧˥ pʰu˨˩˦", "syllable_count": 2, "sentences": [{"text": "频谱像彩虹一样，有很多部分。", "target_word": "频谱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张频谱显示声音的高低部分。", "target_word": "频谱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们用频谱来看声音有多低、多高。", "target_word": "频谱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "阳光经过水珠，就能看到光的频谱。", "target_word": "频谱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个频谱告诉我们低音很多。", "target_word": "频谱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在黑板上画了一个频谱。", "target_word": "频谱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看着频谱，找出了最高的声音。", "target_word": "频谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐的频谱里，低的部分特别多。", "target_word": "频谱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我第一次看到声音的频谱，觉得很有意思。", "target_word": "频谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机软件可以把你的声音变成频谱。", "target_word": "频谱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "频谱图", "label": "复合"}, {"form": "頻譜", "label": "繁体"}], "register": "书面", "sense_fingerprint": "把声音或光按高低分开来看的图（通俗比喻）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71584119-e87a-4451-ae5e-3e7d6f74b1be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22204, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "频谱", "is_correct": true, "explanation": "正确：频谱用彩虹作比喻，指按高低分开的声音或光的分布，符合句意。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱没有彩虹那样的色带分层，不能这样比喻。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：饺子没有彩虹的分层特点，“饺子像彩虹一样”不成立。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟没有彩虹那样的色带分层，不能这样比喻。"}], "explanations": {"频谱": "正确：频谱用彩虹作比喻，指按高低分开的声音或光的分布，符合句意。", "冰箱": "语义：冰箱没有彩虹那样的色带分层，不能这样比喻。", "饺子": "语义：饺子没有彩虹的分层特点，“饺子像彩虹一样”不成立。", "闹钟": "语义：闹钟没有彩虹那样的色带分层，不能这样比喻。"}, "sentence_index": 0, "correct_answer": "频谱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "阳光经过水珠，就能听到光的频谱。", "explanation": "这里应该用〈看到〉。频谱是图像，要用“看”，不能用“听”。"}, {"text": "这把频谱很有趣，我们一起来看。", "explanation": "量词用错：“把”用于有柄的器具，频谱是图像，应用“张”或“幅”。"}, {"text": "他把频谱吃进了肚子里。", "explanation": "频谱是抽象的图形或分布，不能吃；“吃”应搭配食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22204, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "频谱", "is_correct": true, "explanation": "正确：看频谱可以找出最高的声音，与句意相符。"}, {"text": "地图", "is_correct": false, "explanation": "语义：看地图不能找出声音的高低。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘不能显示声音的高低，与“找出最高的声音”无关。"}, {"text": "耳朵", "is_correct": false, "explanation": "搭配：找声音的高低要用“听”，“看耳朵”不能指找出声音。"}], "explanations": {"频谱": "正确：看频谱可以找出最高的声音，与句意相符。", "地图": "语义：看地图不能找出声音的高低。", "窗帘": "语义：窗帘不能显示声音的高低，与“找出最高的声音”无关。", "耳朵": "搭配：找声音的高低要用“听”，“看耳朵”不能指找出声音。"}, "sentence_index": 6, "correct_answer": "频谱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上喝一杯频谱，精神很好。", "explanation": "频谱是抽象的图形或分布，不能喝；“喝”应搭配饮品。"}, {"text": "这张频谱很清楚，我们一起找路吧。", "explanation": "这里应该用〈地图〉。找路要用地图，频谱是声音或光的强度分布，不能用来找路。"}, {"text": "我看着频谱弹钢琴。", "explanation": "这里应该用〈乐谱〉。弹钢琴要看乐谱，频谱是信号的频率分布，不用于演奏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22204, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只频谱像一幅彩色的画。", "corrected_sentence": "这张频谱像一幅彩色的画。", "error_description": "错误：“频谱”的量词用了“只”。正确：应为“这张频谱”。“只”多用于动物，“频谱”是图像，应用“张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22204, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他看了一块频谱，觉得很有意思。", "corrected_sentence": "他看了一张频谱，觉得很有意思。", "error_description": "错误：“频谱”的量词用了“块”。正确：应为“一张频谱”。“块”用于块状的东西，频谱是图像，应用“张”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
