INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22210, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做数学题或电脑工作时，一步一步做事情的方法。", "primary_collocate": null, "pronunciation": "suàn fǎ", "ipa": "swan˥˩ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "这道数学题有一个简单的算法。", "target_word": "算法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑按照算法一步一步工作。", "target_word": "算法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上写出了算法。", "target_word": "算法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个算法一共有五个步骤。", "target_word": "算法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想了一个更快的算法来算加法。", "target_word": "算法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李用新算法做完了这道题。", "target_word": "算法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做电脑游戏要先想好算法。", "target_word": "算法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看得懂这个算法吗？", "target_word": "算法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的算法太慢，电脑算了很久。", "target_word": "算法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "算法写错了，电脑没法工作。", "target_word": "算法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "新算法", "label": "复合词"}], "register": "中性", "sense_fingerprint": "算法：做题或电脑工作时一步一步的方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '287b9723-6463-4642-964d-9dfe8f414a1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22210, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "算法", "is_correct": true, "explanation": "正确：“算法”是解题的简单步骤，与“数学题”搭配，符合句意。"}, {"text": "口袋", "is_correct": false, "explanation": "语义：口袋是物件，不是解数学题的方法。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是用来挡雨的物品，与数学题无关。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，不能用来形容数学题的解法。"}], "explanations": {"算法": "正确：“算法”是解题的简单步骤，与“数学题”搭配，符合句意。", "口袋": "语义：口袋是物件，不是解数学题的方法。", "雨伞": "语义：雨伞是用来挡雨的物品，与数学题无关。", "身材": "体貌：“身材”指人的体形，不能用来形容数学题的解法。"}, "sentence_index": 0, "correct_answer": "算法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他想了一个好算法来减肥。", "explanation": "这里应该用〈方法〉。“算法”指计算或解题的步骤，减肥要用“方法”。"}, {"text": "这场比赛的算法很精彩，球迷看得津津有味。", "explanation": "这里应该用〈比赛〉。“算法”指解题或做事的步骤，不能用来形容比赛的精彩，要说比赛本身。"}, {"text": "这台机器的算法很厚。", "explanation": "这里应该用〈说明书〉。“算法”是抽象的步骤，不能用“厚”来形容，指纸质材料才用“厚”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22210, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "算法", "is_correct": true, "explanation": "正确：做游戏前要设计的是程序的算法，符合句意。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：午饭与做电脑游戏的设计工作无关。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是做游戏时需要事先设计的内容。"}, {"text": "饮料", "is_correct": false, "explanation": "搭配：“想好”一般接计划、方案、内容，与“饮料”搭配不当。"}], "explanations": {"算法": "正确：做游戏前要设计的是程序的算法，符合句意。", "午饭": "语义：午饭与做电脑游戏的设计工作无关。", "天气": "语义：天气不是做游戏时需要事先设计的内容。", "饮料": "搭配：“想好”一般接计划、方案、内容，与“饮料”搭配不当。"}, "sentence_index": 6, "correct_answer": "算法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家餐厅的算法很长，我看了半天。", "explanation": "这里应该用〈菜单〉。“算法”指解题或做事的步骤，餐厅列出菜品的单子要用菜单。"}, {"text": "妈妈在厨房里做了一道算法，全家都说好吃。", "explanation": "这里应该用〈菜〉。“算法”指解题或做事的步骤，做出来能吃的东西要用菜。"}, {"text": "他把这首歌的算法唱得很好听。", "explanation": "这里应该用〈旋律〉。“算法”指解题或做事的步骤，歌曲的音乐线条要用旋律。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22210, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张算法很实用。", "corrected_sentence": "这个算法很实用。", "error_description": "量词错误：“算法”不是扁平的纸张，不能用“张”，应用“个”或“种”。正确说法是“这个算法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22210, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于写了完这个算法。", "corrected_sentence": "他终于写完了这个算法。", "error_description": "补语错误：结果补语“完”应紧跟动词，说“写完了”，不能放在“了”后面说“写了完”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
