INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22212, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用来记歌的书", "primary_collocate": null, "pronunciation": "yuè pǔ", "ipa": "ɥe˥˩ pʰu˨˩˦", "syllable_count": 2, "sentences": [{"text": "他在书店买了一本新乐谱。", "target_word": "乐谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本乐谱里有二十首儿童歌曲。", "target_word": "乐谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把乐谱翻到第十页。", "target_word": "乐谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的钢琴老师借给她一本乐谱。", "target_word": "乐谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的乐谱放在钢琴上面。", "target_word": "乐谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本乐谱很厚，里面都是老歌。", "target_word": "乐谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆里有很多外国歌曲的乐谱。", "target_word": "乐谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他带着一本旧乐谱去教室练歌。", "target_word": "乐谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把乐谱忘在家里了。", "target_word": "乐谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本乐谱的纸已经发黄了。", "target_word": "乐谱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一本乐谱", "label": "量词"}, {"form": "樂譜", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一本记着歌曲的书", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '287b9723-6463-4642-964d-9dfe8f414a1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22212, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乐谱", "is_correct": true, "explanation": "乐谱：一本印有歌曲的书，量词用“本”，书店可以买到。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：钢琴的量词是“架”，不说一本钢琴。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：书店不卖咖啡，咖啡也不是“本”能计量的东西。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：电脑的量词是“台”，不说一本电脑。"}], "explanations": {"乐谱": "乐谱：一本印有歌曲的书，量词用“本”，书店可以买到。", "钢琴": "搭配：钢琴的量词是“架”，不说一本钢琴。", "咖啡": "语义：书店不卖咖啡，咖啡也不是“本”能计量的东西。", "电脑": "搭配：电脑的量词是“台”，不说一本电脑。"}, "sentence_index": 0, "correct_answer": "乐谱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的钢琴老师借给她一只乐谱。", "explanation": "这里应该用〈本〉。乐谱是书册，用“本”计量；“只”用于动物或成对物品中的一个。"}, {"text": "她的钢琴老师借给她一把乐谱。", "explanation": "这里应该用〈本〉。“把”用于有柄的器具，不能用于乐谱。"}, {"text": "她的钢琴老师借给她一棵乐谱。", "explanation": "这里应该用〈本〉。“棵”用于植物，不能用于乐谱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22212, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乐谱", "is_correct": true, "explanation": "乐谱：图书馆里能借到的、印有外国歌曲的书，与句意相合。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料不是可以在图书馆里收藏的外国歌曲材料，与句意不合。"}, {"text": "菜单", "is_correct": false, "explanation": "语义：菜单上列的是菜品，与外国歌曲无关。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：外国歌曲不搭配冰箱，二者不能构成“……的”修饰关系。"}], "explanations": {"乐谱": "乐谱：图书馆里能借到的、印有外国歌曲的书，与句意相合。", "饮料": "语义：饮料不是可以在图书馆里收藏的外国歌曲材料，与句意不合。", "菜单": "语义：菜单上列的是菜品，与外国歌曲无关。", "冰箱": "搭配：外国歌曲不搭配冰箱，二者不能构成“……的”修饰关系。"}, "sentence_index": 6, "correct_answer": "乐谱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台乐谱的纸已经发黄了。", "explanation": "这里应该用〈本〉。“台”用于机器、电器等，不能用于乐谱。"}, {"text": "我一口气读完了那块乐谱。", "explanation": "这里应该用〈本〉。“块”多用于块状物，乐谱是书册，不能用“块”计量。"}, {"text": "图书馆的那座乐谱很厚。", "explanation": "这里应该用〈本〉。“座”用于山、桥、建筑等，不能用于乐谱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22212, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师送了我一首乐谱。", "corrected_sentence": "老师送了我一本乐谱。", "error_description": "量词错误：乐谱是书册，应用“本”，不能用“首”。错误形式：送了我一首乐谱；正确形式：送了我一本乐谱。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22212, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把两双乐谱放进了书包。", "corrected_sentence": "我把两本乐谱放进了书包。", "error_description": "量词错误：乐谱应用“本”，“双”指成对的东西，不能用于乐谱。错误形式：两双乐谱；正确形式：两本乐谱。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22216, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "破坏", "is_correct": true, "explanation": "破坏与创造相反，指使事物受损或毁坏，二者构成反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "散步与创造没有反义关系，二者意义无关。"}, {"text": "吃饭", "is_correct": false, "explanation": "吃饭与创造没有反义关系，二者意义无关。"}, {"text": "游泳", "is_correct": false, "explanation": "游泳与创造没有反义关系，二者意义无关。"}], "correct_answer": "破坏", "explanations": {"破坏": "破坏与创造相反，指使事物受损或毁坏，二者构成反义关系。", "散步": "散步与创造没有反义关系，二者意义无关。", "吃饭": "吃饭与创造没有反义关系，二者意义无关。", "游泳": "游泳与创造没有反义关系，二者意义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22216, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "毁灭", "is_correct": true, "explanation": "毁灭与创造相反，指使事物彻底消失，二者构成反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "跑步与创造没有反义关系，二者意义无关。"}, {"text": "读书", "is_correct": false, "explanation": "读书与创造没有反义关系，二者意义无关。"}, {"text": "画画", "is_correct": false, "explanation": "画画与创造没有反义关系，只是与画家的语境有关。"}], "correct_answer": "毁灭", "explanations": {"毁灭": "毁灭与创造相反，指使事物彻底消失，二者构成反义关系。", "跑步": "跑步与创造没有反义关系，二者意义无关。", "读书": "读书与创造没有反义关系，二者意义无关。", "画画": "画画与创造没有反义关系，只是与画家的语境有关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22216, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做出以前没有的新东西。", "primary_collocate": null, "pronunciation": "chuàng zào", "ipa": "/ʈʂʰuɑŋ˥˩ tsɑʊ˥˩/", "syllable_count": 2, "sentences": [{"text": "这位画家创造了一种新的画法。", "target_word": "创造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们用纸创造出很多有意思的玩具。", "target_word": "创造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的老师能给学生创造学习的机会。", "target_word": "创造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人创造了公司的第一个产品。", "target_word": "创造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱迪生创造了很多有用的东西。", "target_word": "创造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些工人为城市创造了很多财富。", "target_word": "创造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想创造一个没有烦恼的新世界。", "target_word": "创造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友们在课上创造了一首新歌。", "target_word": "创造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要自己创造好的生活。", "target_word": "创造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他创造过三次世界纪录。", "target_word": "创造", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "创造了", "label": "体标：完成"}, {"form": "创造过", "label": "体标：经历"}, {"form": "创造力", "label": "复合"}], "register": "中性", "sense_fingerprint": "做出以前没有的新事物、新成绩或新条件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa75729c-4fdb-4353-ab48-5298e7732270') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22216, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "创造", "is_correct": true, "explanation": "正确：「创造」表示做出以前没有的新画法，与「一种新的画法」相合。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」的对象是食物，不能说吃画法。"}, {"text": "参观", "is_correct": false, "explanation": "语义：「参观」指去看地点或展览，不能用来指画家做出画法。"}, {"text": "继承", "is_correct": false, "explanation": "语义：「继承」指接受前人留下的东西，与「新的画法」矛盾。"}], "explanations": {"创造": "正确：「创造」表示做出以前没有的新画法，与「一种新的画法」相合。", "吃": "搭配：「吃」的对象是食物，不能说吃画法。", "参观": "语义：「参观」指去看地点或展览，不能用来指画家做出画法。", "继承": "语义：「继承」指接受前人留下的东西，与「新的画法」矛盾。"}, "sentence_index": 0, "correct_answer": "创造"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂每天创造一千辆汽车。", "explanation": "这里应该用〈制造〉。「创造」强调做出以前没有的东西，大批量生产同类产品要用「制造」。"}, {"text": "学校创造了一场足球比赛。", "explanation": "这里应该用〈举办〉。「创造」指做出新事物，比赛这类活动要用「举办」。"}, {"text": "妈妈创造了一桌家常菜。", "explanation": "这里应该用〈做〉。「创造」偏重做出前所未有的东西，日常做饭用「做」即可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22216, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "创造", "is_correct": true, "explanation": "正确：「创造」指建立前所未有的新事物，与「一个新世界」相合。"}, {"text": "买", "is_correct": false, "explanation": "搭配：「买」的对象是可以买卖的东西，世界不能买。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：「煮」的对象是食物或液体，世界不能煮。"}, {"text": "拆", "is_correct": false, "explanation": "语义：「拆」指拆开或拆毁具体物品，与「新世界」不合。"}], "explanations": {"创造": "正确：「创造」指建立前所未有的新事物，与「一个新世界」相合。", "买": "搭配：「买」的对象是可以买卖的东西，世界不能买。", "煮": "搭配：「煮」的对象是食物或液体，世界不能煮。", "拆": "语义：「拆」指拆开或拆毁具体物品，与「新世界」不合。"}, "sentence_index": 6, "correct_answer": "创造"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次台风创造了很大的损失。", "explanation": "这里应该用〈造成〉。「创造」指有意做出好的新东西，不说「创造损失」；造成不好的结果要用「造成」。"}, {"text": "他在新学校创造了很多朋友。", "explanation": "这里应该用〈结交〉。「创造」不用于人际关系，交朋友要用「结交」。"}, {"text": "这支球队创造了观众的喜爱。", "explanation": "这里应该用〈赢得〉。「创造」针对做出的事物，观众的喜爱要用「赢得」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22216, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司创造了出很多工作机会。", "corrected_sentence": "这家公司创造出了很多工作机会。", "error_description": "错误形式「创造了出」：补语「出」应紧接动词，「了」放在补语之后，正确形式为「创造出了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22216, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个团队创造了过一种新的治疗方法。", "corrected_sentence": "这个团队创造过一种新的治疗方法。", "error_description": "错误形式「创造了过」：「了」与「过」不能同时加在同一个动词后，正确形式为「创造过」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
