INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22224, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "写一首歌或一段音乐。", "primary_collocate": null, "pronunciation": "zuò qǔ", "ipa": "tswɔ˥˩ tɕʰy˨˩˦", "syllable_count": 2, "sentences": [{"text": "我哥哥会弹吉他，也会作曲。", "target_word": "作曲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想为妈妈的生日作曲。", "target_word": "作曲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天晚上在家作曲，已经有三首新歌了。", "target_word": "作曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌是谁作曲的？", "target_word": "作曲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不会作曲，只会唱歌。", "target_word": "作曲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明想自己作曲，送给同学一首歌。", "target_word": "作曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作曲很难，他试了一个星期才完成。", "target_word": "作曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友帮我写词，我自己作曲。", "target_word": "作曲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她晚上坐在钢琴前作曲，常常一坐就是几个小时。", "target_word": "作曲", "complexity_tier": "T3", "furigana": "tā wǎnshàng zuò zài gāngqín qián zuòqǔ chángcháng yí zuò jiù shì jǐ gè xiǎoshí", "sentence_source": "generated"}, {"text": "他想学习作曲，然后写自己的音乐。", "target_word": "作曲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "作曲家", "label": "复合"}, {"form": "作曲了", "label": "体标"}, {"form": "作曲过", "label": "体标"}], "register": "中性", "sense_fingerprint": "作曲|写一首歌或一段音乐", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a267b60a-1885-4776-a101-f0f8d7d64538') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22224, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作曲", "is_correct": true, "explanation": "正确。“会弹吉他，也会作曲”说的是音乐方面的技能，与句意相符。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”不是人学会的技能，与“会弹吉他”并列不通。"}, {"text": "倒闭", "is_correct": false, "explanation": "搭配：“倒闭”的主语是企业或店铺，不能用于人。"}, {"text": "降落", "is_correct": false, "explanation": "语义：“降落”指飞机或物体落地，不是人的技能。"}], "explanations": {"作曲": "正确。“会弹吉他，也会作曲”说的是音乐方面的技能，与句意相符。", "出生": "语义：“出生”不是人学会的技能，与“会弹吉他”并列不通。", "倒闭": "搭配：“倒闭”的主语是企业或店铺，不能用于人。", "降落": "语义：“降落”指飞机或物体落地，不是人的技能。"}, "sentence_index": 0, "correct_answer": "作曲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的歌词是他作曲的。", "explanation": "这里应该用〈写词〉。作曲负责旋律，歌词要用“写词”，“作曲”不能指写歌词。"}, {"text": "这篇小说是他作曲的。", "explanation": "这里应该用〈写作〉。作曲指创作乐曲，不能用于小说。"}, {"text": "这幅画是谁作曲的？", "explanation": "这里应该用〈绘〉。作曲指创作乐曲，画作要用“绘”，“作曲”不能用于画作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22224, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作曲", "is_correct": true, "explanation": "正确。“作曲很难，他试了一个星期才完成”说的是一项需要完成的工作，符合句意。"}, {"text": "呼吸", "is_correct": false, "explanation": "搭配：“完成”需要有任务或工作作宾语，“呼吸”不是可以完成的事，两者不搭配。"}, {"text": "降雨", "is_correct": false, "explanation": "语义：“降雨”是自然现象，不是需要“试一个星期才完成”的事。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”不是有待完成的任务，与“试了一个星期才完成”不合。"}], "explanations": {"作曲": "正确。“作曲很难，他试了一个星期才完成”说的是一项需要完成的工作，符合句意。", "呼吸": "搭配：“完成”需要有任务或工作作宾语，“呼吸”不是可以完成的事，两者不搭配。", "降雨": "语义：“降雨”是自然现象，不是需要“试一个星期才完成”的事。", "生病": "语义：“生病”不是有待完成的任务，与“试了一个星期才完成”不合。"}, "sentence_index": 6, "correct_answer": "作曲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他作曲了一面墙。", "explanation": "这里应该用〈粉刷〉。作曲的对象是乐曲，不能用于墙。"}, {"text": "她作曲了一个句子。", "explanation": "这里应该用〈造〉。作曲的对象是乐曲，句子不能用“作曲”。"}, {"text": "他作曲了一座桥。", "explanation": "这里应该用〈修〉。作曲的对象是乐曲，桥梁不能用“作曲”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22224, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这首歌是我作曲了的。", "corrected_sentence": "这首歌是我作曲的。", "error_description": "体标错误：“是……的”结构强调已完成的动作，其中不能再加“了”，应说“这首歌是我作曲的”，不说“这首歌是我作曲了的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22224, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她作曲得很快。", "corrected_sentence": "她作曲作得很快。", "error_description": "补语错误：“作曲”是动宾式，带“得”补语时要重复动词，说成“作曲作得很快”，不能说“作曲得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
