INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22230, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指在学校里学习并遵循正式规则和方法的群体。", "primary_collocate": null, "pronunciation": "xué yuàn pài", "ipa": "ɕɥɛ˧˥ ɥɛn˥˩ pʰaɪ˥˩", "syllable_count": 3, "sentences": [{"text": "学院派的学生每天按课表上课，也要考试。", "target_word": "学院派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是学院派，是自己在家学会弹琴的。", "target_word": "学院派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学院派先学基础规则，然后才开始创作。", "target_word": "学院派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学院派的同学都很守规矩，按老师的方法练习。", "target_word": "学院派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边的歌手不是学院派，没有进过音乐学校。", "target_word": "学院派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在班里，学院派和自学的人常常讨论练习方法。", "target_word": "学院派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学院派一般要在学校学好几年才毕业。", "target_word": "学院派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小进音乐学院，是真正的学院派。", "target_word": "学院派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学院派的做法是先按正式方法一步一步学。", "target_word": "学院派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她没有上过美术学院，所以不算学院派。", "target_word": "学院派", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "學院派", "label": "繁体"}], "register": "中性", "sense_fingerprint": "学院派|在学校按正式规则学习的人群", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a267b60a-1885-4776-a101-f0f8d7d64538') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22230, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学院派", "is_correct": true, "explanation": "正确。学院派指在学校按正式规则学习的人，与“每天按课表上课，也要考试”相符。"}, {"text": "自学派", "is_correct": false, "explanation": "语义：自学的人不按课表上课，与后半句“每天按课表上课”相矛盾。"}, {"text": "街头派", "is_correct": false, "explanation": "语义：街头派指不进学校、在街头积累经验的人，与“按课表上课，也要考试”不合。"}, {"text": "野路子", "is_correct": false, "explanation": "语域：“野路子”是口语说法，带有随意色彩，且与“按课表上课”的正式学习方式矛盾。"}], "explanations": {"学院派": "正确。学院派指在学校按正式规则学习的人，与“每天按课表上课，也要考试”相符。", "自学派": "语义：自学的人不按课表上课，与后半句“每天按课表上课”相矛盾。", "街头派": "语义：街头派指不进学校、在街头积累经验的人，与“按课表上课，也要考试”不合。", "野路子": "语域：“野路子”是口语说法，带有随意色彩，且与“按课表上课”的正式学习方式矛盾。"}, "sentence_index": 0, "correct_answer": "学院派"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学院派不按老师的方法，常常自己琢磨练习。", "explanation": "这里应该用〈自学者〉。学院派指按正式规则和老师方法学习的人，与“不按老师的方法”相反。"}, {"text": "学院派的同学不爱按老规矩办事，喜欢自己摸索。", "explanation": "这里应该用〈自由派〉。学院派遵守正式规则，“不爱按老规矩办事”应说自由派。"}, {"text": "她讲课总是即兴发挥，不讲规则，属于学院派。", "explanation": "这里应该用〈先锋派〉。学院派指遵循正式规则和方法的群体，“即兴发挥、不讲规则”应说先锋派。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22230, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学院派", "is_correct": true, "explanation": "正确。学院派指在学校学习的人，“一般要在学校学好几年才毕业”正是其特点。"}, {"text": "速成派", "is_correct": false, "explanation": "语义：速成派强调短期突击，与“学好几年才毕业”的时间跨度相矛盾。"}, {"text": "旁听生", "is_correct": false, "explanation": "语义：旁听生不参加正式考核，不能“学好几年才毕业”。"}, {"text": "研究所", "is_correct": false, "explanation": "搭配：“毕业”的主语应是人，“研究所”不能毕业。"}], "explanations": {"学院派": "正确。学院派指在学校学习的人，“一般要在学校学好几年才毕业”正是其特点。", "速成派": "语义：速成派强调短期突击，与“学好几年才毕业”的时间跨度相矛盾。", "旁听生": "语义：旁听生不参加正式考核，不能“学好几年才毕业”。", "研究所": "搭配：“毕业”的主语应是人，“研究所”不能毕业。"}, "sentence_index": 6, "correct_answer": "学院派"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学院派歌手从不看乐谱，全靠耳朵。", "explanation": "这里应该用〈草根〉。学院派指在学校里按正式方法学习的人，“全靠耳朵、不看乐谱”应说草根。"}, {"text": "学院派画家没有正式学过画，只凭兴趣画画。", "explanation": "这里应该用〈业余〉。学院派指在学校里正式学习的人，“没有正式学过画”应说业余。"}, {"text": "学院派乐手从不遵守正式规则，喜欢即兴创作。", "explanation": "这里应该用〈街头派〉。学院派指遵循正式规则学习的群体，“从不遵守正式规则”应说街头派。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22230, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她按学院派地规矩学钢琴。", "corrected_sentence": "她按学院派的规矩学钢琴。", "error_description": "结构错误：“学院派”修饰名词“规矩”时应用“的”，不用“地”。应改为“她按学院派的规矩学钢琴”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22230, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一只学院派，常年练琴。", "corrected_sentence": "他是一位学院派，常年练琴。", "error_description": "量词错误：指人的“学院派”不用“只”（“只”多用于动物），应用“位”或“个”。应改为“他是一位学院派，常年练琴。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
