INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22236, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西变得更大或更多。", "primary_collocate": null, "pronunciation": "tuò zhǎn", "ipa": "tʰuɔ˥˩ ʈʂan˨˩˦", "syllable_count": 2, "sentences": [{"text": "公司想拓展海外的生意。", "target_word": "拓展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要拓展新的市场。", "target_word": "拓展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多读书可以拓展知识面。", "target_word": "拓展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司计划拓展全国的销售网络。", "target_word": "拓展", "complexity_tier": "T3", "furigana": "zhè jiā gōngsī jìhuà tuòzhǎn quánguó de xiāoshòu wǎngluò", "sentence_source": "generated"}, {"text": "老师带孩子去旅行，拓展他们的眼界。", "target_word": "拓展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想拓展自己的朋友圈。", "target_word": "拓展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店准备拓展到别的城市。", "target_word": "拓展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园又拓展了一大块地方。", "target_word": "拓展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学外语能拓展工作机会。", "target_word": "拓展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了拓展业务，经理常常出差。", "target_word": "拓展", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拓展了", "label": "完成体"}, {"form": "拓展过", "label": "经历体"}, {"form": "拓展训练", "label": "复合"}, {"form": "拓展", "label": "繁体与简体相同"}], "register": "书面", "sense_fingerprint": "使范围、空间、业务等变大变多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77d97711-45c9-40d1-a540-071631f184cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22236, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拓展", "is_correct": true, "explanation": "正确：拓展指范围、业务向外扩大，与「海外的生意」搭配自然。"}, {"text": "咬", "is_correct": false, "explanation": "语义：「咬」是咬东西的动作，不能指生意的开展。"}, {"text": "喝", "is_correct": false, "explanation": "语义：「喝」不能用于生意，与语境不符。"}, {"text": "睡", "is_correct": false, "explanation": "配价：「睡」是不及物动词，不能带宾语「海外的生意」。"}], "explanations": {"拓展": "正确：拓展指范围、业务向外扩大，与「海外的生意」搭配自然。", "咬": "语义：「咬」是咬东西的动作，不能指生意的开展。", "喝": "语义：「喝」不能用于生意，与语境不符。", "睡": "配价：「睡」是不及物动词，不能带宾语「海外的生意」。"}, "sentence_index": 0, "correct_answer": "拓展"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今年公司拓展了三十名员工。", "explanation": "这里应该用〈增加〉。拓展指范围、业务向外扩大，人数变多要用增加。"}, {"text": "这家餐厅拓展了一盘青菜，味道很好。", "explanation": "这里应该用〈炒〉。拓展指范围、业务向外扩大，烹制青菜要用炒。"}, {"text": "这种药能拓展病人的寿命。", "explanation": "这里应该用〈延长〉。拓展指空间、范围、业务的扩大，寿命的增加要用延长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc650faf-eef1-4b87-8649-678eec955448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22236, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拓展", "is_correct": true, "explanation": "正确：拓展表示扩展到别的地方，与「到别的城市」搭配自然。"}, {"text": "吃", "is_correct": false, "explanation": "语义：「吃」不能表示把业务扩展到某个城市，与语境不符。"}, {"text": "讨论", "is_correct": false, "explanation": "配价：「讨论」要带议题作宾语，不能带「到别的城市」这样的方向补语。"}, {"text": "笑", "is_correct": false, "explanation": "语义：「笑」是表情动作，不能表示把店铺扩展到别的城市。"}], "explanations": {"拓展": "正确：拓展表示扩展到别的地方，与「到别的城市」搭配自然。", "吃": "语义：「吃」不能表示把业务扩展到某个城市，与语境不符。", "讨论": "配价：「讨论」要带议题作宾语，不能带「到别的城市」这样的方向补语。", "笑": "语义：「笑」是表情动作，不能表示把店铺扩展到别的城市。"}, "sentence_index": 6, "correct_answer": "拓展"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这两年拓展了十厘米。", "explanation": "这里应该用〈长高〉。拓展用于范围、业务，人的身高增长要说长高。"}, {"text": "他把音量拓展了一点，邻居都听见了。", "explanation": "这里应该用〈调大〉。拓展用于范围和业务，音量的增大要说调大。"}, {"text": "他拓展了走路的速度，一下子就到了学校。", "explanation": "这里应该用〈加快〉。拓展指范围、业务向外扩大，速度变快要说加快。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc650faf-eef1-4b87-8649-678eec955448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22236, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司已经拓展得海外市场。", "corrected_sentence": "公司已经拓展了海外市场。", "error_description": "助词错误：“拓展”后应接完成体“了”，写成“拓展得”不通顺，应改为“拓展了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc650faf-eef1-4b87-8649-678eec955448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22236, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们准备拓展在更多的城市。", "corrected_sentence": "我们准备拓展到更多的城市。", "error_description": "「拓展在」错误，应改为「拓展到」。表示扩展到某地要用介词「到」引出方向补语，「在」不能接在「拓展」后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc650faf-eef1-4b87-8649-678eec955448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
