INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22238, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很多人一起演奏音乐的大队伍。", "primary_collocate": null, "pronunciation": "jiāo xiǎng yuè tuán", "ipa": "tɕjɑʊ˥ ɕjɑŋ˨˩˦ ɥe˥˩ tʰwan˧˥", "syllable_count": 4, "sentences": [{"text": "学校的交响乐团有八十个学生。", "target_word": "交响乐团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "交响乐团的人很多，所以台上坐得满满的。", "target_word": "交响乐团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们交响乐团每周三下午排练。", "target_word": "交响乐团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "交响乐团一起演奏时，声音特别大。", "target_word": "交响乐团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是交响乐团里最年轻的鼓手。", "target_word": "交响乐团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们坐在台下，看交响乐团演奏。", "target_word": "交响乐团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个交响乐团的人来自不同的国家。", "target_word": "交响乐团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "交响乐团要演出了，大家都穿着黑衣服。", "target_word": "交响乐团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明的妈妈在一个交响乐团拉大提琴。", "target_word": "交响乐团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听着交响乐团的演奏，我觉得很放松。", "target_word": "交响乐团", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个交响乐团", "label": "量词"}, {"form": "交響樂團", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很多人一起演奏音乐的大队伍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '287b9723-6463-4642-964d-9dfe8f414a1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22238, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交响乐团", "is_correct": true, "explanation": "交响乐团是由很多人组成的团体，学校的交响乐团有八十个学生参加，句意成立。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是借阅场所，不是由学生组成的团体，不能说它有八十个学生。"}, {"text": "车队", "is_correct": false, "explanation": "语义：车队是车辆组成的队伍，学生不能组成车队，句中不说车队有八十个学生。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器是器具，本身不是由学生组成的团体，句中不能说乐器有八十个学生。"}], "explanations": {"交响乐团": "交响乐团是由很多人组成的团体，学校的交响乐团有八十个学生参加，句意成立。", "图书馆": "语义：图书馆是借阅场所，不是由学生组成的团体，不能说它有八十个学生。", "车队": "语义：车队是车辆组成的队伍，学生不能组成车队，句中不说车队有八十个学生。", "乐器": "语义：乐器是器具，本身不是由学生组成的团体，句中不能说乐器有八十个学生。"}, "sentence_index": 0, "correct_answer": "交响乐团"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "交响乐团一起唱歌时，声音特别大。", "explanation": "这里应该用〈合唱团〉。交响乐团以器乐演奏为主，不靠歌唱，说它一起唱歌不对。"}, {"text": "交响乐团的演员一起上台，观众都笑了。", "explanation": "这里应该用〈剧团〉。交响乐团的成员是乐手，不是演员，一起上台演出戏剧要用剧团。"}, {"text": "交响乐团的舞者一起跳舞，动作很整齐。", "explanation": "这里应该用〈歌舞团〉。交响乐团的成员是演奏乐器的乐手，不跳舞，舞者要在歌舞团里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22238, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交响乐团", "is_correct": true, "explanation": "交响乐团的成员来自不同国家，“这个交响乐团的人来自不同的国家”句意成立。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是有人组成的团体，“冰箱的人来自不同的国家”说不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是矿物，不会有“来自不同国家的人”。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指个人的体形，不能用来修饰一群人。"}], "explanations": {"交响乐团": "交响乐团的成员来自不同国家，“这个交响乐团的人来自不同的国家”句意成立。", "冰箱": "语义：冰箱不是有人组成的团体，“冰箱的人来自不同的国家”说不通。", "石头": "语义：石头是矿物，不会有“来自不同国家的人”。", "身材": "体貌：“身材”指个人的体形，不能用来修饰一群人。"}, "sentence_index": 6, "correct_answer": "交响乐团"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个交响乐团的导游每天带着游客逛古城。", "explanation": "这里应该用〈旅行团〉。交响乐团是演奏乐器的乐团，没有导游带游客逛景点；带团逛古城要用旅行团。"}, {"text": "这个交响乐团的队员在球场上踢进了两个球。", "explanation": "这里应该用〈球队〉。交响乐团的成员是演奏乐器的乐手，不在球场踢球；踢球比赛的队伍要用球队。"}, {"text": "这个交响乐团的小丑每天在广场上表演杂技。", "explanation": "这里应该用〈马戏团〉。交响乐团靠演奏乐器，不表演小丑和杂技；这类表演要用马戏团。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22238, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校刚成立了一座交响乐团。", "corrected_sentence": "学校刚成立了一个交响乐团。", "error_description": "量词错误：“交响乐团”是团体，应该用“个”；“座”用于山、楼这类大型固定物，不能用来数乐团。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22238, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的表哥在一条交响乐团里吹小号。", "corrected_sentence": "我的表哥在一个交响乐团里吹小号。", "error_description": "量词错误：“交响乐团”是团体，应该用“个”；“条”用于细长的东西，不能用来数乐团。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
