INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22240, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示一件事经常发生，次数多，不是偶尔才发生。", "primary_collocate": null, "pronunciation": "cháng", "ipa": "tʂʰɑŋ³⁵", "syllable_count": 1, "sentences": [{"text": "我常去那家饭馆吃饭。", "target_word": "常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不常看电视。", "target_word": "常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我常和朋友一起跑步。", "target_word": "常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她常给妈妈打电话。", "target_word": "常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候我常在河边玩。", "target_word": "常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里冬天常下雪。", "target_word": "常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你常来这儿吗?", "target_word": "常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师常说,要多读书。", "target_word": "常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他常忘记带钥匙。", "target_word": "常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们常在一起学习汉语。", "target_word": "常", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "常常", "label": "重叠"}, {"form": "不常", "label": "否定"}], "register": "中性", "sense_fingerprint": "动作或事情经常发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fef3691-c05f-4979-b766-4af9a742d3ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22240, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "常", "is_correct": true, "explanation": "正确：常（cháng），副词，表示动作或事情经常发生。"}, {"text": "厂", "is_correct": false, "explanation": "厂（chǎng）与常（cháng）声调不同（第三声与第二声），意思是工厂。"}, {"text": "唱", "is_correct": false, "explanation": "唱（chàng）与常（cháng）声调不同（第四声与第二声），意思是唱歌。"}, {"text": "场", "is_correct": false, "explanation": "场（chǎng）与常（cháng）声调不同（第三声与第二声），意思是场地。"}, {"text": "长", "is_correct": false, "explanation": "长（zhǎng）与常（cháng）声母不同（zh 与 ch），声调也不同，意思是生长。"}, {"text": "产", "is_correct": false, "explanation": "产（chǎn）与常（cháng）韵母不同（an 与 ang），声调也不同，意思是生产。"}], "explanations": {"常": "正确：常（cháng），副词，表示动作或事情经常发生。", "厂": "厂（chǎng）与常（cháng）声调不同（第三声与第二声），意思是工厂。", "唱": "唱（chàng）与常（cháng）声调不同（第四声与第二声），意思是唱歌。", "场": "场（chǎng）与常（cháng）声调不同（第三声与第二声），意思是场地。", "长": "长（zhǎng）与常（cháng）声母不同（zh 与 ch），声调也不同，意思是生长。", "产": "产（chǎn）与常（cháng）韵母不同（an 与 ang），声调也不同，意思是生产。"}, "sentence_index": null, "correct_answer": "常"}, "level_3": {"options": [{"text": "常", "is_correct": true, "explanation": "正确：“常”表示经常，符合“去那家饭馆吃饭”这类习惯性动作。"}, {"text": "竟", "is_correct": false, "explanation": "语义：“竟”表示出乎意料，句中说的是平常去饭馆吃饭，没有惊讶之意。"}, {"text": "却", "is_correct": false, "explanation": "语义：“却”表示转折，前文没有需要转折的内容，句子读起来不通顺。"}, {"text": "乃", "is_correct": false, "explanation": "语域：“乃”是文言用法，口语里不用，与“去饭馆吃饭”的口语语气不协调。"}], "explanations": {"常": "正确：“常”表示经常，符合“去那家饭馆吃饭”这类习惯性动作。", "竟": "语义：“竟”表示出乎意料，句中说的是平常去饭馆吃饭，没有惊讶之意。", "却": "语义：“却”表示转折，前文没有需要转折的内容，句子读起来不通顺。", "乃": "语域：“乃”是文言用法，口语里不用，与“去饭馆吃饭”的口语语气不协调。"}, "sentence_index": 0, "correct_answer": "常"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他常来，一年才来一次。", "explanation": "这里应该用〈很少〉。“常”表示经常，与“一年才来一次”的意思矛盾。"}, {"text": "我常喝咖啡，平时只喝茶。", "explanation": "这里应该用〈偶尔〉。“常”表示经常，与“平时只喝茶”的习惯相矛盾。"}, {"text": "我们常是好朋友。", "explanation": "这里应该用〈一直〉。“常”表示反复发生，用于动作；“是好朋友”是持续的状态，应用“一直”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22240, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "常", "is_correct": true, "explanation": "正确：常（cháng），副词，表示动作或事情经常发生。"}, {"text": "城", "is_correct": false, "explanation": "城（chéng）与常（cháng）韵母不同（eng 与 ang），声调相同，意思是城市。"}, {"text": "成", "is_correct": false, "explanation": "成（chéng）与常（cháng）韵母不同（eng 与 ang），声调相同，意思是完成。"}, {"text": "晨", "is_correct": false, "explanation": "晨（chén）与常（cháng）韵母不同（en 与 ang），声调相同，意思是早晨。"}, {"text": "程", "is_correct": false, "explanation": "程（chéng）与常（cháng）韵母不同（eng 与 ang），声调相同，意思是过程。"}, {"text": "陈", "is_correct": false, "explanation": "陈（chén）与常（cháng）韵母不同（en 与 ang），声调相同，意思是陈旧。"}], "explanations": {"常": "正确：常（cháng），副词，表示动作或事情经常发生。", "城": "城（chéng）与常（cháng）韵母不同（eng 与 ang），声调相同，意思是城市。", "成": "成（chéng）与常（cháng）韵母不同（eng 与 ang），声调相同，意思是完成。", "晨": "晨（chén）与常（cháng）韵母不同（en 与 ang），声调相同，意思是早晨。", "程": "程（chéng）与常（cháng）韵母不同（eng 与 ang），声调相同，意思是过程。", "陈": "陈（chén）与常（cháng）韵母不同（en 与 ang），声调相同，意思是陈旧。"}, "sentence_index": null, "correct_answer": "常"}, "level_3": {"options": [{"text": "常", "is_correct": true, "explanation": "正确：“常”表示经常，用于询问对方是否习惯性地来这里。"}, {"text": "必", "is_correct": false, "explanation": "搭配：“必”表示必然或必要，用在询问习惯性动作的疑问句中不自然。"}, {"text": "已", "is_correct": false, "explanation": "语域：“已”是书面用法，口语问“来这儿吗”不用“已”，句意也不合。"}, {"text": "尚", "is_correct": false, "explanation": "语域：“尚”是文言用法，口语不用，与询问习惯的口语句子不协调。"}], "explanations": {"常": "正确：“常”表示经常，用于询问对方是否习惯性地来这里。", "必": "搭配：“必”表示必然或必要，用在询问习惯性动作的疑问句中不自然。", "已": "语域：“已”是书面用法，口语问“来这儿吗”不用“已”，句意也不合。", "尚": "语域：“尚”是文言用法，口语不用，与询问习惯的口语句子不协调。"}, "sentence_index": 6, "correct_answer": "常"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们常在一起学习汉语，一学期才学一次。", "explanation": "这里应该用〈偶尔〉。“常”表示经常，与“一学期才学一次”的意思矛盾。"}, {"text": "明天我们常去图书馆。", "explanation": "这里应该用〈要〉。“常”表示反复发生，“明天”指向的是一次性的将来行为，不能用“常”。"}, {"text": "我常知道这件事的原因。", "explanation": "这里应该用〈早就〉。“常”表示反复发生，“知道”是已经形成的状态，应用“早就”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22240, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我常很去公园散步。", "corrected_sentence": "我常去公园散步。", "error_description": "错误：程度副词“很”用于修饰形容词，不能放在动词“去”之前。“常”后面直接接动词，中间不加“很”。正确应为“我常去公园散步”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22240, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈很常去市场买菜。", "corrected_sentence": "妈妈常去市场买菜。", "error_description": "“常”是副词，不能被“很”修饰。“很常去”错误，应为“常去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22242, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "歪", "is_correct": true, "explanation": "歪：与“正”的“不偏斜”义互为反义，指物体偏向一侧。"}, {"text": "亮", "is_correct": false, "explanation": "亮：形容词，指发光明亮，与“正”的“不偏斜”义没有反义关系。"}, {"text": "甜", "is_correct": false, "explanation": "甜：形容词，指味道甜，与“正”的任何义项都不构成反义关系。"}, {"text": "软", "is_correct": false, "explanation": "软：形容词，指柔软，与“正”的“不偏斜”义没有反义关系。"}], "correct_answer": "歪", "explanations": {"歪": "歪：与“正”的“不偏斜”义互为反义，指物体偏向一侧。", "亮": "亮：形容词，指发光明亮，与“正”的“不偏斜”义没有反义关系。", "甜": "甜：形容词，指味道甜，与“正”的任何义项都不构成反义关系。", "软": "软：形容词，指柔软，与“正”的“不偏斜”义没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39c147ad-02dc-40a2-9f0d-2cea2ca5d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22242, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "歪", "is_correct": true, "explanation": "歪：与“正”的“不偏斜”义互为反义，指物体偏向一侧。"}, {"text": "厚", "is_correct": false, "explanation": "厚：形容词，指厚度大，与“正”的任何义项都没有反义关系。"}, {"text": "慢", "is_correct": false, "explanation": "慢：形容词，指速度低，与“正”的“不偏斜”义没有反义关系。"}, {"text": "深", "is_correct": false, "explanation": "深：形容词，指距离表面远，与“正”的任何义项都没有反义关系。"}], "correct_answer": "歪", "explanations": {"歪": "歪：与“正”的“不偏斜”义互为反义，指物体偏向一侧。", "厚": "厚：形容词，指厚度大，与“正”的任何义项都没有反义关系。", "慢": "慢：形容词，指速度低，与“正”的“不偏斜”义没有反义关系。", "深": "深：形容词，指距离表面远，与“正”的任何义项都没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39c147ad-02dc-40a2-9f0d-2cea2ca5d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22242, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不歪斜，端正。", "primary_collocate": null, "pronunciation": "zhèng", "ipa": "ʈʂɤŋ˥˩", "syllable_count": 1, "sentences": [{"text": "这幅画挂得不正，左边高右边低。", "target_word": "正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他坐得很正，背挺得直直的。", "target_word": "正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "帽子戴得不正，歪到一边去了。", "target_word": "正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个盒子放得很正，四个角都对齐了。", "target_word": "正", "complexity_tier": "T3", "furigana": "zhè gè hé zi fàng de hěn zhèng, sì gè jiǎo dōu duì qí le。", "sentence_source": "generated"}, {"text": "桌子摆得很正，一点儿也不歪。", "target_word": "正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "照片挂得不够正，看起来有点歪。", "target_word": "正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她站得很正，头抬得高高的。", "target_word": "正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条线画得不正，我再画一次。", "target_word": "正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "门前的那根柱子立得很正。", "target_word": "正", "complexity_tier": "T3", "furigana": "mén qián de nà gēn zhù zi lì de hěn zhèng。", "sentence_source": "generated"}, {"text": "杯子有点歪，你把它放得正一点。", "target_word": "正", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "形容词，指物体或姿势端正、不歪（挂得正、坐得正）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd15d400-ff1c-4929-b18e-ebdd0160fea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22242, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "正", "is_correct": true, "explanation": "正（zhèng）：形容词，指不歪斜、端正。"}, {"text": "整", "is_correct": false, "explanation": "整（zhěng，第三声）与 zhèng（第四声）声调不同，意思是完整、整齐。"}, {"text": "镇", "is_correct": false, "explanation": "镇（zhèn）与 zhèng 韵母不同（en 与 eng），意思是城镇。"}, {"text": "账", "is_correct": false, "explanation": "账（zhàng）与 zhèng 韵母不同（ang 与 eng），意思是账目。"}, {"text": "蒸", "is_correct": false, "explanation": "蒸（zhēng，第一声）与 zhèng 声调不同，意思是蒸煮。"}], "explanations": {"正": "正（zhèng）：形容词，指不歪斜、端正。", "整": "整（zhěng，第三声）与 zhèng（第四声）声调不同，意思是完整、整齐。", "镇": "镇（zhèn）与 zhèng 韵母不同（en 与 eng），意思是城镇。", "账": "账（zhàng）与 zhèng 韵母不同（ang 与 eng），意思是账目。", "蒸": "蒸（zhēng，第一声）与 zhèng 声调不同，意思是蒸煮。"}, "sentence_index": null, "correct_answer": "正"}, "level_3": {"options": [{"text": "正", "is_correct": true, "explanation": "正：形容词，指不歪斜，与“挂得不”搭配，说明画挂歪了。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”描写味道，与“挂”的方式不能搭配，语义不通。"}, {"text": "远", "is_correct": false, "explanation": "搭配：“挂”一般不与“远”组成描述挂法的说法，搭配不当。"}, {"text": "亮", "is_correct": false, "explanation": "搭配：“亮”描写光线，与“挂”的方式不能搭配，语义不通。"}], "explanations": {"正": "正：形容词，指不歪斜，与“挂得不”搭配，说明画挂歪了。", "甜": "搭配：“甜”描写味道，与“挂”的方式不能搭配，语义不通。", "远": "搭配：“挂”一般不与“远”组成描述挂法的说法，搭配不当。", "亮": "搭配：“亮”描写光线，与“挂”的方式不能搭配，语义不通。"}, "sentence_index": 0, "correct_answer": "正"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块木板很正，我搬不动。", "explanation": "这里应该用〈厚〉。厚指两面之间的距离大，应说“木板很厚”；〈正〉指不歪斜，不表示厚薄。"}, {"text": "这块地很正，人走着很舒服。", "explanation": "这里应该用〈平〉。平指表面没有起伏，应说“地很平”；〈正〉指不歪斜，不描述表面是否平整。"}, {"text": "这张纸很正，一吹就动。", "explanation": "这里应该用〈薄〉。薄指厚度小，应说“纸很薄”；〈正〉指不歪斜，不表示厚薄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39c147ad-02dc-40a2-9f0d-2cea2ca5d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22242, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "正", "is_correct": true, "explanation": "正（zhèng）：形容词，指不歪斜、端正。"}, {"text": "争", "is_correct": false, "explanation": "争（zhēng，第一声）与 zhèng 声调不同，意思是争夺。"}, {"text": "阵", "is_correct": false, "explanation": "阵（zhèn）与 zhèng 韵母不同（en 与 eng），意思是一阵子。"}, {"text": "盛", "is_correct": false, "explanation": "盛（shèng）与 zhèng 声母不同（sh 与 zh），声调相同，意思是兴盛。"}, {"text": "撑", "is_correct": false, "explanation": "撑（chēng）与 zhèng 声母不同（ch 与 zh），声调也不同，意思是支撑。"}], "explanations": {"正": "正（zhèng）：形容词，指不歪斜、端正。", "争": "争（zhēng，第一声）与 zhèng 声调不同，意思是争夺。", "阵": "阵（zhèn）与 zhèng 韵母不同（en 与 eng），意思是一阵子。", "盛": "盛（shèng）与 zhèng 声母不同（sh 与 zh），声调相同，意思是兴盛。", "撑": "撑（chēng）与 zhèng 声母不同（ch 与 zh），声调也不同，意思是支撑。"}, "sentence_index": null, "correct_answer": "正"}, "level_3": {"options": [{"text": "正", "is_correct": true, "explanation": "正：形容词，指站得端直，与“头抬得高高的”的挺拔姿态一致。"}, {"text": "弯", "is_correct": false, "explanation": "语义：“弯”指身体弯曲，与“头抬得高高的”的挺直姿态矛盾。"}, {"text": "驼", "is_correct": false, "explanation": "搭配：“驼”多指背部弯曲，用于“站得很驼”不符合习惯说法。"}, {"text": "矮", "is_correct": false, "explanation": "语义：“矮”说身高，与“头抬得高高的”描写的姿态不协调。"}], "explanations": {"正": "正：形容词，指站得端直，与“头抬得高高的”的挺拔姿态一致。", "弯": "语义：“弯”指身体弯曲，与“头抬得高高的”的挺直姿态矛盾。", "驼": "搭配：“驼”多指背部弯曲，用于“站得很驼”不符合习惯说法。", "矮": "语义：“矮”说身高，与“头抬得高高的”描写的姿态不协调。"}, "sentence_index": 6, "correct_answer": "正"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个球很正，滚得很快。", "explanation": "这里应该用〈圆〉。圆指没有棱角、呈圆形，应说“球很圆”；〈正〉指不歪斜，不描述形状。"}, {"text": "这把刀很正，切菜很快。", "explanation": "这里应该用〈利〉。利指锋利，应说“刀很利”；〈正〉不表示锋利义。"}, {"text": "这间屋子很正，住着很舒服。", "explanation": "这里应该用〈暖和〉。暖和指温度适中、不冷，应说“屋子很暖和”；〈正〉不表示温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39c147ad-02dc-40a2-9f0d-2cea2ca5d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22242, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张地图挂得正很。", "corrected_sentence": "这张地图挂得很正。", "error_description": "“很”修饰形容词“正”，应放在“正”之前，应说“挂得很正”，不能说“挂得正很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39c147ad-02dc-40a2-9f0d-2cea2ca5d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22242, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块匾挂了正，字看得清楚。", "corrected_sentence": "这块匾挂正了，字看得清楚。", "error_description": "“挂正”是动词加结果补语，“了”应放在整个动补结构之后，应说“挂正了”，不能说“挂了正”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39c147ad-02dc-40a2-9f0d-2cea2ca5d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
