INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22244, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "机器像人一样学会想事情、做事情。", "primary_collocate": null, "pronunciation": "rén gōng zhì néng", "ipa": "ʐən˧˥ kʊŋ˥ ʈʂɨ˥˩ nəŋ˧˥", "syllable_count": 4, "sentences": [{"text": "人工智能可以帮我们翻译句子。", "target_word": "人工智能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在很多手机都有人工智能功能。", "target_word": "人工智能", "complexity_tier": "T3", "furigana": "rén gōng zhì néng", "sentence_source": "generated"}, {"text": "他想学习人工智能。", "target_word": "人工智能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人工智能会下棋，也会画画。", "target_word": "人工智能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司正在研发人工智能。", "target_word": "人工智能", "complexity_tier": "T3", "furigana": "rén gōng zhì néng", "sentence_source": "generated"}, {"text": "人工智能让我们的生活更方便。", "target_word": "人工智能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说人工智能是新的技术。", "target_word": "人工智能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用人工智能写了一封信。", "target_word": "人工智能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人担心人工智能会代替工作。", "target_word": "人工智能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人工智能的发展特别快。", "target_word": "人工智能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人工智能技术", "label": "复合"}, {"form": "人工智能产品", "label": "复合"}], "register": "通用", "sense_fingerprint": "让机器会学习、会思考的技术", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ddbf6c1-65b5-4c28-9abb-1fe3d7a1f8f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22244, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：“天气”是自然现象，不能充当“帮我们翻译句子”的施事。"}, {"text": "人工智能", "is_correct": true, "explanation": "人工智能：正确答案，是能够帮助人完成翻译的技术。"}, {"text": "心情", "is_correct": false, "explanation": "配价：“帮助”需要能动的施事，“心情”是情绪，不能做施事。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：“午饭”是食物，不能帮人翻译句子。"}], "explanations": {"天气": "语义：“天气”是自然现象，不能充当“帮我们翻译句子”的施事。", "人工智能": "人工智能：正确答案，是能够帮助人完成翻译的技术。", "心情": "配价：“帮助”需要能动的施事，“心情”是情绪，不能做施事。", "午饭": "语义：“午饭”是食物，不能帮人翻译句子。"}, "sentence_index": 0, "correct_answer": "人工智能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "现在的人工智能是下午三点。", "explanation": "这里应该用〈时间〉。“人工智能”指一种技术，不能用来说明时刻，表示现在的时刻要用“时间”。"}, {"text": "我的人工智能今天吃了午饭。", "explanation": "这里应该用〈弟弟〉。“人工智能”是一种技术，不能吃午饭，要说“我的弟弟”。"}, {"text": "他正在学习一只人工智能。", "explanation": "这里应该用〈门〉。量词“只”用于动物，学科或技术要用“门”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6c19ad-5bbb-4eee-a007-d6f320b39185') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22244, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "味道", "is_correct": false, "explanation": "语义：“味道”指气味或口味，不能是“新的技术”。"}, {"text": "人工智能", "is_correct": true, "explanation": "人工智能：正确答案，可以说“是新的技术”。"}, {"text": "大海", "is_correct": false, "explanation": "语义：“大海”是地理事物，不是技术。"}, {"text": "春天", "is_correct": false, "explanation": "语义：“春天”是季节，不能被称为“新的技术”。"}], "explanations": {"味道": "语义：“味道”指气味或口味，不能是“新的技术”。", "人工智能": "人工智能：正确答案，可以说“是新的技术”。", "大海": "语义：“大海”是地理事物，不是技术。", "春天": "语义：“春天”是季节，不能被称为“新的技术”。"}, "sentence_index": 6, "correct_answer": "人工智能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的人工智能很阴。", "explanation": "这里应该用〈天气〉。“很阴”用来形容天气，人工智能是一种技术，不能用来形容天气。"}, {"text": "我对你的人工智能很深。", "explanation": "这里应该用〈感情〉。“很深”用来形容两人之间的感情，人工智能是一种技术，不能用来形容感情。"}, {"text": "这条河的人工智能很宽。", "explanation": "这里应该用〈宽度〉。“很宽”用来形容河面的宽窄，人工智能不能用来说河的宽窄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6c19ad-5bbb-4eee-a007-d6f320b39185') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22244, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家医院开始使用一只人工智能。", "corrected_sentence": "这家医院开始使用人工智能。", "error_description": "错误：“一只”；正确：去掉“一只”。“只”用于动物，人工智能作为技术不能用“只”计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6c19ad-5bbb-4eee-a007-d6f320b39185') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22244, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这门课讲的是人工智能地历史。", "corrected_sentence": "这门课讲的是人工智能的历史。", "error_description": "错误：“人工智能地历史”；正确：“人工智能的历史”。“人工智能”修饰“历史”作定语，定语后面要用“的”，“地”用于修饰动词或形容词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6c19ad-5bbb-4eee-a007-d6f320b39185') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
