INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22250, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "事情正在发生的那一刻。", "primary_collocate": null, "pronunciation": "shí shí", "ipa": "ʂɻ̩˧˥ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "这个软件能实时翻译。", "target_word": "实时", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "手机地图会实时告诉你路上的情况。", "target_word": "实时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们可以实时看到比赛的分数。", "target_word": "实时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新闻网站实时更新每天的消息。", "target_word": "实时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "记者正在实时报道事故现场。", "target_word": "实时", "complexity_tier": "T3", "furigana": "shí shí", "sentence_source": "generated"}, {"text": "在线课堂中，老师实时回答同学们的问题。", "target_word": "实时", "complexity_tier": "T3", "furigana": "shí shí", "sentence_source": "generated"}, {"text": "电视正在实时播放比赛。", "target_word": "实时", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他用手机实时直播了现场。", "target_word": "实时", "complexity_tier": "T3", "furigana": "shí shí", "sentence_source": "generated"}, {"text": "医生可以实时看到病人的心跳。", "target_word": "实时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个网站的天气是实时的，很准。", "target_word": "实时", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "实时性", "label": "复合"}, {"form": "實時", "label": "繁体"}], "register": "中性", "sense_fingerprint": "实时|property|事情正在发生的那一刻", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c39c2f0b-1c7d-4288-9529-c42fc1d1b19a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22250, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "实时", "is_correct": true, "explanation": "实时：shí shí（第二声），指事情正在发生的那一刻。"}, {"text": "时事", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是时事、新闻。"}, {"text": "事实", "is_correct": false, "explanation": "第一个音节 shì（第四声）与 shí（第二声）声调不同，意思是事实。"}, {"text": "实施", "is_correct": false, "explanation": "第二个音节 shī（第一声）与 shí（第二声）声调不同，意思是实施。"}, {"text": "史实", "is_correct": false, "explanation": "第一个音节 shǐ（第三声）与 shí（第二声）声调不同，意思是史实，即历史上的事实。"}], "explanations": {"实时": "实时：shí shí（第二声），指事情正在发生的那一刻。", "时事": "shì（第四声）与 shí（第二声）声调不同，意思是时事、新闻。", "事实": "第一个音节 shì（第四声）与 shí（第二声）声调不同，意思是事实。", "实施": "第二个音节 shī（第一声）与 shí（第二声）声调不同，意思是实施。", "史实": "第一个音节 shǐ（第三声）与 shí（第二声）声调不同，意思是史实，即历史上的事实。"}, "sentence_index": null, "correct_answer": "实时"}, "level_3": {"options": [{"text": "实时", "is_correct": true, "explanation": "实时：指事情正在发生的那一刻，修饰“翻译”表示即时进行，与句子相符。"}, {"text": "陈旧", "is_correct": false, "explanation": "语义：陈旧指东西老旧，不能用来修饰“翻译”这种进行方式。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：悲伤是情绪，不能用来修饰翻译的方式，句子说不通。"}, {"text": "古老", "is_correct": false, "explanation": "搭配：古老多用于说事物的年代，不能修饰“翻译”。"}], "explanations": {"实时": "实时：指事情正在发生的那一刻，修饰“翻译”表示即时进行，与句子相符。", "陈旧": "语义：陈旧指东西老旧，不能用来修饰“翻译”这种进行方式。", "悲伤": "语义：悲伤是情绪，不能用来修饰翻译的方式，句子说不通。", "古老": "搭配：古老多用于说事物的年代，不能修饰“翻译”。"}, "sentence_index": 0, "correct_answer": "实时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们实时赶到了现场。", "explanation": "这里应该用〈及时〉。及时指在需要的时候，实时指事情正在发生的那一刻，不能说“实时赶到”。"}, {"text": "火车实时到站，没有晚点。", "explanation": "这里应该用〈按时〉。按时指在规定的时间，实时指事情正在发生的那一刻，不能说“实时到站”。"}, {"text": "会议上他实时承认了错误。", "explanation": "这里应该用〈当场〉。当场指在当时的现场，实时指事情正在发生的那一刻，不能修饰“承认”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '691f3f1c-d45d-444e-963e-277b3753efa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22250, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "实时", "is_correct": true, "explanation": "实时：shí shí（第二声），指事情正在发生的那一刻。"}, {"text": "石狮", "is_correct": false, "explanation": "第二个音节 shī（第一声）与 shí（第二声）声调不同，意思是石狮子。"}, {"text": "史诗", "is_correct": false, "explanation": "两个音节声调都不同：shǐ（第三声）、shī（第一声）与 shí shí 不同，意思是史诗。"}, {"text": "实事", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是实际发生的事情。"}, {"text": "事事", "is_correct": false, "explanation": "两个音节声调都不同：shì shì（第四声）与 shí shí 不同，意思是每一件事。"}], "explanations": {"实时": "实时：shí shí（第二声），指事情正在发生的那一刻。", "石狮": "第二个音节 shī（第一声）与 shí（第二声）声调不同，意思是石狮子。", "史诗": "两个音节声调都不同：shǐ（第三声）、shī（第一声）与 shí shí 不同，意思是史诗。", "实事": "shì（第四声）与 shí（第二声）声调不同，意思是实际发生的事情。", "事事": "两个音节声调都不同：shì shì（第四声）与 shí shí 不同，意思是每一件事。"}, "sentence_index": null, "correct_answer": "实时"}, "level_3": {"options": [{"text": "实时", "is_correct": true, "explanation": "实时：指事情正在发生的那一刻，修饰“播放”表示同步进行，与句子相符。"}, {"text": "漆黑", "is_correct": false, "explanation": "语义：漆黑指没有光亮，与电视播放画面的动作相矛盾。"}, {"text": "冰冷", "is_correct": false, "explanation": "语义：冰冷指温度低或态度冷淡，不能用来修饰“播放”。"}, {"text": "空荡", "is_correct": false, "explanation": "搭配：空荡多用来描述空间，不能修饰“播放比赛”。"}], "explanations": {"实时": "实时：指事情正在发生的那一刻，修饰“播放”表示同步进行，与句子相符。", "漆黑": "语义：漆黑指没有光亮，与电视播放画面的动作相矛盾。", "冰冷": "语义：冰冷指温度低或态度冷淡，不能用来修饰“播放”。", "空荡": "搭配：空荡多用来描述空间，不能修饰“播放比赛”。"}, "sentence_index": 6, "correct_answer": "实时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会议总是实时开始，从不拖延。", "explanation": "这里应该用〈准时〉。准时指到了规定的时间，实时指事情正在发生的那一刻，不能说“实时开始”。"}, {"text": "你实时可以来找我。", "explanation": "这里应该用〈随时〉。随时指任何时候都可以，实时指事情正在发生的那一刻，不能表示“任何时候”。"}, {"text": "我们实时决定改时间。", "explanation": "这里应该用〈临时〉。临时指暂时或临场做出决定，实时指事情正在发生的那一刻，不能说“实时决定”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '691f3f1c-d45d-444e-963e-277b3753efa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22250, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他收到了一条实时地信息。", "corrected_sentence": "他收到了一条实时信息。", "error_description": "错误：“地”误用。“实时”修饰名词“信息”时不用“地”，“地”用于修饰动词。应说“实时信息”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '691f3f1c-d45d-444e-963e-277b3753efa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22250, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台机器能实时了监测温度。", "corrected_sentence": "这台机器能实时监测温度。", "error_description": "错误：“了”误用。“实时”作状语修饰动词，中间不能加“了”，应说“能实时监测温度”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '691f3f1c-d45d-444e-963e-277b3753efa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
