INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22252, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "别人告诉你该做什么，你就做什么。", "primary_collocate": null, "pronunciation": "zhǐ lìng", "ipa": "ʈʂɨ˨˩˦ liŋ˥˩", "syllable_count": 2, "sentences": [{"text": "老师的指令很简单，大家都听懂了。", "target_word": "指令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "班长的指令是先写作业，再出去玩。", "target_word": "指令", "complexity_tier": "T3", "furigana": "bān zhǎng de zhǐ lìng shì xiān xiě zuò yè, zài chū qù wán.", "sentence_source": "generated"}, {"text": "教练的指令一下，球员们都跑起来了。", "target_word": "指令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他做饭时总是听从妈妈的指令。", "target_word": "指令", "complexity_tier": "T3", "furigana": "tā zuò fàn shí zǒng shì tīng cóng mā ma de zhǐ lìng.", "sentence_source": "generated"}, {"text": "我没听清楚他的指令，只好再问一遍。", "target_word": "指令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到指令，孩子们立刻站好了。", "target_word": "指令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生的指令是：每天早上吃药。", "target_word": "指令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "导游的指令，我们一定要听。", "target_word": "指令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游戏的指令是向左走三步。", "target_word": "指令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请等我的指令，再开始跳舞。", "target_word": "指令", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条指令", "label": "量词"}, {"form": "一道指令", "label": "量词"}, {"form": "指令集", "label": "复合"}], "register": "中性", "sense_fingerprint": "指令：别人告诉你该做什么的话，听的人要照着做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3370b77-fb49-4e42-b46b-5b0a583e1654') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22252, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "指令", "is_correct": true, "explanation": "正确：老师的指令指要求大家去做的事，与“大家都听懂了”相合。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：云朵是天上的水汽，不能作老师布置的事，“很简单”也不搭。"}, {"text": "芝麻", "is_correct": false, "explanation": "搭配：“老师的”后面不能接“芝麻”这类食物，句子说不通。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是地理事物，不能被“听懂”，与句意不符。"}], "explanations": {"指令": "正确：老师的指令指要求大家去做的事，与“大家都听懂了”相合。", "云朵": "语义：云朵是天上的水汽，不能作老师布置的事，“很简单”也不搭。", "芝麻": "搭配：“老师的”后面不能接“芝麻”这类食物，句子说不通。", "河流": "语义：河流是地理事物，不能被“听懂”，与句意不符。"}, "sentence_index": 0, "correct_answer": "指令"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈给他布置了一支指令，让他去买菜。", "explanation": "这里应该用〈条〉。〈支〉用于笔、棍等细长的物体，指令不能用〈支〉来计量。"}, {"text": "他做饭时总是采纳妈妈的指令。", "explanation": "这里应该用〈建议〉。建议可以采纳，指令要求执行，不能说“采纳指令”；“采纳”搭配的是〈建议〉。"}, {"text": "他做饭时总有一个指令，希望能做出好吃的菜。", "explanation": "这里应该用〈愿望〉。指令是别人要求你执行的，不能用来表达自己做饭时的希望。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13ab7b39-29ac-4c7b-9c96-7e4f274fce82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22252, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指令", "is_correct": true, "explanation": "正确：医生的指令指要求病人执行的嘱咐，与“每天早上吃药”相合。"}, {"text": "湖泊", "is_correct": false, "explanation": "语义：湖泊是水域，不能作为医生要求的内容。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，与“吃药”的要求毫不相关。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“医生的”后面接“石头”不成搭配，且与“吃药”无关。"}], "explanations": {"指令": "正确：医生的指令指要求病人执行的嘱咐，与“每天早上吃药”相合。", "湖泊": "语义：湖泊是水域，不能作为医生要求的内容。", "钢琴": "语义：钢琴是乐器，与“吃药”的要求毫不相关。", "石头": "搭配：“医生的”后面接“石头”不成搭配，且与“吃药”无关。"}, "sentence_index": 6, "correct_answer": "指令"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我还没发出一把指令，你们先别跳舞。", "explanation": "这里应该用〈条〉。〈把〉用于有柄的器具，指令不能用〈把〉计量。"}, {"text": "我向你提出一个指令，希望你先别跳舞。", "explanation": "这里应该用〈请求〉。指令是要求对方执行的命令；希望对方先别动，属于〈请求〉。"}, {"text": "我向你们发出一个指令，祝大家新年快乐。", "explanation": "这里应该用〈祝福〉。指令是必须执行的命令，不能用来表达祝愿；“祝大家新年快乐”属于〈祝福〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13ab7b39-29ac-4c7b-9c96-7e4f274fce82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22252, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他听从了老师的一只指令。", "corrected_sentence": "他听从了老师的一条指令。", "error_description": "量词错误：“指令”应用“条”计量。“只”用于动物，应改为“一条指令”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13ab7b39-29ac-4c7b-9c96-7e4f274fce82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22252, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他已经按照老师的一本指令完成了作业。", "corrected_sentence": "他已经按照老师的一条指令完成了作业。", "error_description": "量词错误：“指令”应用“条”计量。“本”用于书籍，应改为“一条指令”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13ab7b39-29ac-4c7b-9c96-7e4f274fce82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
