INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22256, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一种用符号来表示想法、进行推理的学问，比如用字母代表句子。", "primary_collocate": null, "pronunciation": "fú hào luó jí", "ipa": "fu˧˥ xɑʊ˥˩ lwo˧˥ tɕi˧˥", "syllable_count": 4, "sentences": [{"text": "符号逻辑用符号表示人的想法。", "target_word": "符号逻辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在符号逻辑里，我们常用字母代表句子。", "target_word": "符号逻辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "符号逻辑课上，老师教我们用符号写想法。", "target_word": "符号逻辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得符号逻辑像一种特别的语言。", "target_word": "符号逻辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "符号逻辑里的符号，有的像数学符号。", "target_word": "符号逻辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对符号逻辑很感兴趣，每天都学一点。", "target_word": "符号逻辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这门符号逻辑课，同学们都觉得很难。", "target_word": "符号逻辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐给我讲了什么是符号逻辑。", "target_word": "符号逻辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "符号逻辑中，用符号来写推理，可以看得更清楚。", "target_word": "符号逻辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学了符号逻辑，我用符号来记想法。", "target_word": "符号逻辑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "符號邏輯", "label": "繁体"}, {"form": "门", "label": "量词"}], "register": "书面", "sense_fingerprint": "用符号表示想法的学问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a267b60a-1885-4776-a101-f0f8d7d64538') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22256, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "符号逻辑", "is_correct": true, "explanation": "符号逻辑是用符号表示想法的学问，作主语指这门学问本身，搭配正确。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：冰块是固态的水，不能用符号表示人的想法。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎是动物，不能用符号表示人的想法。"}, {"text": "蜂蜜", "is_correct": false, "explanation": "语义：蜂蜜是食物，不能用符号表示人的想法。"}], "explanations": {"符号逻辑": "符号逻辑是用符号表示想法的学问，作主语指这门学问本身，搭配正确。", "冰块": "语义：冰块是固态的水，不能用符号表示人的想法。", "老虎": "语义：老虎是动物，不能用符号表示人的想法。", "蜂蜜": "语义：蜂蜜是食物，不能用符号表示人的想法。"}, "sentence_index": 0, "correct_answer": "符号逻辑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他说话很有符号逻辑。", "explanation": "这里应该用〈道理〉：“很有道理”指说话有根据；符号逻辑是用符号表示想法的学问，不能用来形容说话。"}, {"text": "符号逻辑很香，快尝尝。", "explanation": "这里应该用〈汤〉。“很香、快尝尝”形容食物；符号逻辑是学问，不能吃。"}, {"text": "符号逻辑是一种面粉做的点心。", "explanation": "这里应该用〈糕点〉：“面粉做的”指食品；符号逻辑是用符号表示想法的学问，不是食品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22256, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "符号逻辑", "is_correct": true, "explanation": "符号逻辑是一门学问，“这门符号逻辑课”指这门课，与句子语境相符。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是学科，不能用作课程的名称。"}, {"text": "老头儿", "is_correct": false, "explanation": "语域：“老头儿”是口语词，用于书面的课程名称不协调。"}, {"text": "香蕉", "is_correct": false, "explanation": "语义：香蕉是水果，不是学科，不能作为课程的名称。"}], "explanations": {"符号逻辑": "符号逻辑是一门学问，“这门符号逻辑课”指这门课，与句子语境相符。", "空气": "语义：空气不是学科，不能用作课程的名称。", "老头儿": "语域：“老头儿”是口语词，用于书面的课程名称不协调。", "香蕉": "语义：香蕉是水果，不是学科，不能作为课程的名称。"}, "sentence_index": 6, "correct_answer": "符号逻辑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的符号逻辑很快。", "explanation": "这里应该用〈节奏〉。“很快”描述音乐的节拍；符号逻辑是学问，不描述速度。"}, {"text": "这篇文章的符号逻辑很朴素。", "explanation": "这里“符号逻辑”是学问，不指文章的写法；“朴素”形容文风，应说〈语言〉。"}, {"text": "符号逻辑的颜色是红色的。", "explanation": "这里“符号逻辑”是学问，没有颜色；颜色用于〈图案〉这类有形的东西，不能用来描述学问。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22256, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我学了过符号逻辑，知道一些符号的用法。", "corrected_sentence": "我学过符号逻辑，知道一些符号的用法。", "error_description": "体标叠用错误：“了”和“过”不能同时用在同一动词后，经历体只用“过”，应说“学过符号逻辑”，删去“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22256, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我去年选了一把符号逻辑课。", "corrected_sentence": "我去年选了一门符号逻辑课。", "error_description": "量词错误：课程用“门”，“把”用于有柄的器具。应为“一门符号逻辑课”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
