INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22260, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "仔细看。", "primary_collocate": null, "pronunciation": "shěn shì", "ipa": "ʂən˨˩ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "老师拿起我的作业，认真地审视了一遍。", "target_word": "审视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在镜子前，静静地审视着自己。", "target_word": "审视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生审视着那张片子，皱起了眉头。", "target_word": "审视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用怀疑的眼光审视着面前的陌生人。", "target_word": "审视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画家退后几步，审视自己刚画好的画。", "target_word": "审视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察审视着房间里的每一个角落。", "target_word": "审视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买房子以前，他审视了每个房间的墙。", "target_word": "审视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人戴上眼镜，审视着手里的旧照片。", "target_word": "审视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理审视了一下新来的员工，没有说话。", "target_word": "审视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把那封信审视了很久，还是看不懂。", "target_word": "审视", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "审视了", "label": "体标（了）"}, {"form": "审视着", "label": "体标（着）"}, {"form": "审视过", "label": "体标（过）"}], "register": "书面", "sense_fingerprint": "审视-认真、仔细地看", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b8958f0-ffe2-4271-bc78-1dc054604ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22260, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "审视", "is_correct": true, "explanation": "审视（shěn shì）：认真、仔细地看。"}, {"text": "身世", "is_correct": false, "explanation": "身世（shēn shì）与审视（shěn shì）第一个音节声调不同（第一声），意思是个人的经历和出身。"}, {"text": "省事", "is_correct": false, "explanation": "省事（shěng shì）与审视（shěn shì）韵母不同（ing 与 in），意思是省去麻烦。"}, {"text": "声势", "is_correct": false, "explanation": "声势（shēng shì）与审视（shěn shì）韵母不同（eng 与 en），声调也不同，意思是气势、声威。"}], "explanations": {"审视": "审视（shěn shì）：认真、仔细地看。", "身世": "身世（shēn shì）与审视（shěn shì）第一个音节声调不同（第一声），意思是个人的经历和出身。", "省事": "省事（shěng shì）与审视（shěn shì）韵母不同（ing 与 in），意思是省去麻烦。", "声势": "声势（shēng shì）与审视（shěn shì）韵母不同（eng 与 en），声调也不同，意思是气势、声威。"}, "sentence_index": null, "correct_answer": "审视"}, "level_3": {"options": [{"text": "撕", "is_correct": false, "explanation": "语义：“撕”是把东西弄破，与“认真地看”的意思不符。"}, {"text": "审视", "is_correct": true, "explanation": "“认真地审视了一遍”表示仔细看了一遍作业，符合语境。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢掉，与“认真地”看作业的动作相矛盾。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”是给人或动物送食物，与“认真地看作业”的动作不合。"}], "explanations": {"撕": "语义：“撕”是把东西弄破，与“认真地看”的意思不符。", "审视": "“认真地审视了一遍”表示仔细看了一遍作业，符合语境。", "扔": "语义：“扔”是丢掉，与“认真地”看作业的动作相矛盾。", "喂": "语义：“喂”是给人或动物送食物，与“认真地看作业”的动作不合。"}, "sentence_index": 0, "correct_answer": "审视"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他闭着眼睛，审视着面包的香味。", "explanation": "这里应该用〈闻〉。审视是用眼睛仔细看，不能用于闻气味。"}, {"text": "她轻轻地审视着微风的凉意。", "explanation": "这里应该用〈感受〉。审视是视觉动作，不能用于体会凉意之类的身体感觉。"}, {"text": "他静静地审视着远处的鸟鸣。", "explanation": "这里应该用〈倾听〉。审视用眼睛看，不能用于听声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad4e277-4461-49be-8fb2-4b479753ab00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22260, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "搬", "is_correct": false, "explanation": "语义：墙是固定的建筑结构，不能“搬”，与“仔细查看墙面”不合。"}, {"text": "审视", "is_correct": true, "explanation": "“审视了每个房间的墙”表示买房前仔细查看墙面，符合语境。"}, {"text": "喝", "is_correct": false, "explanation": "语义：墙不能喝，“喝”与“房间的墙”的语境完全不符。"}, {"text": "订", "is_correct": false, "explanation": "搭配：“订”用于订报纸、订座位，不能用于墙。"}], "explanations": {"搬": "语义：墙是固定的建筑结构，不能“搬”，与“仔细查看墙面”不合。", "审视": "“审视了每个房间的墙”表示买房前仔细查看墙面，符合语境。", "喝": "语义：墙不能喝，“喝”与“房间的墙”的语境完全不符。", "订": "搭配：“订”用于订报纸、订座位，不能用于墙。"}, "sentence_index": 6, "correct_answer": "审视"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他仔细审视着这碗汤的味道。", "explanation": "这里应该用〈品尝〉。审视是用眼睛看，不能用于尝味道。"}, {"text": "她安静地审视着雨声。", "explanation": "这里应该用〈聆听〉。审视是用眼睛看，不能用于听声音。"}, {"text": "他伸手审视着那块冰冷的石头。", "explanation": "这里应该用〈触摸〉。审视是用眼睛仔细看，不能用手去感受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad4e277-4461-49be-8fb2-4b479753ab00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22260, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店员仔细审视了着那张旧地图，寻找出口。", "corrected_sentence": "店员仔细审视着那张旧地图，寻找出口。", "error_description": "体标用错。“审视着”表示动作正在进行，不能在“审视”后同时加“了”和“着”，应说“审视着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad4e277-4461-49be-8fb2-4b479753ab00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22260, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "侦探仔细审视着案发现场的一只脚印。", "corrected_sentence": "侦探仔细审视着案发现场的一个脚印。", "error_description": "量词用错。脚印应用「个」，「只」用于动物等，不能说「一只脚印」，应说「一个脚印」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad4e277-4461-49be-8fb2-4b479753ab00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
