INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22262, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "一本书好不好读，就是可读性。", "primary_collocate": null, "pronunciation": "kě dú xìng", "ipa": "kʰɤ˨˩ tu˧˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这本书的可读性很高，孩子也爱看。", "target_word": "可读性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书的可读性不高，我读不下去。", "target_word": "可读性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买书以前，我会先看一看可读性怎么样。", "target_word": "可读性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部小说故事精彩，可读性很强。", "target_word": "可读性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书里的字太小，可读性差。", "target_word": "可读性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友说这本书很有可读性，我就买了一本。", "target_word": "可读性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的书语言简单，可读性比别人的好。", "target_word": "可读性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本杂志的可读性强，每期都有人买。", "target_word": "可读性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书名很吸引人，内容的可读性也不错。", "target_word": "可读性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作者想提高这本书的可读性，就改了很多地方。", "target_word": "可读性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "可讀性", "label": "繁体"}], "register": "通用", "sense_fingerprint": "一本书好不好读", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abf388ec-18fe-4bd8-8a47-45cf8777f83f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22262, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可读性", "is_correct": true, "explanation": "正确。“可读性”指一本书好不好读，放在“很高，孩子也爱看”之前最通顺。"}, {"text": "纯度", "is_correct": false, "explanation": "语义：“纯度”说的是物质的纯净程度，一本书的纯度很高不成立。"}, {"text": "能耗", "is_correct": false, "explanation": "语义：“能耗”指能源消耗，书的能耗很高没有意义。"}, {"text": "功率", "is_correct": false, "explanation": "语域：“功率”是物理和电器的专业词，不用来评价一本书是否好读。"}], "explanations": {"可读性": "正确。“可读性”指一本书好不好读，放在“很高，孩子也爱看”之前最通顺。", "纯度": "语义：“纯度”说的是物质的纯净程度，一本书的纯度很高不成立。", "能耗": "语义：“能耗”指能源消耗，书的能耗很高没有意义。", "功率": "语域：“功率”是物理和电器的专业词，不用来评价一本书是否好读。"}, "sentence_index": 0, "correct_answer": "可读性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电视的可读性很高，画面的细节都很清楚。", "explanation": "这里应该用〈清晰度〉。可读性只用于文字作品，电视画面的清楚程度要说清晰度。"}, {"text": "这段录音的可读性很好，小声的地方也听得见。", "explanation": "这里应该用〈音质〉。可读性只说文字作品，录音的好坏要用音质。"}, {"text": "这台机器的可读性很稳，多年都没有出过问题。", "explanation": "这里应该用〈可靠性〉。可读性只用于文字作品，机器的稳定程度要说可靠性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22262, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可读性", "is_correct": true, "explanation": "正确。句中说语言简单，比较的是这本书的“可读性”，即好不好读。"}, {"text": "防水性", "is_correct": false, "explanation": "语义：“防水性”指防止水渗入的能力，书的语言简单不谈防水。"}, {"text": "导热性", "is_correct": false, "explanation": "语义：“导热性”指传导热量的能力，与语言是否简单毫无关系。"}, {"text": "延展性", "is_correct": false, "explanation": "语域：“延展性”是金属等材料的物理术语，不用于评价一本书的语言。"}], "explanations": {"可读性": "正确。句中说语言简单，比较的是这本书的“可读性”，即好不好读。", "防水性": "语义：“防水性”指防止水渗入的能力，书的语言简单不谈防水。", "导热性": "语义：“导热性”指传导热量的能力，与语言是否简单毫无关系。", "延展性": "语域：“延展性”是金属等材料的物理术语，不用于评价一本书的语言。"}, "sentence_index": 6, "correct_answer": "可读性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书有一片很高的可读性，我一看就喜欢。", "explanation": "这里不能用量词〈片〉。〈片〉用于叶子、薄片等东西，可读性是抽象名词，不能这样计量。"}, {"text": "这本书有一幅很好的可读性，大家都在读。", "explanation": "这里不能用量词〈幅〉。〈幅〉用于画、图等，可读性不能用它计量。"}, {"text": "这本书有一台很强的可读性，孩子很爱看。", "explanation": "这里不能用量词〈台〉。〈台〉用于机器、设备，可读性是抽象名词，不能用它计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22262, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本字典的可读性很重，初学者都能用。", "corrected_sentence": "这本字典的可读性很高，初学者都能用。", "error_description": "错误：“重”指物体的重量，不能用来形容可读性，应说“高”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22262, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本小说的可读性们很好，学生都爱看。", "corrected_sentence": "这本小说的可读性很好，学生都爱看。", "error_description": "错误：“们”只用于指人，抽象名词“可读性”后不能加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
