INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22266, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "事物本身，尤其是主体部分，不包括附件，也不是它的照片。", "primary_collocate": null, "pronunciation": "běn tǐ", "ipa": "pən˨˩ tʰi˨˩", "syllable_count": 2, "sentences": [{"text": "这只是照片，不是它的本体。", "target_word": "本体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个报价只包括相机本体，不包括镜头。", "target_word": "本体", "complexity_tier": "T3", "furigana": "zhè ge bào jià zhǐ bāo kuò xiàng jī běn tǐ, bù bāo kuò jìng tóu.", "sentence_source": "generated"}, {"text": "手机的壳很漂亮，本体却很旧。", "target_word": "本体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个玩具的本体是木头做的，外面涂着红色。", "target_word": "本体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台吸尘器本体很小，配件却很多。", "target_word": "本体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "盒子是新的，里面的本体却坏了。", "target_word": "本体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "照片上的月亮和月亮本体不一样。", "target_word": "本体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他只买了游戏机本体，没有买手柄。", "target_word": "本体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先检查一下机器本体有没有问题。", "target_word": "本体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台相机本体很轻，镜头却很重。", "target_word": "本体", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "本體", "label": "繁体"}], "register": "通用", "sense_fingerprint": "事物本身或其主体，区别于附件与照片", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abf388ec-18fe-4bd8-8a47-45cf8777f83f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22266, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "本体", "is_correct": true, "explanation": "正确。“照片”不是事物本身，所以“不是它的本体”成立。"}, {"text": "体温", "is_correct": false, "explanation": "语义：照片没有体温，“不是它的体温”说不通。"}, {"text": "寿命", "is_correct": false, "explanation": "语义：照片没有寿命可谈，句意不通。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”与“照片”不搭配，照片没有可以品尝的味道。"}], "explanations": {"本体": "正确。“照片”不是事物本身，所以“不是它的本体”成立。", "体温": "语义：照片没有体温，“不是它的体温”说不通。", "寿命": "语义：照片没有寿命可谈，句意不通。", "味道": "搭配：“味道”与“照片”不搭配，照片没有可以品尝的味道。"}, "sentence_index": 0, "correct_answer": "本体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道题的本体很大，很多人都做不出来。", "explanation": "这里应该用〈难度〉。本体指事物本身，不指题目的难易程度；说题目难不难要用难度。"}, {"text": "这次旅行的本体很贵，我付不起。", "explanation": "这里应该用〈费用〉。本体指事物本身，不能用来说花钱多少；说花费要用「费用」。"}, {"text": "今天的本体很好，我们去公园吧。", "explanation": "这里应该用〈天气〉。本体指事物本身，不能用来说天气的好坏；说天气要用「天气」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22266, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "本体", "is_correct": true, "explanation": "正确。“月亮本体”指月亮本身，与照片上的月亮相对，所以句意成立。"}, {"text": "节奏", "is_correct": false, "explanation": "语义：月亮没有节奏可以比较，“月亮节奏不一样”说不通。"}, {"text": "芳香", "is_correct": false, "explanation": "搭配：“芳香”多用于花、香料，不与“月亮”搭配。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：月亮不是乐器，句中谈的是月亮本身，“乐器”不成立。"}], "explanations": {"本体": "正确。“月亮本体”指月亮本身，与照片上的月亮相对，所以句意成立。", "节奏": "语义：月亮没有节奏可以比较，“月亮节奏不一样”说不通。", "芳香": "搭配：“芳香”多用于花、香料，不与“月亮”搭配。", "乐器": "语义：月亮不是乐器，句中谈的是月亮本身，“乐器”不成立。"}, "sentence_index": 6, "correct_answer": "本体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天吃本体，所以身体很健康。", "explanation": "这里应该用〈食物〉。本体指事物本身，不能拿来吃；吃的东西要说食物。"}, {"text": "妈妈今天给我穿本体，很合身。", "explanation": "这里应该用〈衣服〉。本体指事物本身，不能拿来穿；穿的东西要说衣服。"}, {"text": "他每天唱本体，大家都很喜欢听。", "explanation": "这里应该用〈歌〉。本体指事物本身，不能拿来唱；唱的要说歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22266, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一只相机本体，镜头另外买。", "corrected_sentence": "我买了一台相机本体，镜头另外买。", "error_description": "量词“只”用错了。“只”用于动物或成对器物中的一个，相机本体应该用量词“台”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22266, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她只买了一只空气炸锅本体，配件另外买。", "corrected_sentence": "她只买了一台空气炸锅本体，配件另外买。", "error_description": "量词“只”用错了。“只”用于动物或成对器物中的一个，空气炸锅本体应该用量词“台”，说“一台空气炸锅本体”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22276, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现象", "is_correct": true, "explanation": "现象：事物表现在外的样子，与「本质」构成反义关系。"}, {"text": "方法", "is_correct": false, "explanation": "方法指做事的途径，与「本质」没有对立关系。"}, {"text": "速度", "is_correct": false, "explanation": "速度指运动的快慢，与「本质」没有对立关系。"}, {"text": "季节", "is_correct": false, "explanation": "季节指一年中的时段，与「本质」没有对立关系。"}], "correct_answer": "现象", "explanations": {"现象": "现象：事物表现在外的样子，与「本质」构成反义关系。", "方法": "方法指做事的途径，与「本质」没有对立关系。", "速度": "速度指运动的快慢，与「本质」没有对立关系。", "季节": "季节指一年中的时段，与「本质」没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7df9bc8-1bcf-43c8-be31-eb6336a223a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22276, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现象", "is_correct": true, "explanation": "现象：事物表现在外的样子，与「本质」构成反义关系。"}, {"text": "体积", "is_correct": false, "explanation": "体积指物体所占空间的大小，与「本质」没有对立关系。"}, {"text": "工具", "is_correct": false, "explanation": "工具指用来做事的器具，与「本质」没有对立关系。"}, {"text": "声音", "is_correct": false, "explanation": "声音指听觉所感受到的振动，与「本质」没有对立关系。"}], "correct_answer": "现象", "explanations": {"现象": "现象：事物表现在外的样子，与「本质」构成反义关系。", "体积": "体积指物体所占空间的大小，与「本质」没有对立关系。", "工具": "工具指用来做事的器具，与「本质」没有对立关系。", "声音": "声音指听觉所感受到的振动，与「本质」没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7df9bc8-1bcf-43c8-be31-eb6336a223a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22276, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "本质就是一样东西最最重要的特点。", "primary_collocate": null, "pronunciation": "běn zhì", "ipa": "pən˨˩˦ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这两件事的本质是一样的。", "target_word": "本质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想看清问题的本质。", "target_word": "本质", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师让我们看到事情的本质，不要只看表面。", "target_word": "本质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱不是幸福的本质。", "target_word": "本质", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这本书说的是爱情的本质。", "target_word": "本质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看起来很凶，可他的本质很善良。", "target_word": "本质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学习的本质是自己多想多练。", "target_word": "本质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "变了名字，东西的本质没有变。", "target_word": "本质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种动物和那种动物，本质不同。", "target_word": "本质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的广告不会骗人，要说出产品的本质。", "target_word": "本质", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "本质上", "label": "复合"}], "register": "中性", "sense_fingerprint": "事物最根本、最重要的特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b76edc4-0981-45f9-b40b-13826adb3d03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22276, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "本质", "is_correct": true, "explanation": "běn zhì（第四声）：事物最根本、最重要的特点，即听到的目标词。"}, {"text": "本市", "is_correct": false, "explanation": "běn shì（第四声）与 běn zhì 的声母不同（sh 与 zh），意思是本市（这座城市）。"}, {"text": "本职", "is_correct": false, "explanation": "běn zhí（第二声）与 běn zhì（第四声）声调不同，意思是本职（本职工作）。"}, {"text": "本身", "is_correct": false, "explanation": "běn shēn 的声母是 sh、声调是第一声，与 běn zhì 的声母和声调都不同，意思是本身（事物自己）。"}, {"text": "本事", "is_correct": false, "explanation": "běn shi（轻声）与 běn zhì 声母不同（sh 与 zh），声调也不同，意思是本事（能力）。"}], "explanations": {"本质": "běn zhì（第四声）：事物最根本、最重要的特点，即听到的目标词。", "本市": "běn shì（第四声）与 běn zhì 的声母不同（sh 与 zh），意思是本市（这座城市）。", "本职": "běn zhí（第二声）与 běn zhì（第四声）声调不同，意思是本职（本职工作）。", "本身": "běn shēn 的声母是 sh、声调是第一声，与 běn zhì 的声母和声调都不同，意思是本身（事物自己）。", "本事": "běn shi（轻声）与 běn zhì 声母不同（sh 与 zh），声调也不同，意思是本事（能力）。"}, "sentence_index": null, "correct_answer": "本质"}, "level_3": {"options": [{"text": "容貌", "is_correct": false, "explanation": "体貌：容貌只指人的外貌，不能用来说两件事之间的关系。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：事件没有颜色，「颜色」只能用来说事物的色彩，这里说不通。"}, {"text": "本质", "is_correct": true, "explanation": "本质：事物最根本的特点，与「这两件事……是一样的」搭配自然。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重只指人或动物的重量，「这两件事的体重」说不通。"}], "explanations": {"容貌": "体貌：容貌只指人的外貌，不能用来说两件事之间的关系。", "颜色": "语义：事件没有颜色，「颜色」只能用来说事物的色彩，这里说不通。", "本质": "本质：事物最根本的特点，与「这两件事……是一样的」搭配自然。", "体重": "语义：体重只指人或动物的重量，「这两件事的体重」说不通。"}, "sentence_index": 0, "correct_answer": "本质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他靠这笔本质开了一家店。", "explanation": "这里应该用〈本钱〉。本质指事物根本的特点，不指做生意用的资金；做生意的资金要用〈本钱〉。"}, {"text": "这件衣服的本质很便宜。", "explanation": "这里应该用〈价格〉。本质不指价钱；说衣服价钱便宜要用〈价格〉。"}, {"text": "这面墙的本质很白。", "explanation": "这里应该用〈颜色〉。本质是抽象的根本特点，不指物体的颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7df9bc8-1bcf-43c8-be31-eb6336a223a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22276, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重量", "is_correct": false, "explanation": "语义：学习没有重量，「重量」只用来说物体，这里说不通。"}, {"text": "本质", "is_correct": true, "explanation": "本质：学习最根本的特点，与「自己多想多练」的内容相合。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：学习不是有岁数的事物，「学习的年龄」说不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材只指人的体形，不能用来说学习。"}], "explanations": {"重量": "语义：学习没有重量，「重量」只用来说物体，这里说不通。", "本质": "本质：学习最根本的特点，与「自己多想多练」的内容相合。", "年龄": "语义：学习不是有岁数的事物，「学习的年龄」说不通。", "身材": "体貌：身材只指人的体形，不能用来说学习。"}, "sentence_index": 6, "correct_answer": "本质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯水的本质很烫。", "explanation": "这里应该用〈温度〉。本质不指冷热这类可感受的程度；说水的冷热要用〈温度〉。"}, {"text": "这块蛋糕的本质很甜。", "explanation": "这里应该用〈味道〉。本质指根本特点，不指口感；说蛋糕甜要用〈味道〉。"}, {"text": "他的本质很大，什么都会修。", "explanation": "这里应该用〈本领〉。本质指事物根本的特点，不指人的能力；说人会做事的能力要用〈本领〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7df9bc8-1bcf-43c8-be31-eb6336a223a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22276, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两件事在本质是一样的。", "corrected_sentence": "这两件事在本质上是一样的。", "error_description": "「在……本质上」是固定格式，应为「在本质上」。学习者常漏掉「上」，写成「在本质」，这是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7df9bc8-1bcf-43c8-be31-eb6336a223a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22276, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种现象本质很复杂。", "corrected_sentence": "这种现象的本质很复杂。", "error_description": "名词作定语修饰「本质」时要加「的」，应为「现象的本质」。学习者常漏掉「的」，这是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7df9bc8-1bcf-43c8-be31-eb6336a223a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
