INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22278, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "耳朵听声音的能力。", "primary_collocate": null, "pronunciation": "tīng jué", "ipa": "tʰiŋ˥ tɕyɛ˧˥", "syllable_count": 2, "sentences": [{"text": "猫的听觉很好，远处的声音也听得到。", "target_word": "听觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的听觉不太好，说话要大声一点。", "target_word": "听觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听觉有问题的人可以戴助听器。", "target_word": "听觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗的听觉比人灵。", "target_word": "听觉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生用仪器测试孩子的听觉。", "target_word": "听觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "耳朵受伤以后，他的听觉变差了。", "target_word": "听觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的听觉会慢慢变弱。", "target_word": "听觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太吵的地方对听觉不好。", "target_word": "听觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的听觉很灵，隔着墙也听得到我说话。", "target_word": "听觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护听觉，请不要把音量开得太大。", "target_word": "听觉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "聽覺", "label": "繁体"}, {"form": "听觉器官", "label": "复合"}], "register": "通用", "sense_fingerprint": "耳朵听声音的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abf388ec-18fe-4bd8-8a47-45cf8777f83f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22278, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不能用“很好”评价能力，句中讲的是猫的听力，与“颜色”不合。"}, {"text": "听觉", "is_correct": true, "explanation": "正确：“听觉”指耳朵听声音的能力，与后面“远处的声音也听得到”一致。"}, {"text": "字迹", "is_correct": false, "explanation": "语义：“字迹”是写下的笔画痕迹，猫不具备字迹，与句意不符。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”一般说“正常”或“超标”，不说“很好”。"}], "explanations": {"颜色": "语义：“颜色”不能用“很好”评价能力，句中讲的是猫的听力，与“颜色”不合。", "听觉": "正确：“听觉”指耳朵听声音的能力，与后面“远处的声音也听得到”一致。", "字迹": "语义：“字迹”是写下的笔画痕迹，猫不具备字迹，与句意不符。", "体重": "搭配：“体重”一般说“正常”或“超标”，不说“很好”。"}, "sentence_index": 0, "correct_answer": "听觉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次露营的听觉让我很满足。", "explanation": "这里应该用〈体验〉。“体验”指亲身经历后获得的感受，可以说“体验让我很满足”；“听觉”是听声音的能力，不能指露营的经历。"}, {"text": "我对这家餐厅的听觉很满意。", "explanation": "这里应该用〈感觉〉。对餐厅的印象要说“感觉”，“听觉”只指听声音的能力。"}, {"text": "这部电影给我留下了深刻的听觉。", "explanation": "这里应该用〈感受〉。对作品的体会要说“感受”，“听觉”不能指这种体会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22278, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "语义：身高会增长或降低，不会“变弱”，与句中的变化趋势不符。"}, {"text": "听觉", "is_correct": true, "explanation": "正确：“听觉”会随年龄减弱，与“慢慢变弱”的语义相合。"}, {"text": "血型", "is_correct": false, "explanation": "语义：血型是固定的生理分类，不会“变弱”，句意不通。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”一般说“增长”，不说“变弱”，与这一搭配不符。"}], "explanations": {"身高": "语义：身高会增长或降低，不会“变弱”，与句中的变化趋势不符。", "听觉": "正确：“听觉”会随年龄减弱，与“慢慢变弱”的语义相合。", "血型": "语义：血型是固定的生理分类，不会“变弱”，句意不通。", "年龄": "搭配：“年龄”一般说“增长”，不说“变弱”，与这一搭配不符。"}, "sentence_index": 6, "correct_answer": "听觉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的听觉很漂亮，我很喜欢。", "explanation": "这里应该用〈款式〉。听觉指听声音的能力，不能用来形容衣服的样式；说衣服的样式要用「款式」。"}, {"text": "这碗汤的听觉很咸，我喝不下去。", "explanation": "这里应该用〈味道〉。听觉指听声音的能力，不能用来说汤的咸淡；说咸淡要用「味道」。"}, {"text": "这座山的听觉很高，我们爬了一整天。", "explanation": "这里应该用〈高度〉。听觉指听声音的能力，不能用来说山的高矮；说高矮要用「高度」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22278, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一张很灵敏的听觉。", "corrected_sentence": "他有一种很灵敏的听觉。", "error_description": "错误：“听觉”前的量词用了“张”。“张”用于纸、桌子等平面的东西，计量抽象的听觉要用“种”。正确形式是“有一种很灵敏的听觉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22278, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "外婆的听觉最近变大了。", "corrected_sentence": "外婆的听觉最近变弱了。", "error_description": "错误：“变大”不能用来描述听觉的强弱；听觉减弱应说“变弱”。正确形式是“外婆的听觉最近变弱了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
