INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22280, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用一些符号来代表信息，就像用密码写东西。", "primary_collocate": null, "pronunciation": "biān mǎ", "ipa": "piɛn˥ ma˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们可以用数字给每个字母编码。", "target_word": "编码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明把自己的名字编码成一串符号。", "target_word": "编码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢用符号编码，给朋友写秘密信。", "target_word": "编码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让学生把短句编码成数字。", "target_word": "编码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她编码了一封信，只有弟弟能看懂。", "target_word": "编码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们用不同的颜色给信息编码。", "target_word": "编码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "游戏里，他们用声音编码秘密消息。", "target_word": "编码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先编码，再发给朋友，别人就看不懂。", "target_word": "编码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你能把这句话编码成符号吗？", "target_word": "编码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们编码过很多句子，玩得很开心。", "target_word": "编码", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "編碼", "label": "繁体"}, {"form": "编码了", "label": "体标"}, {"form": "编码过", "label": "体标"}], "register": "中性", "sense_fingerprint": "用符号代表信息，像写密码一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abf388ec-18fe-4bd8-8a47-45cf8777f83f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22280, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "画", "is_correct": false, "explanation": "语义：“画”指描绘图形，不能表示用数字给字母赋值。"}, {"text": "编码", "is_correct": true, "explanation": "正确：“用数字给每个字母编码”指用数字代表字母，与句意相合。"}, {"text": "涂", "is_correct": false, "explanation": "语义：“涂”指把颜色抹在表面，与用数字代表字母的意思不符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能与“字母”搭配表示对字母做的赋值操作，说“给字母唱”不通。"}], "explanations": {"画": "语义：“画”指描绘图形，不能表示用数字给字母赋值。", "编码": "正确：“用数字给每个字母编码”指用数字代表字母，与句意相合。", "涂": "语义：“涂”指把颜色抹在表面，与用数字代表字母的意思不符。", "唱": "搭配：“唱”不能与“字母”搭配表示对字母做的赋值操作，说“给字母唱”不通。"}, "sentence_index": 0, "correct_answer": "编码"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上编码一杯牛奶，很有营养。", "explanation": "这里应该用〈喝〉。编码指用符号代表信息，不能用来指喝东西；喝牛奶要说「喝」。"}, {"text": "她用铅笔编码了一张地图。", "explanation": "这里应该用〈绘制〉。绘制是用线条画出图形；编码是用符号代表信息，不能用来指画地图。"}, {"text": "他用毛笔把故事编码成了诗。", "explanation": "这里应该用〈写〉。写是用笔写出文字；编码是用符号代表信息，不能用来指把故事写成诗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22280, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃掉", "is_correct": false, "explanation": "语义：“吃掉”指把东西咽下去，不能用来表示用声音传递或处理秘密消息。"}, {"text": "编码", "is_correct": true, "explanation": "正确：“用声音编码秘密消息”指用声音代表消息内容，与游戏的情境相合。"}, {"text": "擦掉", "is_correct": false, "explanation": "语义：“擦掉”指抹去痕迹，与用声音传递秘密消息的语境不符。"}, {"text": "测量", "is_correct": false, "explanation": "搭配：“测量”的对象是长度、重量等可量化的东西，不与“秘密消息”搭配。"}], "explanations": {"吃掉": "语义：“吃掉”指把东西咽下去，不能用来表示用声音传递或处理秘密消息。", "编码": "正确：“用声音编码秘密消息”指用声音代表消息内容，与游戏的情境相合。", "擦掉": "语义：“擦掉”指抹去痕迹，与用声音传递秘密消息的语境不符。", "测量": "搭配：“测量”的对象是长度、重量等可量化的东西，不与“秘密消息”搭配。"}, "sentence_index": 6, "correct_answer": "编码"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她编码了一段新舞蹈，演出很成功。", "explanation": "这里应该用〈编排〉。“编排”指组织安排舞蹈、节目等；“编码”是用符号代表信息，不能用来指编排舞蹈。"}, {"text": "我们编码了一本新杂志，下个月出版。", "explanation": "这里应该用〈编辑〉。“编辑”指整理、修改稿件并出版刊物；“编码”是用符号代表信息，不能用来指编辑杂志。"}, {"text": "他编码了一份旅行计划，大家都很满意。", "explanation": "这里应该用〈编制〉。“编制”指做出计划、方案；“编码”是用符号代表信息，不能用来指制定计划。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22280, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把这段话编码了成数字。", "corrected_sentence": "他把这段话编码成了数字。", "error_description": "错误：“了”放在了“成”前，写成“编码了成”。正确形式是“编码成了”，“了”应放在结果补语“成”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22280, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这封信我已经编码了好。", "corrected_sentence": "这封信我已经编码好了。", "error_description": "错误：结果补语“好”放在了“了”后面，写成“编码了好”。正确形式是“编码好了”，结果补语“好”应紧接在动词“编码”之后，“了”放在句末。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
