INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22282, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "可能发生的事情。", "primary_collocate": null, "pronunciation": "kě néng xìng", "ipa": "kʰɤ˨˩˦ nəŋ˧˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "未来有很多可能性。", "target_word": "可能性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个计划还有别的可能性吗？", "target_word": "可能性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们来说说各种可能性。", "target_word": "可能性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他一直在找新的可能性。", "target_word": "可能性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "路只有一条，没有别的可能性。", "target_word": "可能性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两种可能性，我都想过。", "target_word": "可能性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的话让我看到了新的可能性。", "target_word": "可能性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师请大家写出三种可能性。", "target_word": "可能性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们先想想，还有哪些可能性？", "target_word": "可能性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子的未来充满了可能性。", "target_word": "可能性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "可能发生的某种情况或事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abf388ec-18fe-4bd8-8a47-45cf8777f83f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22282, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体积", "is_correct": false, "explanation": "搭配：“很多”不修饰“体积”，“未来有很多体积”不成立。"}, {"text": "历史", "is_correct": false, "explanation": "语义：“历史”指已经过去的事，与“未来”矛盾。"}, {"text": "可能性", "is_correct": true, "explanation": "正确：“可能性”指可能发生的事情，与“未来有很多”相符。"}, {"text": "过去", "is_correct": false, "explanation": "语义：“过去”与“未来”相反，不能作“未来有很多”的内容。"}], "explanations": {"体积": "搭配：“很多”不修饰“体积”，“未来有很多体积”不成立。", "历史": "语义：“历史”指已经过去的事，与“未来”矛盾。", "可能性": "正确：“可能性”指可能发生的事情，与“未来有很多”相符。", "过去": "语义：“过去”与“未来”相反，不能作“未来有很多”的内容。"}, "sentence_index": 0, "correct_answer": "可能性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的可能性很暴躁，经常发火。", "explanation": "这里应该用〈脾气〉。可能性指可能发生的事情，不能描述人的性情；说脾气暴躁要用「脾气」。"}, {"text": "这种材料的可能性很韧，不容易断。", "explanation": "这里应该用〈韧性〉。可能性指可能发生的事情，不能用来形容材料的柔韧；说材料的韧性要用「韧性」。"}, {"text": "这件东西的可能性很贵，我买不起。", "explanation": "这里应该用〈价格〉。可能性指可能发生的事情，不能形容东西的价钱；说价格高要用「价格」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22282, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年龄", "is_correct": false, "explanation": "搭配：“看到”的对象应是可见的新事物，不说“看到新的年龄”。"}, {"text": "呼吸", "is_correct": false, "explanation": "配价：“看到”不能带“呼吸”作宾语，呼吸不可见。"}, {"text": "可能性", "is_correct": true, "explanation": "正确：“新的可能性”指可以看到的新的可能，与“看到了新的”相符。"}, {"text": "味道", "is_correct": false, "explanation": "配价：“看到”不能带“味道”作宾语，味道不可见。"}], "explanations": {"年龄": "搭配：“看到”的对象应是可见的新事物，不说“看到新的年龄”。", "呼吸": "配价：“看到”不能带“呼吸”作宾语，呼吸不可见。", "可能性": "正确：“新的可能性”指可以看到的新的可能，与“看到了新的”相符。", "味道": "配价：“看到”不能带“味道”作宾语，味道不可见。"}, "sentence_index": 6, "correct_answer": "可能性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗面的可能性很烫，你先别吃。", "explanation": "这里应该用〈温度〉。可能性指可能发生的事情，不能用来说食物烫不烫；说烫不烫要用「温度」。"}, {"text": "这个杯子的可能性很优雅，我很喜欢。", "explanation": "这里应该用〈外形〉。可能性指可能发生的事情，不能用来形容杯子的样子；说外形优雅要用「外形」。"}, {"text": "这把吉他的可能性很好听，我很喜欢。", "explanation": "这里应该用〈声音〉。可能性指可能发生的事情，不能用来形容乐器的声音；说声音好听要用「声音」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22282, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们可以考虑几张可能性。", "corrected_sentence": "我们可以考虑几种可能性。", "error_description": "错误：“张”用于纸、桌子、脸等平面或面状的东西，不用来计量“可能性”。“可能性”应用量词“种”，正确形式是“我们可以考虑几种可能性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22282, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个计划有很多可能性们。", "corrected_sentence": "这个计划有很多可能性。", "error_description": "错误形式为“可能性们”，正确形式为“可能性”。“可能性”是抽象名词，不能加复数词尾“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
