INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22284, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做出某个人或东西的样子。", "primary_collocate": null, "pronunciation": "sù zào", "ipa": "su˥˩ tsɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "艺术家用泥土塑造了一个小女孩。", "target_word": "塑造", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位作家塑造了很多有趣的人物。", "target_word": "塑造", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好电影能塑造一个真实的英雄。", "target_word": "塑造", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "演员用声音塑造了这个角色。", "target_word": "塑造", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "家庭会塑造孩子的性格。", "target_word": "塑造", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司想塑造一个好形象。", "target_word": "塑造", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他正在用蜡塑造一只小鸟。", "target_word": "塑造", "complexity_tier": "T3", "furigana": "tā zhèng zài yòng là sù zào yì zhī xiǎo niǎo", "sentence_source": "generated"}, {"text": "读书可以塑造一个人的气质。", "target_word": "塑造", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市想把自己塑造成旅游城市。", "target_word": "塑造", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "画家用几笔就塑造出了老人的样子。", "target_word": "塑造", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "塑造了", "label": "体标"}, {"form": "塑造着", "label": "体标"}, {"form": "塑造过", "label": "体标"}], "register": "中性", "sense_fingerprint": "用材料或文字、表演做出人或物的形象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b76edc4-0981-45f9-b40b-13826adb3d03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22284, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "煮", "is_correct": false, "explanation": "语义：煮是烹饪的动作，不能用泥土煮出人物形象。"}, {"text": "浇灌", "is_correct": false, "explanation": "搭配：浇灌多用于植物或田地，不说用泥土浇灌人像。"}, {"text": "塑造", "is_correct": true, "explanation": "塑造：用材料做出人或物的形象，与「用泥土」「一个小女孩」相合。"}, {"text": "培养", "is_correct": false, "explanation": "语义：培养指培育生命，不是用材料做出形象，这里说不通。"}], "explanations": {"煮": "语义：煮是烹饪的动作，不能用泥土煮出人物形象。", "浇灌": "搭配：浇灌多用于植物或田地，不说用泥土浇灌人像。", "塑造": "塑造：用材料做出人或物的形象，与「用泥土」「一个小女孩」相合。", "培养": "语义：培养指培育生命，不是用材料做出形象，这里说不通。"}, "sentence_index": 0, "correct_answer": "塑造"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂塑造了很多汽车。", "explanation": "这里应该用〈制造〉。塑造指用材料或文字做出人或物的形象；成批生产汽车要用〈制造〉。"}, {"text": "工人塑造了一座桥。", "explanation": "这里应该用〈修建〉。塑造指做出人或物的形象，建造桥梁要用〈修建〉。"}, {"text": "画家塑造了一幅地图。", "explanation": "这里应该用〈绘制〉。塑造指做出人或物的形象，画地图要用〈绘制〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7df9bc8-1bcf-43c8-be31-eb6336a223a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22284, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "烤", "is_correct": false, "explanation": "语义：烤是加热食物的方式，蜡不能用来烤出小鸟。"}, {"text": "绣", "is_correct": false, "explanation": "搭配：绣需要线，不能用蜡去绣。"}, {"text": "塑造", "is_correct": true, "explanation": "塑造：用材料做出形象，与「用蜡」「小鸟」相合。"}, {"text": "烧", "is_correct": false, "explanation": "语义：烧会毁坏材料，与「做出一只小鸟」的语境相反。"}], "explanations": {"烤": "语义：烤是加热食物的方式，蜡不能用来烤出小鸟。", "绣": "搭配：绣需要线，不能用蜡去绣。", "塑造": "塑造：用材料做出形象，与「用蜡」「小鸟」相合。", "烧": "语义：烧会毁坏材料，与「做出一只小鸟」的语境相反。"}, "sentence_index": 6, "correct_answer": "塑造"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他塑造了这件衣服。", "explanation": "这里应该用〈清洗〉。塑造指做出人或物的形象，不指洗涤衣物。"}, {"text": "他塑造了一锅汤。", "explanation": "这里应该用〈煮〉。塑造指做出人或物的形象，不指烹饪食物；做汤要用〈煮〉。"}, {"text": "卡车塑造了货物。", "explanation": "这里应该用〈运输〉。塑造指做出形象，搬运货物要用〈运输〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7df9bc8-1bcf-43c8-be31-eb6336a223a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22284, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把这块木头塑造了成一只鸟。", "corrected_sentence": "他把这块木头塑造成一只鸟。", "error_description": "「塑造成」是固定结构，「了」不能插在「塑造」和「成」之间；去掉「了」，应为「塑造成」。学习者常误加「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7df9bc8-1bcf-43c8-be31-eb6336a223a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22284, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他正在用蜡塑造了一只小猫。", "corrected_sentence": "他正在用蜡塑造着一只小猫。", "error_description": "「正在」表示动作进行中，不能与「了」搭配。应为「正在……着」，把「了」换成「着」，学习者常误加「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7df9bc8-1bcf-43c8-be31-eb6336a223a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22286, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "偷懒", "is_correct": true, "explanation": "反义：“偷懒”指不肯出力、不认真做事，与“努力”意思相反。"}, {"text": "思考", "is_correct": false, "explanation": "无关：“思考”指用脑子想问题，与“努力”不构成反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "无关：“唱歌”指发出乐音，与“努力”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "无关：“散步”指慢慢走路，与“努力”不构成反义关系。"}], "correct_answer": "偷懒", "explanations": {"偷懒": "反义：“偷懒”指不肯出力、不认真做事，与“努力”意思相反。", "思考": "无关：“思考”指用脑子想问题，与“努力”不构成反义关系。", "唱歌": "无关：“唱歌”指发出乐音，与“努力”没有反义关系。", "散步": "无关：“散步”指慢慢走路，与“努力”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22286, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "懈怠", "is_correct": true, "explanation": "反义：“懈怠”指松懈、不肯努力，与“努力”意思相反。"}, {"text": "聊天", "is_correct": false, "explanation": "无关：“聊天”指随意交谈，与“努力”不构成反义关系。"}, {"text": "旅游", "is_correct": false, "explanation": "无关：“旅游”指外出游览，与“努力”没有反义关系。"}, {"text": "跳舞", "is_correct": false, "explanation": "无关：“跳舞”指随着音乐舞动身体，与“努力”不构成反义关系。"}], "correct_answer": "懈怠", "explanations": {"懈怠": "反义：“懈怠”指松懈、不肯努力，与“努力”意思相反。", "聊天": "无关：“聊天”指随意交谈，与“努力”不构成反义关系。", "旅游": "无关：“旅游”指外出游览，与“努力”没有反义关系。", "跳舞": "无关：“跳舞”指随着音乐舞动身体，与“努力”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22286, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "努力就是要一直加油去做一件事。", "primary_collocate": null, "pronunciation": "nǔ lì", "ipa": "nu˨˩˦ li˥˩", "syllable_count": 2, "sentences": [{"text": "我们要努力学习。", "target_word": "努力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他每天都很努力。", "target_word": "努力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她努力了三年，终于考上大学。", "target_word": "努力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了家人，他一直在努力工作。", "target_word": "努力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只要努力，你就能做好。", "target_word": "努力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我会努力记住每个人的名字。", "target_word": "努力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们努力让孩子过上好日子。", "target_word": "努力", "complexity_tier": "T3", "furigana": "tā men nǔ lì ràng hái zi guò shàng hǎo rì zi", "sentence_source": "generated"}, {"text": "虽然很累，她还是努力走到山顶。", "target_word": "努力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师希望大家努力把作业做完。", "target_word": "努力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他努力过很多次，但都没成功。", "target_word": "努力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "努力了", "label": "体标"}, {"form": "努力过", "label": "体标"}, {"form": "努努力", "label": "重叠"}], "register": "中性", "sense_fingerprint": "动词：拿出力气，坚持不懈地去做某件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca85f957-df35-4d8f-af57-1db695739dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22286, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "复习", "is_correct": false, "explanation": "语义：“复习”与后面的“学习”意思重复，句子不通顺。"}, {"text": "努力", "is_correct": true, "explanation": "“努力”表示尽力去做，修饰“学习”，句意通顺。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，后面不能直接带“学习”作宾语。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与“学习”意思相反，句意矛盾。"}], "explanations": {"复习": "语义：“复习”与后面的“学习”意思重复，句子不通顺。", "努力": "“努力”表示尽力去做，修饰“学习”，句意通顺。", "散步": "配价：“散步”是不及物动词，后面不能直接带“学习”作宾语。", "睡觉": "语义：“睡觉”与“学习”意思相反，句意矛盾。"}, "sentence_index": 0, "correct_answer": "努力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头很努力。", "explanation": "这里应该用〈沉重〉。“努力”形容人主动付出，石头的重量要用“沉重”，不能说“很努力”。"}, {"text": "这份工作很努力，不太适合我。", "explanation": "这里应该用〈费力〉。“努力”用于人主动付出，形容事情吃力要用“费力”。"}, {"text": "他很努力地摔了一跤。", "explanation": "这里应该用〈不小心〉。“努力”表示有意付出，摔跤是无意的，应说“不小心摔了一跤”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22286, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "玩耍", "is_correct": false, "explanation": "配价：“玩耍”是不及物动词，不能接“让孩子过上好日子”这样的兼语结构。"}, {"text": "努力", "is_correct": true, "explanation": "“努力”表示尽力去做，与“让孩子过上好日子”的目标相符，句意通顺。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”与“过上好日子”的积极目标相反，句意不通。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：“逃避”与“过上好日子”的目标矛盾，句子不通顺。"}], "explanations": {"玩耍": "配价：“玩耍”是不及物动词，不能接“让孩子过上好日子”这样的兼语结构。", "努力": "“努力”表示尽力去做，与“让孩子过上好日子”的目标相符，句意通顺。", "生病": "语义：“生病”与“过上好日子”的积极目标相反，句意不通。", "逃避": "语义：“逃避”与“过上好日子”的目标矛盾，句子不通顺。"}, "sentence_index": 6, "correct_answer": "努力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他努力遇上了车祸。", "explanation": "这里应该用〈遭遇〉。“努力”表示有意去争取，车祸是不由自己控制的意外，只能说“遭遇”。"}, {"text": "她努力被老板批评了。", "explanation": "这里应该用〈挨〉。“努力”表示主动付出，被批评是被动接受，要说“挨批评”。"}, {"text": "我努力地出生在北京。", "explanation": "这里应该用〈降生〉。“努力”指有意争取，出生不是人能选择的，应说“降生在北京”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22286, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他努力了学习了一个学期。", "corrected_sentence": "他努力学习了一个学期。", "error_description": "错误：“努力”作状语修饰“学习”时后面不能加“了”，“了”应紧跟动词“学习”，应说“他努力学习了一个学期。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22286, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她很努力得准备考试。", "corrected_sentence": "她很努力地准备考试。", "error_description": "错误：“努力”修饰动词“准备”时要用“地”，不能用“得”；“得”用于动词或形容词后作补语，应说“她很努力地准备考试。”，不能说“她很努力得准备考试。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22292, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
