INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22292, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两个人约好时间、地点一起玩。", "primary_collocate": null, "pronunciation": "yuē huì", "ipa": "ɥe˥ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "周末他们常去公园约会。", "target_word": "约会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和女朋友在咖啡店约会。", "target_word": "约会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们第一次约会就去看电影。", "target_word": "约会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们约会过很多次。", "target_word": "约会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天晚上他们约会了三个小时。", "target_word": "约会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她打扮得很漂亮，要去约会。", "target_word": "约会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们喜欢在河边约会，一边走一边聊天。", "target_word": "约会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想和我约会吗？", "target_word": "约会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们约会时，手机都关了。", "target_word": "约会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王很紧张，因为他明天要约会。", "target_word": "约会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "约会了", "label": "体标"}, {"form": "约会过", "label": "体标"}, {"form": "约会对象", "label": "复合"}, {"form": "約會", "label": "繁体"}], "register": "中性", "sense_fingerprint": "两个人约好后一起出去玩、谈恋爱式的见面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9da955b2-9cb2-4719-95b9-57d75913c78c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22292, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "约会", "is_correct": true, "explanation": "“约会”指两人约好见面，句中“周末常去公园”正好描述这种活动。"}, {"text": "上班", "is_correct": false, "explanation": "语义：上班是到单位工作，不能说周末常去公园上班。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是测验，不会常在公园进行，句意不通。"}, {"text": "莅临", "is_correct": false, "explanation": "语域：莅临是正式书面语，与口语句子不协调，也不能说他们去公园莅临。"}], "explanations": {"约会": "“约会”指两人约好见面，句中“周末常去公园”正好描述这种活动。", "上班": "语义：上班是到单位工作，不能说周末常去公园上班。", "考试": "语义：考试是测验，不会常在公园进行，句意不通。", "莅临": "语域：莅临是正式书面语，与口语句子不协调，也不能说他们去公园莅临。"}, "sentence_index": 0, "correct_answer": "约会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们每周在咖啡店约会，讨论工作。", "explanation": "这里应该用〈见面〉。约会多指恋爱式的约见，谈工作用见面。"}, {"text": "他约会奶奶去医院，一起吃午饭。", "explanation": "这里应该用〈陪伴〉。约会只用于两人之间的恋爱式见面，陪家人去医院要用陪伴。"}, {"text": "这台电脑明天要和打印机约会。", "explanation": "这里应该用〈配合〉。约会指两个人约好一起见面玩，电脑与打印机之间的协作要用配合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22292, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "约会", "is_correct": true, "explanation": "“约会”指两人约好见面，句中“一边走一边聊天”正好描述这种活动。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉不能一边走一边聊天，与句意冲突。"}, {"text": "加班", "is_correct": false, "explanation": "语义：加班是工作时间的延长，不能在河边一边走一边聊天地进行。"}, {"text": "结账", "is_correct": false, "explanation": "搭配：结账是付款，与“在河边”和“一边走一边聊天”的语境不搭配。"}], "explanations": {"约会": "“约会”指两人约好见面，句中“一边走一边聊天”正好描述这种活动。", "睡觉": "语义：睡觉不能一边走一边聊天，与句意冲突。", "加班": "语义：加班是工作时间的延长，不能在河边一边走一边聊天地进行。", "结账": "搭配：结账是付款，与“在河边”和“一边走一边聊天”的语境不搭配。"}, "sentence_index": 6, "correct_answer": "约会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他明天要去医院约会生病的朋友。", "explanation": "这里应该用〈探望〉。约会指恋爱式的约见，去医院看望生病的朋友要用探望。"}, {"text": "这次考试的约会很重要，大家都很紧张。", "explanation": "“约会”指约好的见面，考试不是约会，这里的词义用错了。"}, {"text": "他把约会寄给了朋友，朋友很开心。", "explanation": "这里应该用〈通知〉。约会指两人约好的见面，不能当作物品寄出；把见面安排告诉别人要用通知。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22292, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们昨天约会过三个小时。", "corrected_sentence": "我们昨天约会了三个小时。", "error_description": "表示已经完成的具体时段要用“了”，说“约会了三个小时”；“过”表示经历，不能与具体时段搭配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22292, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们昨天约会的很开心。", "corrected_sentence": "他们昨天约会得很开心。", "error_description": "补语标记错误：动词后引出补语要用「得」，说「约会得很开心」；「的」用于修饰名词，不能接在动词后引出补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
