INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22302, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很深的地方。", "primary_collocate": null, "pronunciation": "shēn céng", "ipa": "ʂən˥ tsʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "海水的深层很冷。", "target_word": "深层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的深层土壤很干净。", "target_word": "深层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把水管放到了地下的深层。", "target_word": "深层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖的深层有很多大鱼。", "target_word": "深层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "深层的水比上面的水干净。", "target_word": "深层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地下深层的土很湿。", "target_word": "深层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山的深层有一个大洞。", "target_word": "深层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水来自地下的深层。", "target_word": "深层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海的深层很黑，也很安静。", "target_word": "深层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳照不到海底的深层。", "target_word": "深层", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "深層", "label": "繁体"}, {"form": "深层次", "label": "复合"}], "register": "通用", "sense_fingerprint": "很深的地方，如水下、地下的深处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '027318f4-2b33-4396-a5c8-0febbc57a5e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22302, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "深层", "is_correct": true, "explanation": "「深层」指很深的地方，与「很冷」搭配，符合句意。"}, {"text": "高度", "is_correct": false, "explanation": "语义：「高度」说高低，海水不能说「高度很冷」。"}, {"text": "声音", "is_correct": false, "explanation": "语义：「声音」指听到的声响，不指海水的深处。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：「味道」可以说咸淡，不能说「很冷」。"}], "explanations": {"深层": "「深层」指很深的地方，与「很冷」搭配，符合句意。", "高度": "语义：「高度」说高低，海水不能说「高度很冷」。", "声音": "语义：「声音」指听到的声响，不指海水的深处。", "味道": "搭配：「味道」可以说咸淡，不能说「很冷」。"}, "sentence_index": 0, "correct_answer": "深层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "湖的深层上飘着很多落叶。", "explanation": "这里应该用〈表面〉。落叶漂在水面上，「深层」指很深的地方，不能用来指水面。"}, {"text": "这口井的深层有十米。", "explanation": "这里应该用〈深度〉。「深度」指从表面到底部的距离，可以用米来量，「深层」指很深的地方，不能说有几米。"}, {"text": "这座山的深层很高。", "explanation": "这里应该用〈海拔〉。「海拔」指高出海平面的高度，可以说高，「深层」指很深的地方，不能说「高」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0513fdf-1194-433e-86ab-311a913ce376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22302, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "深层", "is_correct": true, "explanation": "「深层」指山内部很深的地方，「有一个大洞」符合这一位置，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：「颜色」不能有「大洞」，山的颜色和洞不搭配。"}, {"text": "时间", "is_correct": false, "explanation": "语义：「时间」指时段，不占据山的空间位置。"}, {"text": "重量", "is_correct": false, "explanation": "语义：「重量」说轻重，不指山的某个位置。"}], "explanations": {"深层": "「深层」指山内部很深的地方，「有一个大洞」符合这一位置，符合句意。", "颜色": "搭配：「颜色」不能有「大洞」，山的颜色和洞不搭配。", "时间": "语义：「时间」指时段，不占据山的空间位置。", "重量": "语义：「重量」说轻重，不指山的某个位置。"}, "sentence_index": 6, "correct_answer": "深层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这栋楼的深层住着很多人。", "explanation": "这里应该用〈高层〉。楼房的上部是高层，「深层」指地下或水下很深的地方，不能指楼房。"}, {"text": "这片湖的深层很浅。", "explanation": "这里应该用〈浅层〉。「浅层」指较浅的部分，与「深层」意思相反，「深层」指很深的地方，不能说「很浅」。"}, {"text": "这棵树的深层开了很多花。", "explanation": "这里应该用〈树梢〉。花开在枝头，「深层」指很深的地方，不能指树的顶部。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0513fdf-1194-433e-86ab-311a913ce376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22302, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "池底的一只深层很黑。", "corrected_sentence": "池底的深层很黑。", "error_description": "量词错误：「深层」前不加「一只」，「只」用于动物或成对的器物，这里应直接说「池底的深层」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0513fdf-1194-433e-86ab-311a913ce376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22302, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地壳的深层地温度很高。", "corrected_sentence": "地壳的深层温度很高。", "error_description": "错误在于多出“地”。“深层”是名词，直接修饰“温度”，不需要“地”（“地”用于动词、形容词作状语）；应说“地壳的深层温度很高”，删去“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0513fdf-1194-433e-86ab-311a913ce376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
