INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22308, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "去学校听老师讲课。", "primary_collocate": null, "pronunciation": "shàng kè", "ipa": "ʂɑŋ˥˩ kʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "孩子们七点半就去学校上课。", "target_word": "上课", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天有三节课，要去上课了。", "target_word": "上课", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李生病了，今天不能去上课。", "target_word": "上课", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟上课很认真，每天都很开心。", "target_word": "上课", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们周末不上课，可以睡懒觉。", "target_word": "上课", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天坐公共汽车去学校上课。", "target_word": "上课", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，学生还是打着伞去上课。", "target_word": "上课", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥在大学上课，学的是历史。", "target_word": "上课", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面太吵，我们没办法安静地上课。", "target_word": "上课", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天他没去上课，因为发烧了。", "target_word": "上课", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上了课", "label": "体标"}, {"form": "上过课", "label": "体标"}, {"form": "上課", "label": "繁体"}], "register": "中性", "sense_fingerprint": "上课：去学校听老师讲课", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9da955b2-9cb2-4719-95b9-57d75913c78c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22308, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上课", "is_correct": true, "explanation": "“上课”指去学校听老师讲课，符合“孩子们七点半就去学校”的语境。"}, {"text": "放学", "is_correct": false, "explanation": "语义：放学是学生离开学校，与“去学校”方向相反，句意矛盾。"}, {"text": "回家", "is_correct": false, "explanation": "语义：回家与“去学校”方向相反，不能用来描述去学校的动作。"}, {"text": "下班", "is_correct": false, "explanation": "搭配：下班用于上班族结束工作，不能用来说孩子们。"}], "explanations": {"上课": "“上课”指去学校听老师讲课，符合“孩子们七点半就去学校”的语境。", "放学": "语义：放学是学生离开学校，与“去学校”方向相反，句意矛盾。", "回家": "语义：回家与“去学校”方向相反，不能用来描述去学校的动作。", "下班": "搭配：下班用于上班族结束工作，不能用来说孩子们。"}, "sentence_index": 0, "correct_answer": "上课"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从六岁起就上课，直到大学毕业。", "explanation": "这里应该用〈上学〉。上学指长期在学校读书，上课只指某节或某天的课，不能用来表示整个求学阶段。"}, {"text": "爸爸每天去公司上课，回家很累。", "explanation": "这里应该用〈上班〉。上课是听课或讲课，去公司工作要用上班。"}, {"text": "周末我去医院上课，看望生病的奶奶。", "explanation": "这里应该用〈探望〉。上课指去学校听老师讲课，去医院看望病人要用探望。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22308, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上课", "is_correct": true, "explanation": "“上课”指学生在学校听课，符合“下雨了，学生还是打着伞”的语境。"}, {"text": "上班", "is_correct": false, "explanation": "搭配：上班用于职工，不能用来说学生。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：打着伞去游泳与下雨撑伞的情境冲突，句意不通。"}, {"text": "莅临", "is_correct": false, "explanation": "语域：莅临是正式书面语，与口语句子不协调，也不能说学生去莅临。"}], "explanations": {"上课": "“上课”指学生在学校听课，符合“下雨了，学生还是打着伞”的语境。", "上班": "搭配：上班用于职工，不能用来说学生。", "游泳": "语义：打着伞去游泳与下雨撑伞的情境冲突，句意不通。", "莅临": "语域：莅临是正式书面语，与口语句子不协调，也不能说学生去莅临。"}, "sentence_index": 6, "correct_answer": "上课"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器每天早上七点上课。", "explanation": "这里应该用〈运行〉。上课指去学校听老师讲课，机器的工作要用运行。"}, {"text": "他去银行上课，办理了一笔存款。", "explanation": "这里应该用〈办理〉。上课指去学校听老师讲课，去银行办理业务要用「办理」。"}, {"text": "我每天下午去超市上课，顺便买菜回家。", "explanation": "这里应该用〈购物〉。上课指去学校听老师讲课，去超市买东西要用购物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22308, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天去学校上三只课。", "corrected_sentence": "他每天去学校上三节课。", "error_description": "量词错误：「课」的量词应为「节」，不能用「只」。应说「上三节课」，不说「上三只课」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22308, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我今天有三节课要上课。", "corrected_sentence": "我今天有三节课要上。", "error_description": "宾语重复错误：「上课」本身已含宾语「课」，「三节课」是「有」的宾语，又兼作「上」的对象，后面不能再加「课」，应说「有三节课要上」，不说「有三节课要上课」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
