INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22320, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "正好就是这个", "primary_collocate": null, "pronunciation": "zhèng shì", "ipa": "ʈʂɤŋ˥˩ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "现在正是春天，花都开了。", "target_word": "正是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你来得正是时候，饭刚做好。", "target_word": "正是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这正是我想要的礼物。", "target_word": "正是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正是我们找了很久的老师。", "target_word": "正是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "九月正是秋天，天气很舒服。", "target_word": "正是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这正是问题的关键。", "target_word": "正是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天正是她的生日，我送了她花。", "target_word": "正是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人正是我们的新经理。", "target_word": "正是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子十岁正是学游泳的好年纪。", "target_word": "正是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事正是他最担心的。", "target_word": "正是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "强调恰好就是所说的人、事物或时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b36993-6be1-4beb-8bc2-c6c37fd0d0a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22320, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "证实", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是证明属实。"}, {"text": "正是", "is_correct": true, "explanation": "正确答案：zhèng shì，意思是恰好就是所说的人、事物或时间。"}, {"text": "正史", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，意思是正式的历史记载。"}, {"text": "政治", "is_correct": false, "explanation": "zhì 与 shì 声母不同（zh 与 sh），意思是政治。"}, {"text": "阵势", "is_correct": false, "explanation": "zhèn 与 zhèng 韵尾不同（n 与 ng），意思是阵势、气势。"}], "explanations": {"证实": "shí（第二声）与 shì（第四声）声调不同，意思是证明属实。", "正是": "正确答案：zhèng shì，意思是恰好就是所说的人、事物或时间。", "正史": "shǐ（第三声）与 shì（第四声）声调不同，意思是正式的历史记载。", "政治": "zhì 与 shì 声母不同（zh 与 sh），意思是政治。", "阵势": "zhèn 与 zhèng 韵尾不同（n 与 ng），意思是阵势、气势。"}, "sentence_index": null, "correct_answer": "正是"}, "level_3": {"options": [{"text": "并不是", "is_correct": false, "explanation": "语义：“并不是”否定“春天”，与“花都开了”的描述相矛盾。"}, {"text": "正是", "is_correct": true, "explanation": "正确：“正是”强调恰好是春天，与“花都开了”相符。"}, {"text": "可不是", "is_correct": false, "explanation": "语域：“可不是”是口语应答语，不能用来陈述“现在是春天”。"}, {"text": "不一定是", "is_correct": false, "explanation": "语义：“不一定是”表示不确定，与“花都开了”的肯定描述不符。"}], "explanations": {"并不是": "语义：“并不是”否定“春天”，与“花都开了”的描述相矛盾。", "正是": "正确：“正是”强调恰好是春天，与“花都开了”相符。", "可不是": "语域：“可不是”是口语应答语，不能用来陈述“现在是春天”。", "不一定是": "语义：“不一定是”表示不确定，与“花都开了”的肯定描述不符。"}, "sentence_index": 0, "correct_answer": "正是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们正是吃饭呢，你先别进来。", "explanation": "这里应该用〈正在〉。“正是”用于确认人或事的所指，不表示动作正在进行，要用“正在”。"}, {"text": "这件衣服正是很漂亮。", "explanation": "这里应该用〈非常〉。“正是”用于确认所指，不表示程度，形容程度要用“非常”。"}, {"text": "我正是吃饱了，你们吃吧。", "explanation": "这里应该用〈刚刚〉。“正是”用于确认所指，不表示刚发生的动作，要用“刚刚”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c70bd67-1f70-4fec-9ce1-5b472ee1565d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22320, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一直是", "is_correct": false, "explanation": "语义：“一直是”表示持续，与“昨天”这一具体日子矛盾。"}, {"text": "正是", "is_correct": true, "explanation": "正确：“正是”强调恰好是某天是她的生日，与“我送了她花”相符。"}, {"text": "不会是", "is_correct": false, "explanation": "语义：“不会是”否定“她的生日”，与“我送了她花”的情境矛盾。"}, {"text": "绝不是", "is_correct": false, "explanation": "语义：“绝不是”完全否定，与“我送了她花”的语境矛盾。"}], "explanations": {"一直是": "语义：“一直是”表示持续，与“昨天”这一具体日子矛盾。", "正是": "正确：“正是”强调恰好是某天是她的生日，与“我送了她花”相符。", "不会是": "语义：“不会是”否定“她的生日”，与“我送了她花”的情境矛盾。", "绝不是": "语义：“绝不是”完全否定，与“我送了她花”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "正是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他正是回家了，你别等他了。", "explanation": "这里应该用〈刚刚〉。“正是”用于确认所指，不表示刚发生的动作，要用“刚刚”。"}, {"text": "这本书正是很厚。", "explanation": "这里应该用〈非常〉。“正是”用于确认所指，不表示程度，形容程度要用“非常”。"}, {"text": "这个房间正是很大。", "explanation": "这里应该用〈十分〉。“正是”用于确认所指，不表示程度，形容程度要用“十分”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c70bd67-1f70-4fec-9ce1-5b472ee1565d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22320, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是正是我们最需要的东西。", "corrected_sentence": "这正是我们最需要的东西。", "error_description": "错误：「正是」前多加了「是」。「正是」本身已表示恰好是，与「这」连用直接说「这正是」，不能再加「是」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c70bd67-1f70-4fec-9ce1-5b472ee1565d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22320, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个答案很正是我想要的。", "corrected_sentence": "这个答案正是我想要的。", "error_description": "错误：“很正是”。正确：“正是”。“正是”本身已表示强调，不能再加程度副词“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c70bd67-1f70-4fec-9ce1-5b472ee1565d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
