INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22322, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22322, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情就是人们做的一件事。", "primary_collocate": null, "pronunciation": "shì qing", "ipa": "ʂɻ̩⁵¹ tɕʰiŋ", "syllable_count": 2, "sentences": [{"text": "今天我有很多事情要做。", "target_word": "事情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事情很重要。", "target_word": "事情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把事情告诉了妈妈。", "target_word": "事情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道这件事情吗？", "target_word": "事情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情已经做完了。", "target_word": "事情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在教室里说了一件事情。", "target_word": "事情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想和你说一件有意思的事情。", "target_word": "事情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天发生了一件奇怪的事情。", "target_word": "事情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先做重要的事情，再玩手机。", "target_word": "事情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她总是把事情做得很好。", "target_word": "事情", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "件", "label": "量词"}], "register": "中性", "sense_fingerprint": "人们做的或发生的一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89604cde-aa36-49a3-b834-19b3606a7411') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22322, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "事情", "is_correct": true, "explanation": "“很多事情要做”指很多需要做的事，与句意相符，通顺。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不是需要去做的事，“很多河流要做”说不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能用“做”来处理，句意不通。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：“做”与“房间”不搭，应说“打扫房间”。"}], "explanations": {"事情": "“很多事情要做”指很多需要做的事，与句意相符，通顺。", "河流": "语义：河流不是需要去做的事，“很多河流要做”说不通。", "天气": "语义：天气不能用“做”来处理，句意不通。", "房间": "搭配：“做”与“房间”不搭，应说“打扫房间”。"}, "sentence_index": 0, "correct_answer": "事情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个事情很好用，大家都想买。", "explanation": "这里应该用〈东西〉。事情指人做的事，不能说“好用”，说有用处的物件要用东西。"}, {"text": "我想和你说一本事情。", "explanation": "这里的量词用错了。“本”用于书、本子，事情要用“件”，应说“一件事情”。"}, {"text": "这个事情很好吃，我很喜欢。", "explanation": "这里应该用〈菜〉。“好吃”形容食物，事情不能这样形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22322, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "事情", "is_correct": true, "explanation": "“说一件有意思的事情”指讲述一件有趣的事，与句意相符，通顺。"}, {"text": "衣服", "is_correct": false, "explanation": "语义：“说”的对象是话题或事情，不能说衣服，句意不通。"}, {"text": "行李", "is_correct": false, "explanation": "语义：行李不能作为“说”的内容，句意不通。"}, {"text": "家具", "is_correct": false, "explanation": "搭配：“说”一般接话题、事情，不接家具，搭配不当。"}], "explanations": {"事情": "“说一件有意思的事情”指讲述一件有趣的事，与句意相符，通顺。", "衣服": "语义：“说”的对象是话题或事情，不能说衣服，句意不通。", "行李": "语义：行李不能作为“说”的内容，句意不通。", "家具": "搭配：“说”一般接话题、事情，不接家具，搭配不当。"}, "sentence_index": 6, "correct_answer": "事情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事情的颜色很白，像雪一样。", "explanation": "这里应该用〈东西〉。“白”形容有颜色的东西，事情没有颜色，不能这样形容。"}, {"text": "我昨天做了一块事情。", "explanation": "这里的量词用错了。“块”用于成块的东西，事情应该用“件”。"}, {"text": "这道菜的事情很好，大家都爱吃。", "explanation": "这里应该用〈味道〉。菜的好坏要说味道，事情不能用来评价菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22322, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本事情我必须马上告诉你。", "corrected_sentence": "这件事情我必须马上告诉你。", "error_description": "错误形式：“这本事情”。正确形式：“这件事情”。“本”用于书、本子，“事情”应该用量词“件”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22322, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他已经事情做完了。", "corrected_sentence": "他已经把事情做完了。", "error_description": "错误形式：“他已经事情做完了”。“事情”是“做完”的宾语，不能直接放在动词前：可以用“把”提到动词前（“把事情做完”），也可以放在动词后（“做完事情了”）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22324, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe460a13-b349-4f9d-a31a-e0d890935749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22324, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe460a13-b349-4f9d-a31a-e0d890935749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22324, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "就是让别人不要生气，意思是“请别不高兴”。", "primary_collocate": null, "pronunciation": "bié shēng qì", "ipa": "pjɛ ʂɤŋ tɕʰi", "syllable_count": 3, "sentences": [{"text": "老师笑着说：“别生气，慢慢来。”", "target_word": "别生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看我不高兴，就说：“别生气。”", "target_word": "别生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别生气，这只是个小问题。", "target_word": "别生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐对哭着的小明说：“别生气。”", "target_word": "别生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学说错了话，你别生气。", "target_word": "别生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别生气，我们明天再谈。", "target_word": "别生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸对妈妈说：“别生气，我来做饭。”", "target_word": "别生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对朋友说：“别生气，是我的错。”", "target_word": "别生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人很不高兴，服务员说：“请别生气。”", "target_word": "别生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别生气啦，下次我一定准时。", "target_word": "别生气", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "别生气了", "label": "加了"}, {"form": "別生氣", "label": "繁体"}], "register": "口语", "sense_fingerprint": "请别人不要不高兴的安慰话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbaaaf73-74c4-4217-9399-ec60d52059ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22324, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "别生气", "is_correct": true, "explanation": "正确。「别生气，慢慢来」是劝慰语，与「老师笑着说」的语境相符，只有它能填入空格。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：「迟到」不能构成劝慰，「迟到，慢慢来」句意不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：「睡觉，慢慢来」与老师笑着劝人的语境无关，句意不通。"}, {"text": "下雨", "is_correct": false, "explanation": "搭配：「慢慢来」用于人的行为，天气不能被要求「慢慢来」，搭配不当。"}], "explanations": {"别生气": "正确。「别生气，慢慢来」是劝慰语，与「老师笑着说」的语境相符，只有它能填入空格。", "迟到": "语义：「迟到」不能构成劝慰，「迟到，慢慢来」句意不通。", "睡觉": "语义：「睡觉，慢慢来」与老师笑着劝人的语境无关，句意不通。", "下雨": "搭配：「慢慢来」用于人的行为，天气不能被要求「慢慢来」，搭配不当。"}, "sentence_index": 0, "correct_answer": "别生气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在图书馆里安静地看书，妈妈对我说：“别生气。”", "explanation": "「别生气」预设有人正在发怒，图书馆里大家都在安静看书，没有人生气，这里应该用「小声点」提醒别人。"}, {"text": "老人在公园里下棋，我走过去对他说：“别生气。”", "explanation": "「别生气」预设对方正在发怒，老人下棋时心情很好，这里不能这样劝，应该说「打扰了」。"}, {"text": "他没有生气，我却劝他：“别生气。”", "explanation": "「别生气」预设对方正在生气。对方没有生气时不能这样劝，应该用「没关系」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe460a13-b349-4f9d-a31a-e0d890935749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22324, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "别生气", "is_correct": true, "explanation": "正确。「别生气，我来做饭」是家人之间的劝慰语，只有它能填入空格。"}, {"text": "出门", "is_correct": false, "explanation": "语义：「出门，我来做饭」前后不接，句意不通。"}, {"text": "赴约", "is_correct": false, "explanation": "语域：「赴约」是书面语，与家人间的口语对话不合。"}, {"text": "考试", "is_correct": false, "explanation": "语义：「考试，我来做饭」与劝慰的语境无关，句意不通。"}], "explanations": {"别生气": "正确。「别生气，我来做饭」是家人之间的劝慰语，只有它能填入空格。", "出门": "语义：「出门，我来做饭」前后不接，句意不通。", "赴约": "语域：「赴约」是书面语，与家人间的口语对话不合。", "考试": "语义：「考试，我来做饭」与劝慰的语境无关，句意不通。"}, "sentence_index": 6, "correct_answer": "别生气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在银行排队办事，一直很耐心，我对他说：“别生气。”", "explanation": "「别生气」预设对方正在发怒，他很有耐心，没有生气，这里不能这样劝，应该说「辛苦了」。"}, {"text": "他把饭做得很香，全家都夸他，我却说：“别生气。”", "explanation": "「别生气」预设对方正在生气；全家都在夸他，他正高兴，这里应该说「做得真好」。"}, {"text": "我请朋友看电影，他很开心，我说：“别生气。”", "explanation": "这里是开心的语境。「别生气」是劝人不要发怒，这里应该用「别客气」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe460a13-b349-4f9d-a31a-e0d890935749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22324, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你别生气了了，我马上去买。", "corrected_sentence": "你别生气了，我马上去买。", "error_description": "错误形式「别生气了了」，句末「了」多写了一个。正确形式「别生气了」，「了」只用一次，放在句末。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe460a13-b349-4f9d-a31a-e0d890935749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22324, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爸爸，别生气过，我们明天再去。", "corrected_sentence": "爸爸，别生气了，我们明天再去。", "error_description": "错误形式「别生气过」，「过」表示经历过，劝阻的语境要用「了」表示事情的变化。正确形式「别生气了」，「了」应放在句末。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe460a13-b349-4f9d-a31a-e0d890935749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
