INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22330, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "尊敬别人，把别人看得重要。", "primary_collocate": null, "pronunciation": "zūn zhòng", "ipa": "tswən˥ ʈʂʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我们要尊重老师。", "target_word": "尊重", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请尊重别人的意见。", "target_word": "尊重", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他很尊重自己的父母。", "target_word": "尊重", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师尊重每一个学生的想法。", "target_word": "尊重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她尊重孩子的选择，没有反对。", "target_word": "尊重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在别人家里，要尊重他们的习惯。", "target_word": "尊重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好朋友会互相尊重，不会说坏话。", "target_word": "尊重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都很尊重这位老医生。", "target_word": "尊重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你不听我说话，就是不尊重我。", "target_word": "尊重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "到别的国家旅行，要尊重那里的文化。", "target_word": "尊重", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "尊重了", "label": "体标"}, {"form": "尊重过", "label": "体标"}], "register": "中性", "sense_fingerprint": "尊敬他人，重视他人的想法和感受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b76edc4-0981-45f9-b40b-13826adb3d03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22330, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "尊重", "is_correct": true, "explanation": "正确：“尊重”表示尊敬老师，与“我们要……老师”的语境相符。"}, {"text": "欺负", "is_correct": false, "explanation": "语义：“欺负”与尊敬老师的语境相反，“我们要欺负老师”不合常理。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”用于物品，不能用于老师，句子不通。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”搭配物品，不能说“搬运老师”。"}], "explanations": {"尊重": "正确：“尊重”表示尊敬老师，与“我们要……老师”的语境相符。", "欺负": "语义：“欺负”与尊敬老师的语境相反，“我们要欺负老师”不合常理。", "修理": "语义：“修理”用于物品，不能用于老师，句子不通。", "搬运": "搭配：“搬运”搭配物品，不能说“搬运老师”。"}, "sentence_index": 0, "correct_answer": "尊重"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校一直尊重安全教育。", "explanation": "这里应该用〈重视〉。尊重用于人的想法、感受、选择，对事情的重要性要用〈重视〉。"}, {"text": "他很尊重那块面包。", "explanation": "这里应该用〈吃〉。尊重指看重人、规律、文化等，不指吃东西；吃面包要用〈吃〉。"}, {"text": "他尊重了那个盒子。", "explanation": "这里应该用〈打开〉。尊重用于人的想法和感受，盒子要用〈打开〉，不能说“尊重盒子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7df9bc8-1bcf-43c8-be31-eb6336a223a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22330, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尊重", "is_correct": true, "explanation": "正确：“尊重”表示重视彼此，与“不会说坏话”的语境相符。"}, {"text": "偷窃", "is_correct": false, "explanation": "语义：“偷窃”与“好朋友”的意思相反，整句不通。"}, {"text": "摔倒", "is_correct": false, "explanation": "语义：摔倒是身体意外，与「互相尊重」的语境无关，「互相摔倒」说不通。"}, {"text": "迷路", "is_correct": false, "explanation": "语义：迷路指找不着方向，与「互相尊重」的语境无关，「互相迷路」说不通。"}], "explanations": {"尊重": "正确：“尊重”表示重视彼此，与“不会说坏话”的语境相符。", "偷窃": "语义：“偷窃”与“好朋友”的意思相反，整句不通。", "摔倒": "语义：摔倒是身体意外，与「互相尊重」的语境无关，「互相摔倒」说不通。", "迷路": "语义：迷路指找不着方向，与「互相尊重」的语境无关，「互相迷路」说不通。"}, "sentence_index": 6, "correct_answer": "尊重"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人每天都要尊重这台机器。", "explanation": "这里应该用〈维护〉。尊重用于对人的想法和感受，机器的保养要用〈维护〉。"}, {"text": "晚上他尊重窗外的雨声。", "explanation": "这里应该用〈欣赏〉。尊重不用于景色和声音，欣赏美好的事物才用〈欣赏〉。"}, {"text": "他每天都要尊重这扇窗户。", "explanation": "这里应该用〈擦〉。尊重用于人的想法和感受，窗户要用〈擦〉，不能说“尊重窗户”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7df9bc8-1bcf-43c8-be31-eb6336a223a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22330, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们应该尊重了彼此的隐私。", "corrected_sentence": "我们应该尊重彼此的隐私。", "error_description": "体标错误：“应该”表示义务，尚未实现，不能与“了”同用，应说“应该尊重彼此的隐私”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7df9bc8-1bcf-43c8-be31-eb6336a223a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22330, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们应该被尊重每个人的权利。", "corrected_sentence": "我们应该尊重每个人的权利。", "error_description": "被动误用：“尊重”后面已带宾语“每个人的权利”，不能再加“被”构成被动句，应去掉“被”，说“应该尊重每个人的权利”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7df9bc8-1bcf-43c8-be31-eb6336a223a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
