INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22332, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示坏的意思。", "primary_collocate": null, "pronunciation": "bù hǎo", "ipa": "pu˥˩ xɑʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "他的运气不好，今天又丢了钱包。", "target_word": "不好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服的颜色不好，我不喜欢。", "target_word": "不好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的睡眠不好，早上很累。", "target_word": "不好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板对他的印象不好，不想用他。", "target_word": "不好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法不好，会带来很多麻烦。", "target_word": "不好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟的习惯不好，常常忘记写作业。", "target_word": "不好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的服务不好，客人都不想再来。", "target_word": "不好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的字不好，别人看不懂。", "target_word": "不好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的内容不好，没有人想读。", "target_word": "不好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的视力不好，要戴眼镜。", "target_word": "不好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不好意思", "label": "复合"}], "register": "中性", "sense_fingerprint": "不好：表示坏、差、不令人满意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9da955b2-9cb2-4719-95b9-57d75913c78c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22332, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不好", "is_correct": true, "explanation": "正确：不好，指坏、差、不令人满意。"}, {"text": "不跑", "is_correct": false, "explanation": "声母不同：「不跑」以 p 开头，意思是不跑步。"}, {"text": "不搞", "is_correct": false, "explanation": "声母不同：「不搞」以 g 开头，意思是不做、不干。"}, {"text": "不倒", "is_correct": false, "explanation": "声母不同：「不倒」以 d 开头，意思是不倒下。"}, {"text": "不扫", "is_correct": false, "explanation": "声母不同：「不扫」以 s 开头，意思是不打扫。"}], "explanations": {"不好": "正确：不好，指坏、差、不令人满意。", "不跑": "声母不同：「不跑」以 p 开头，意思是不跑步。", "不搞": "声母不同：「不搞」以 g 开头，意思是不做、不干。", "不倒": "声母不同：「不倒」以 d 开头，意思是不倒下。", "不扫": "声母不同：「不扫」以 s 开头，意思是不打扫。"}, "sentence_index": null, "correct_answer": "不好"}, "level_3": {"options": [{"text": "不好", "is_correct": true, "explanation": "正确：「运气不好」才会「今天又丢了钱包」，只有「不好」与后半句相合。"}, {"text": "厚", "is_correct": false, "explanation": "搭配：「运气」不说「厚」，搭配不当。"}, {"text": "远", "is_correct": false, "explanation": "语义：「运气」不能用距离来形容，句子说不通。"}, {"text": "甜", "is_correct": false, "explanation": "语义：「甜」指味道，不能用来形容「运气」，句子说不通。"}], "explanations": {"不好": "正确：「运气不好」才会「今天又丢了钱包」，只有「不好」与后半句相合。", "厚": "搭配：「运气」不说「厚」，搭配不当。", "远": "语义：「运气」不能用距离来形容，句子说不通。", "甜": "语义：「甜」指味道，不能用来形容「运气」，句子说不通。"}, "sentence_index": 0, "correct_answer": "不好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个秘密我不好说，你直接去问他吧。", "explanation": "这里的「不好说」是不便说出口的意思，是另一个义项，与指坏的、不好的意思无关。"}, {"text": "我忘了还书，真不好意思。", "explanation": "「不好意思」表示难为情，是另一个义项，这里不是指坏的、不好的意思。"}, {"text": "我不好打扰他休息，你明天再来吧。", "explanation": "这里的「不好打扰」表示不便打扰，是另一个义项，与指坏的、不好的意思无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22332, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不好", "is_correct": true, "explanation": "正确：不好，指坏、差、不令人满意。"}, {"text": "不早", "is_correct": false, "explanation": "声母不同：「不早」以 z 开头，「不好」以 h 开头，意思是不早。"}, {"text": "不老", "is_correct": false, "explanation": "声母不同：「不老」以 l 开头，意思是不显老。"}, {"text": "不少", "is_correct": false, "explanation": "声母不同：「不少」以 sh 开头，意思是很多、不在少数。"}, {"text": "不考", "is_correct": false, "explanation": "声母不同：「不考」以 k 开头，意思是不参加考试。"}], "explanations": {"不好": "正确：不好，指坏、差、不令人满意。", "不早": "声母不同：「不早」以 z 开头，「不好」以 h 开头，意思是不早。", "不老": "声母不同：「不老」以 l 开头，意思是不显老。", "不少": "声母不同：「不少」以 sh 开头，意思是很多、不在少数。", "不考": "声母不同：「不考」以 k 开头，意思是不参加考试。"}, "sentence_index": null, "correct_answer": "不好"}, "level_3": {"options": [{"text": "不好", "is_correct": true, "explanation": "正确：「这里的服务不好」导致「客人都不想再来」，只有「不好」与后半句相合。"}, {"text": "高", "is_correct": false, "explanation": "语义：「高」指水平高，与「客人都不想再来」矛盾，句意说不通。"}, {"text": "轻", "is_correct": false, "explanation": "搭配：「服务」不能用重量来形容，说「轻」不通。"}, {"text": "窄", "is_correct": false, "explanation": "语义：「服务」不能用宽窄来形容，句子说不通。"}], "explanations": {"不好": "正确：「这里的服务不好」导致「客人都不想再来」，只有「不好」与后半句相合。", "高": "语义：「高」指水平高，与「客人都不想再来」矛盾，句意说不通。", "轻": "搭配：「服务」不能用重量来形容，说「轻」不通。", "窄": "语义：「服务」不能用宽窄来形容，句子说不通。"}, "sentence_index": 6, "correct_answer": "不好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事我不好评价，还是你来决定吧。", "explanation": "这里的「不好评价」表示不便评价，是另一个义项，与指坏的、不好的意思无关。"}, {"text": "这个话题我不好开口，你去问他吧。", "explanation": "这里的「不好开口」表示不便说出口，是另一个义项，与指坏的、不好的意思无关。"}, {"text": "这道题我不好回答，请你谅解。", "explanation": "这里的「不好回答」表示难以作答，是另一个义项，与指坏的、不好的意思无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22332, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把这次的成绩不好，妈妈很生气。", "corrected_sentence": "他这次的成绩不好，妈妈很生气。", "error_description": "句法错误：「把」字句要求后面是动作性动词作谓语，「不好」是形容词，不能用「把」引出「这次的成绩」，应去掉「把」，说「他这次的成绩不好」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22332, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他接待客人的时候做了不好，客人很生气。", "corrected_sentence": "他接待客人的时候做得不好，客人很生气。", "error_description": "补语错误：「做得不好」中补语要用「得」连接，不能用「了」，应说「做得不好」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22334, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "伤心", "is_correct": true, "explanation": "正确：「伤心」与「开心」意思相反，指心里非常难过。"}, {"text": "聪明", "is_correct": false, "explanation": "与「开心」没有反义关系，「聪明」指智力好。"}, {"text": "便宜", "is_correct": false, "explanation": "与「开心」没有反义关系，「便宜」指价钱低。"}, {"text": "干净", "is_correct": false, "explanation": "与「开心」没有反义关系，「干净」指没有脏东西。"}], "correct_answer": "伤心", "explanations": {"伤心": "正确：「伤心」与「开心」意思相反，指心里非常难过。", "聪明": "与「开心」没有反义关系，「聪明」指智力好。", "便宜": "与「开心」没有反义关系，「便宜」指价钱低。", "干净": "与「开心」没有反义关系，「干净」指没有脏东西。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6a458cc-0e81-446e-9b52-8645627b3211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22334, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "难过", "is_correct": true, "explanation": "正确：「难过」与「开心」意思相反，指心里不快乐。"}, {"text": "结实", "is_correct": false, "explanation": "与「开心」没有反义关系，「结实」指东西坚固或身体强壮。"}, {"text": "清楚", "is_correct": false, "explanation": "与「开心」没有反义关系，「清楚」指明白、不模糊。"}, {"text": "安全", "is_correct": false, "explanation": "与「开心」没有反义关系，「安全」指没有危险。"}], "correct_answer": "难过", "explanations": {"难过": "正确：「难过」与「开心」意思相反，指心里不快乐。", "结实": "与「开心」没有反义关系，「结实」指东西坚固或身体强壮。", "清楚": "与「开心」没有反义关系，「清楚」指明白、不模糊。", "安全": "与「开心」没有反义关系，「安全」指没有危险。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6a458cc-0e81-446e-9b52-8645627b3211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22334, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "心里感到很高兴。", "primary_collocate": null, "pronunciation": "kāi xīn", "ipa": "kʰai˥ ɕin˥", "syllable_count": 2, "sentences": [{"text": "今天我很开心。", "target_word": "开心", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们在公园里玩得很开心。", "target_word": "开心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "收到朋友的生日礼物，她特别开心。", "target_word": "开心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你为什么不开心？是不是考试没考好？", "target_word": "开心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到爸爸回家，小弟弟开心地跑了过去。", "target_word": "开心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他笑着说，今天是最开心的一天。", "target_word": "开心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友都来参加我的生日会，我开心极了。", "target_word": "开心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到好消息，大家都很开心。", "target_word": "开心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末和家人一起去海边，真开心！", "target_word": "开心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她考了第一名，开心得一晚上没睡着。", "target_word": "开心", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "开开心心", "label": "重叠"}, {"form": "不开心", "label": "否定形式"}], "register": "口语", "sense_fingerprint": "心情愉快，高兴", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '447b2f2c-611b-4adc-a6ed-b618209aaf2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22334, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高大", "is_correct": false, "explanation": "体貌：「高大」形容身材，不能用来说一个人今天的心情。"}, {"text": "开心", "is_correct": true, "explanation": "正确：「开心」表示心里高兴，可以用「很」修饰，描述今天的心情。"}, {"text": "陈旧", "is_correct": false, "explanation": "语义：「陈旧」指东西用久了、不新，不能用来形容人今天的心情。"}, {"text": "方便", "is_correct": false, "explanation": "搭配：「方便」形容事情或设施，不能用来形容人的心情。"}], "explanations": {"高大": "体貌：「高大」形容身材，不能用来说一个人今天的心情。", "开心": "正确：「开心」表示心里高兴，可以用「很」修饰，描述今天的心情。", "陈旧": "语义：「陈旧」指东西用久了、不新，不能用来形容人今天的心情。", "方便": "搭配：「方便」形容事情或设施，不能用来形容人的心情。"}, "sentence_index": 0, "correct_answer": "开心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把开心放进了柜子里，每天早上拿出来用一次。", "explanation": "这里不这么用：「开心」是形容词，表示心里高兴，不能当东西放进柜子；这里说的是心情，应该用〈快乐的心情〉之类的说法。"}, {"text": "她的成绩很开心，考试结果出来后大家都笑了。", "explanation": "这里不这么用：「开心」说的是人的心情，不能用来形容成绩；成绩好要说〈好〉或〈优秀〉。"}, {"text": "小王对妈妈很开心，每天都帮她做家务。", "explanation": "这里应该用〈好〉。「开心」说的是自己心里高兴，不能用来说对别人的态度；对人友好要用〈好〉，如「对妈妈很好」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6a458cc-0e81-446e-9b52-8645627b3211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22334, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冷清", "is_correct": false, "explanation": "语义：「冷清」指人少、没有热闹，与「朋友都来参加」矛盾。"}, {"text": "开心", "is_correct": true, "explanation": "正确：「开心」与「极了」搭配，说心里非常高兴。"}, {"text": "寂寞", "is_correct": false, "explanation": "语义：「寂寞」指孤单，与「朋友都来参加我的生日会」矛盾。"}, {"text": "瘦小", "is_correct": false, "explanation": "体貌：「瘦小」形容身材，不能用来说心情。"}], "explanations": {"冷清": "语义：「冷清」指人少、没有热闹，与「朋友都来参加」矛盾。", "开心": "正确：「开心」与「极了」搭配，说心里非常高兴。", "寂寞": "语义：「寂寞」指孤单，与「朋友都来参加我的生日会」矛盾。", "瘦小": "体貌：「瘦小」形容身材，不能用来说心情。"}, "sentence_index": 6, "correct_answer": "开心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他要把这个问题开心清楚，大家才能明白。", "explanation": "这里不这么用：「开心」是形容词，表示心里高兴，不能当动词说讲清问题；这里应该用〈讲清〉。"}, {"text": "他把这份作业开心了一下午，还没做完。", "explanation": "这里不这么用：「开心」是形容词，表示心里高兴，不能带「作业」作宾语；做作业要用〈做〉。"}, {"text": "她开心这个成绩，一直在笑。", "explanation": "这里应该用〈为……开心〉。「开心」是形容词，不能直接带「这个成绩」作宾语；表示为某事高兴要说「为……开心」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6a458cc-0e81-446e-9b52-8645627b3211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22334, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我今天很开心地，因为考试通过了。", "corrected_sentence": "我今天很开心，因为考试通过了。", "error_description": "错误：「很开心地」；正确：「很开心」。「开心」在这里作谓语，后面不加「地」；「地」只用来修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6a458cc-0e81-446e-9b52-8645627b3211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22334, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他收到录取通知，开心地一晚上没睡着。", "corrected_sentence": "他收到录取通知，开心得一晚上没睡着。", "error_description": "错误：「开心地一晚上没睡着」；正确：「开心得一晚上没睡着」。「开心」在这里作补语说明程度，要用「得」引出；「地」只用来修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6a458cc-0e81-446e-9b52-8645627b3211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22338, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "散会", "is_correct": true, "explanation": "正确：“散会”指会议结束，与“开会”构成反义。"}, {"text": "吃饭", "is_correct": false, "explanation": "“吃饭”是日常活动，与“开会”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”是休闲活动，与“开会”不构成反义。"}, {"text": "睡觉", "is_correct": false, "explanation": "“睡觉”是休息行为，与“开会”没有反义关系。"}], "correct_answer": "散会", "explanations": {"散会": "正确：“散会”指会议结束，与“开会”构成反义。", "吃饭": "“吃饭”是日常活动，与“开会”没有反义关系。", "散步": "“散步”是休闲活动，与“开会”不构成反义。", "睡觉": "“睡觉”是休息行为，与“开会”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c6e4eaf-bbef-40a3-834b-a2f5a9583caa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22338, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "散会", "is_correct": true, "explanation": "正确：“散会”指会议结束，与“开会”构成反义。"}, {"text": "唱歌", "is_correct": false, "explanation": "“唱歌”是娱乐活动，与“开会”没有反义关系。"}, {"text": "工作", "is_correct": false, "explanation": "“工作”是泛指的劳动，与“开会”不构成反义。"}, {"text": "写信", "is_correct": false, "explanation": "“写信”是个人的书面交流，与“开会”没有反义关系。"}], "correct_answer": "散会", "explanations": {"散会": "正确：“散会”指会议结束，与“开会”构成反义。", "唱歌": "“唱歌”是娱乐活动，与“开会”没有反义关系。", "工作": "“工作”是泛指的劳动，与“开会”不构成反义。", "写信": "“写信”是个人的书面交流，与“开会”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c6e4eaf-bbef-40a3-834b-a2f5a9583caa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22338, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "好多人坐在一起说话，商量事情。", "primary_collocate": null, "pronunciation": "kāi huì", "ipa": "kʰai˥ xuei˥˩", "syllable_count": 2, "sentences": [{"text": "明天上午九点，我们在会议室开会。", "target_word": "开会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理正在办公室里和同事们开会。", "target_word": "开会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司的人都到了，现在可以开会了。", "target_word": "开会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开会的时候，请把手机关掉。", "target_word": "开会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个星期一早上都要开会。", "target_word": "开会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天下午我们开会开了两个小时。", "target_word": "开会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说下午全校老师都要去开会。", "target_word": "开会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他开会迟到了，大家都在等他。", "target_word": "开会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开会前，大家先把桌子摆好。", "target_word": "开会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们开会讨论一下旅行的安排。", "target_word": "开会", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "开了会", "label": "体标（了）"}, {"form": "开过会", "label": "体标（过）"}, {"form": "开个会", "label": "离合"}], "register": "中性", "sense_fingerprint": "许多人聚在一起讨论、商量事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39e035a-dda2-4ec6-9ffc-89dfa7d4a654') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22338, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开会", "is_correct": true, "explanation": "正确：“开会”指好多人聚在一起商量事情，符合会议室的语境。"}, {"text": "开车", "is_correct": false, "explanation": "搭配：“开车”的对象是车辆，会议室里不能开车。"}, {"text": "跑步", "is_correct": false, "explanation": "语义：“跑步”是个人锻炼，与在会议室里商量事情的语境不符。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”是娱乐活动，与“明天上午九点”的工作安排不符。"}], "explanations": {"开会": "正确：“开会”指好多人聚在一起商量事情，符合会议室的语境。", "开车": "搭配：“开车”的对象是车辆，会议室里不能开车。", "跑步": "语义：“跑步”是个人锻炼，与在会议室里商量事情的语境不符。", "唱歌": "语义：“唱歌”是娱乐活动，与“明天上午九点”的工作安排不符。"}, "sentence_index": 0, "correct_answer": "开会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师在教室里开会，给学生讲了三个小时的历史。", "explanation": "这里应该用〈上课〉。开会指多人为商量事情而聚在一起，老师给学生讲课要用“上课”。"}, {"text": "周末我们在朋友家开会，一起吃蛋糕唱歌。", "explanation": "这里应该用〈聚会〉。开会指为商量事情而召集的会议，朋友吃喝唱歌是“聚会”。"}, {"text": "夏天我们去河里开会，穿着泳衣玩了一下午。", "explanation": "这里应该用〈游泳〉。开会不是娱乐活动，下河穿着泳衣玩要用“游泳”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c6e4eaf-bbef-40a3-834b-a2f5a9583caa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22338, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开会", "is_correct": true, "explanation": "正确：“开会”指集体商量事情，符合“全校老师都要去”的语境。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”是个人的身体状况，不能由全校老师集体去做。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”是个人的事，不能说全校老师都要去结婚。"}, {"text": "开庭", "is_correct": false, "explanation": "语域：“开庭”是司法用语，不用于学校的集体活动。"}], "explanations": {"开会": "正确：“开会”指集体商量事情，符合“全校老师都要去”的语境。", "生病": "语义：“生病”是个人的身体状况，不能由全校老师集体去做。", "结婚": "语义：“结婚”是个人的事，不能说全校老师都要去结婚。", "开庭": "语域：“开庭”是司法用语，不用于学校的集体活动。"}, "sentence_index": 6, "correct_answer": "开会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们下周在操场上开会，跑了一百米。", "explanation": "这里应该用〈比赛〉。开会指人为商量事情而聚在一起，在操场上跑步竞争要用“比赛”。"}, {"text": "我在房间里开会，玩了一下午的游戏。", "explanation": "这里应该用〈打游戏〉。开会指多人为商量事情而聚在一起，玩游戏要用“打游戏”。"}, {"text": "我们明天在公园里开会，跳了一下午的舞。", "explanation": "这里应该用〈跳舞〉。开会指多人为商量事情而聚在一起，在公园里跳了一下午的舞要用“跳舞”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c6e4eaf-bbef-40a3-834b-a2f5a9583caa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22338, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们下午三点开会议，别迟到。", "corrected_sentence": "我们下午三点开会，别迟到。", "error_description": "错误形式是“开会议”，正确形式是“开会”。“会”本身已含“会议”的意思，“开会”是离合词，不能再带宾语“会议”；要说“开会”或“召开会议”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c6e4eaf-bbef-40a3-834b-a2f5a9583caa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22338, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把开会推迟了一个小时。", "corrected_sentence": "我们把会推迟了一个小时。", "error_description": "错误形式是“把开会推迟”，正确形式是“把会推迟”。离合词“开会”不能整体作“把”字句的宾语，要把宾语“会”单独放在“把”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c6e4eaf-bbef-40a3-834b-a2f5a9583caa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22340, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "准时", "is_correct": true, "explanation": "准时：按规定的时间到达，与“迟到”相反。"}, {"text": "干净", "is_correct": false, "explanation": "干净：形容清洁，与“迟到”没有反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "热闹：形容场面人多而活跃，与“迟到”没有关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮：形容光线充足，与“迟到”没有关系。"}], "correct_answer": "准时", "explanations": {"准时": "准时：按规定的时间到达，与“迟到”相反。", "干净": "干净：形容清洁，与“迟到”没有反义关系。", "热闹": "热闹：形容场面人多而活跃，与“迟到”没有关系。", "明亮": "明亮：形容光线充足，与“迟到”没有关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd255a78-aea1-4968-8fb6-1b75f37cd5d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22340, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "准时", "is_correct": true, "explanation": "准时：按规定的时间到达，与“迟到”相反。"}, {"text": "认真", "is_correct": false, "explanation": "认真：形容做事专心细致，与“迟到”没有反义关系。"}, {"text": "轻松", "is_correct": false, "explanation": "轻松：形容不紧张、不费力，与“迟到”没有关系。"}, {"text": "便宜", "is_correct": false, "explanation": "便宜：形容价格低，与“迟到”没有关系。"}], "correct_answer": "准时", "explanations": {"准时": "准时：按规定的时间到达，与“迟到”相反。", "认真": "认真：形容做事专心细致，与“迟到”没有反义关系。", "轻松": "轻松：形容不紧张、不费力，与“迟到”没有关系。", "便宜": "便宜：形容价格低，与“迟到”没有关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd255a78-aea1-4968-8fb6-1b75f37cd5d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22340, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "比应该到的时间晚到。", "primary_collocate": null, "pronunciation": "chí dào", "ipa": "tʂʰɨ˧˥ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他今天早上又迟到了。", "target_word": "迟到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天开会，请大家不要迟到。", "target_word": "迟到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，路上很堵，我还是迟到了。", "target_word": "迟到", "complexity_tier": "T3", "furigana": "chí dào", "sentence_source": "generated"}, {"text": "老师问他为什么迟到。", "target_word": "迟到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来没有迟到过。", "target_word": "迟到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为起床太晚，小王上班迟到了十分钟。", "target_word": "迟到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怎么又迟到了？", "target_word": "迟到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怕迟到，所以跑着去学校。", "target_word": "迟到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影八点开始，迟到的人不能进去。", "target_word": "迟到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别着急，我们还没有迟到。", "target_word": "迟到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "迟到了", "label": "体标"}, {"form": "迟到过", "label": "体标"}, {"form": "遲到", "label": "繁体"}], "register": "中性", "sense_fingerprint": "比规定或约定的时间晚到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13b584fe-81b3-45c5-b43f-c258eb988e16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22340, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "迟到", "is_correct": true, "explanation": "迟到：比应该到的时间晚到，是本题要辨认的词。"}, {"text": "吃到", "is_correct": false, "explanation": "chīdào（第一声）与 chídào（第二声）只差声调，意思是吃到、尝到。"}, {"text": "直到", "is_correct": false, "explanation": "zhídào 与 chídào 声母不同（zh 与 ch），意思是一直到某个时间为止。"}, {"text": "赤道", "is_correct": false, "explanation": "chìdào（第四声）与 chídào 只差声调，指地球中间那条纬线。"}], "explanations": {"迟到": "迟到：比应该到的时间晚到，是本题要辨认的词。", "吃到": "chīdào（第一声）与 chídào（第二声）只差声调，意思是吃到、尝到。", "直到": "zhídào 与 chídào 声母不同（zh 与 ch），意思是一直到某个时间为止。", "赤道": "chìdào（第四声）与 chídào 只差声调，指地球中间那条纬线。"}, "sentence_index": null, "correct_answer": "迟到"}, "level_3": {"options": [{"text": "迟到", "is_correct": true, "explanation": "迟到：没有按时到达，放在“又……了”里符合语境。"}, {"text": "下班", "is_correct": false, "explanation": "语义：下班指一天的工作结束，与“今天早上”相矛盾。"}, {"text": "感谢", "is_correct": false, "explanation": "配价：感谢要带宾语（感谢某人、某事），这里缺少宾语。"}, {"text": "驾临", "is_correct": false, "explanation": "语域：驾临是书面敬语，不适合这句口语叙述。"}], "explanations": {"迟到": "迟到：没有按时到达，放在“又……了”里符合语境。", "下班": "语义：下班指一天的工作结束，与“今天早上”相矛盾。", "感谢": "配价：感谢要带宾语（感谢某人、某事），这里缺少宾语。", "驾临": "语域：驾临是书面敬语，不适合这句口语叙述。"}, "sentence_index": 0, "correct_answer": "迟到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他迟到了一下，才回答老师的问题。", "explanation": "这里应该用〈迟疑〉。迟到指比规定时间晚到，不能用来表示犹豫的停顿。"}, {"text": "我三十岁才学会游泳，比别人迟到了很多。", "explanation": "这里应该用〈晚〉。迟到只用于没有按时到达，学游泳的进度不能说迟到。"}, {"text": "他的脑子总是迟到，别人讲三遍他才明白。", "explanation": "这里应该用〈迟钝〉。迟到指没有按时到达，形容脑子反应慢要用“迟钝”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd255a78-aea1-4968-8fb6-1b75f37cd5d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22340, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "迟到", "is_correct": true, "explanation": "迟到：没有按时到达，符合对方责备的语气。"}, {"text": "去世", "is_correct": false, "explanation": "语义：去世指人死亡，对方还活着，不能说“又去世了”。"}, {"text": "出生", "is_correct": false, "explanation": "语义：出生只能发生一次，“又出生了”不合常理。"}, {"text": "光临", "is_correct": false, "explanation": "语域：光临是对客人的敬辞，用来责备对方时很不合适。"}], "explanations": {"迟到": "迟到：没有按时到达，符合对方责备的语气。", "去世": "语义：去世指人死亡，对方还活着，不能说“又去世了”。", "出生": "语义：出生只能发生一次，“又出生了”不合常理。", "光临": "语域：光临是对客人的敬辞，用来责备对方时很不合适。"}, "sentence_index": 6, "correct_answer": "迟到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "路上迟到了一会儿，他才到学校。", "explanation": "这里应该用〈耽搁〉。迟到指到达得晚，不能用来表示路上停留的时间。"}, {"text": "这块表每天迟到五分钟，我得把它调快一点。", "explanation": "这里应该用〈慢〉。迟到指人没有按时到达，表走得慢要说“慢”。"}, {"text": "我们在博物馆迟到了两个小时。", "explanation": "这里应该用〈停留〉。迟到指没有按时到达，不能表示在某地待的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd255a78-aea1-4968-8fb6-1b75f37cd5d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22340, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每次都迟到的很厉害。", "corrected_sentence": "他每次都迟到得很厉害。", "error_description": "“迟到”后面的程度补语要用“得”，不能用“的”。应说“迟到得很厉害”，“的”用于修饰名词，不接在动词后表示程度。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd255a78-aea1-4968-8fb6-1b75f37cd5d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22340, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妈妈从来没有迟到了。", "corrected_sentence": "我妈妈从来没有迟到过。", "error_description": "“从来没有……过”表示未有过的经历，动词后要用“过”，不用“了”。应说“从来没有迟到过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd255a78-aea1-4968-8fb6-1b75f37cd5d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
