INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22342, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把要做的事情想好顺序，一件一件做好。", "primary_collocate": null, "pronunciation": "ān pái", "ipa": "an˥ pʰai˧˥", "syllable_count": 2, "sentences": [{"text": "老师把明天的课安排好了。", "target_word": "安排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理安排我下周去上海出差。", "target_word": "安排", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末的时间，你是怎么安排的？", "target_word": "安排", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我已经安排了三个人去机场接客人。", "target_word": "安排", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈把这个星期的饭菜都安排好了。", "target_word": "安排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他安排得很好，大家都满意。", "target_word": "安排", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旅行的路线，朋友已经安排过了。", "target_word": "安排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你安排一个时间，我们见个面。", "target_word": "安排", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校安排新同学先参观图书馆。", "target_word": "安排", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事太多，我得好好安排安排。", "target_word": "安排", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "安排了", "label": "体标（了）"}, {"form": "安排过", "label": "体标（过）"}, {"form": "安排好", "label": "结果补语"}, {"form": "安排安排", "label": "重叠"}], "register": "中性", "sense_fingerprint": "事先把事情、人员或时间按顺序定好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39e035a-dda2-4ec6-9ffc-89dfa7d4a654') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22342, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "安排", "is_correct": true, "explanation": "正确：“安排”指事先定好事情的顺序，“把明天的课安排好了”符合语境。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”多指修理，与“把课安排好”的语境不符。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”搭配黑板、桌子这类具体物体，不能擦“课”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，“课”不能吃。"}], "explanations": {"安排": "正确：“安排”指事先定好事情的顺序，“把明天的课安排好了”符合语境。", "修": "语义：“修”多指修理，与“把课安排好”的语境不符。", "擦": "搭配：“擦”搭配黑板、桌子这类具体物体，不能擦“课”。", "吃": "语义：“吃”的对象是食物，“课”不能吃。"}, "sentence_index": 0, "correct_answer": "安排"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人安排了新的空调，明天就能用。", "explanation": "这里应该用〈安装〉。安排指事先定好人、事或时间的先后，不用于装设设备。"}, {"text": "他安排了我的自行车，现在能骑了。", "explanation": "这里应该用〈修理〉。安排不能用来表示修理东西。"}, {"text": "我安排了他一本书，他很高兴。", "explanation": "这里应该用〈送〉。安排的对象是事情或人员，不能用来表示把东西交给别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c6e4eaf-bbef-40a3-834b-a2f5a9583caa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22342, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "安排", "is_correct": true, "explanation": "正确：“安排”指事先定好顺序，“朋友已经安排过了”符合旅行路线的语境。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”的对象是食物，“路线”不能煮。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”搭配歌曲，不能说唱“路线”。"}, {"text": "煎", "is_correct": false, "explanation": "搭配：“煎”搭配食物，“路线”不能煎。"}], "explanations": {"安排": "正确：“安排”指事先定好顺序，“朋友已经安排过了”符合旅行路线的语境。", "煮": "语义：“煮”的对象是食物，“路线”不能煮。", "唱": "搭配：“唱”搭配歌曲，不能说唱“路线”。", "煎": "搭配：“煎”搭配食物，“路线”不能煎。"}, "sentence_index": 6, "correct_answer": "安排"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位建筑师安排了一座新的体育馆，外形特别漂亮。", "explanation": "这里应该用〈设计〉。安排是把事情定好次序，画图定出建筑外形要用“设计”。"}, {"text": "她安排了一封长信，给远方的朋友讲了很多事。", "explanation": "这里应该用〈写〉。安排是定事情的次序，写信要用“写”。"}, {"text": "油漆工安排了这面墙，颜色很漂亮。", "explanation": "这里应该用〈粉刷〉。安排是定事情的次序，给墙面涂上颜色要用“粉刷”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c6e4eaf-bbef-40a3-834b-a2f5a9583caa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22342, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我还没安排了三个人去机场接客人。", "corrected_sentence": "我还没安排三个人去机场接客人。", "error_description": "错误形式是“还没安排了”，正确形式是“还没安排”。“没”否定尚未发生的动作，用“没”时要去掉动态助词“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c6e4eaf-bbef-40a3-834b-a2f5a9583caa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22342, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把行程安排了。", "corrected_sentence": "我们把行程安排好了。", "error_description": "错误形式是“把行程安排了”，正确形式是“把行程安排好了”。“把”字句的动词后面要有结果补语，这里应补上“好”，表示安排完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c6e4eaf-bbef-40a3-834b-a2f5a9583caa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
