INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22346, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "朋友就是你喜欢和他一起玩的人。", "primary_collocate": null, "pronunciation": "péng you", "ipa": "pʰɤŋ˧˥ joʊ", "syllable_count": 2, "sentences": [{"text": "他是我最好的朋友。", "target_word": "朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我有一个朋友在北京工作。", "target_word": "朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我和朋友去看电影。", "target_word": "朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她朋友很多，每天都有人找她。", "target_word": "朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位朋友是我的同学。", "target_word": "朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友生病了，我去医院看他。", "target_word": "朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的朋友会说汉语吗？", "target_word": "朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想给朋友买一个生日礼物。", "target_word": "朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在新学校，我很快交了几个朋友。", "target_word": "朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友之间应该互相帮助。", "target_word": "朋友", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "朋友们", "label": "复数"}, {"form": "好朋友", "label": "复合"}], "register": "中性", "sense_fingerprint": "互相喜欢、常在一起的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d813a3-5c7c-4c35-a022-bcb120b67276') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22346, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电脑", "is_correct": false, "explanation": "语义：「电脑」是物品，不能指“我”最好的亲密关系对象"}, {"text": "朋友", "is_correct": true, "explanation": "正确。朋友指互相喜欢、常在一起的人，与“最好的”搭配"}, {"text": "身材", "is_correct": false, "explanation": "体貌：「身材」指体型外形，不指人际关系中的对象"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」是自然现象，不能指“我最好的”亲密关系对象"}], "explanations": {"电脑": "语义：「电脑」是物品，不能指“我”最好的亲密关系对象", "朋友": "正确。朋友指互相喜欢、常在一起的人，与“最好的”搭配", "身材": "体貌：「身材」指体型外形，不指人际关系中的对象", "天气": "语义：「天气」是自然现象，不能指“我最好的”亲密关系对象"}, "sentence_index": 0, "correct_answer": "朋友"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医院里的朋友我谁也不认识，他们都是来看病的。", "explanation": "这里应该用〈病人〉。朋友指彼此熟悉、有情谊的人，“谁也不认识”和“都是来看病的”与之矛盾，应说〈病人〉。"}, {"text": "公司里我从没见过的朋友都来参加了会议。", "explanation": "这里应该用〈同事〉。朋友指彼此熟悉、有情谊的人，“从没见过”与之矛盾，同单位工作的人要说〈同事〉"}, {"text": "我们班的朋友很多，我却一个也不认识。", "explanation": "这里应该用〈同学〉。同班学生之间应称〈同学〉，朋友指彼此熟悉、有情谊的人，“一个也不认识”与之矛盾"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc0cc312-6c8a-4816-81d1-52075941a40b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22346, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雨伞", "is_correct": false, "explanation": "语义：「雨伞」是物品，不会说话，不能作“会说汉语”的主语"}, {"text": "朋友", "is_correct": true, "explanation": "正确。朋友是人，可以会说汉语，与句子语境相符"}, {"text": "身高", "is_correct": false, "explanation": "体貌：「身高」指身体的高度，是外形特征，不指能说话的人"}, {"text": "椅子", "is_correct": false, "explanation": "语义：「椅子」是家具，不会说汉语，与句子语境不符"}], "explanations": {"雨伞": "语义：「雨伞」是物品，不会说话，不能作“会说汉语”的主语", "朋友": "正确。朋友是人，可以会说汉语，与句子语境相符", "身高": "体貌：「身高」指身体的高度，是外形特征，不指能说话的人", "椅子": "语义：「椅子」是家具，不会说汉语，与句子语境不符"}, "sentence_index": 6, "correct_answer": "朋友"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店里的朋友我一个也不认识，他们只是来买东西的。", "explanation": "这里应该用〈顾客〉。朋友指彼此熟悉、有情谊的人，“一个也不认识”与之矛盾，来买东西的人应说〈顾客〉。"}, {"text": "路上的朋友我都讨厌，一看见就躲开。", "explanation": "这里应该用〈路人〉。朋友指你喜欢一起玩的人，与“讨厌”“躲开”矛盾，路上的陌生人要说〈路人〉"}, {"text": "电影院里的朋友我谁也不认识，只好各看各的。", "explanation": "这里应该用〈观众〉。朋友指彼此熟悉、有情谊的人，“谁也不认识”与之矛盾，在电影院看片的人要说〈观众〉"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc0cc312-6c8a-4816-81d1-52075941a40b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22346, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有好几朋友，都在北京。", "corrected_sentence": "我有好几个朋友，都在北京。", "error_description": "“好几朋友”错误：“好几”后面的名词要带量词，应为“好几个朋友”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc0cc312-6c8a-4816-81d1-52075941a40b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22346, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在公司里认识了几个朋友们。", "corrected_sentence": "我在公司里认识了几个朋友。", "error_description": "“几个朋友们”错误：有数量词修饰时，“朋友”后不加“们”，应为“几个朋友”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc0cc312-6c8a-4816-81d1-52075941a40b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
