INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22350, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "时间是60分钟那么长。", "primary_collocate": null, "pronunciation": "xiǎo shí", "ipa": "ɕjɑʊ˨˩˦ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "做这顿饭用了两小时。", "target_word": "小时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一天有二十四个小时。", "target_word": "小时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等了一个小时，他还没来。", "target_word": "小时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天花一小时学中文。", "target_word": "小时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这趟车开了三个小时才到。", "target_word": "小时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天只睡了五个小时。", "target_word": "小时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一小时有六十分钟。", "target_word": "小时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生让我每隔四小时吃一次药。", "target_word": "小时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路走过去大约要半小时。", "target_word": "小时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在图书馆看书看了两个小时。", "target_word": "小时", "complexity_tier": "T3", "furigana": "tā zài túshūguǎn kàn shū kàn le liǎng gè xiǎoshí", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个小时", "label": "量词"}, {"form": "半个小时", "label": "复合"}, {"form": "小时工", "label": "复合"}, {"form": "小時", "label": "繁体"}], "register": "中性", "sense_fingerprint": "小时：时间长度，六十分钟那么长", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd4d851-86a9-4cfd-a310-ec607390ed11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22350, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "小时", "is_correct": true, "explanation": "小时：时间是六十分钟那么长。"}, {"text": "小事", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是小事，与时间长度无关。"}, {"text": "小诗", "is_correct": false, "explanation": "shī（第一声）与 shí（第二声）声调不同，意思是小诗。"}, {"text": "消失", "is_correct": false, "explanation": "xiāo（第一声）与 xiǎo（第三声）、shī（第一声）与 shí（第二声）声调都不同，意思是消失。"}, {"text": "小吃", "is_correct": false, "explanation": "chī 与 shí 声母不同（ch 与 sh），意思是小吃。"}], "explanations": {"小时": "小时：时间是六十分钟那么长。", "小事": "shì（第四声）与 shí（第二声）声调不同，意思是小事，与时间长度无关。", "小诗": "shī（第一声）与 shí（第二声）声调不同，意思是小诗。", "消失": "xiāo（第一声）与 xiǎo（第三声）、shī（第一声）与 shí（第二声）声调都不同，意思是消失。", "小吃": "chī 与 shí 声母不同（ch 与 sh），意思是小吃。"}, "sentence_index": null, "correct_answer": "小时"}, "level_3": {"options": [{"text": "小时", "is_correct": true, "explanation": "小时：做一顿饭用两小时，时长合理。"}, {"text": "年", "is_correct": false, "explanation": "语义：做一顿饭用两年，与日常经验不符。"}, {"text": "公里", "is_correct": false, "explanation": "搭配：“用了”后面说的是时间，不能用长度单位“公里”来计量。"}, {"text": "礼拜", "is_correct": false, "explanation": "语义：做一顿饭用两个礼拜，与语境完全不符。"}], "explanations": {"小时": "小时：做一顿饭用两小时，时长合理。", "年": "语义：做一顿饭用两年，与日常经验不符。", "公里": "搭配：“用了”后面说的是时间，不能用长度单位“公里”来计量。", "礼拜": "语义：做一顿饭用两个礼拜，与语境完全不符。"}, "sentence_index": 0, "correct_answer": "小时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他今年十二小时了。", "explanation": "这里应该用〈岁〉。问年龄要用“岁”，“小时”只表示时间长度，不能用来说人的年龄。"}, {"text": "这部电影我看了一只小时。", "explanation": "这里应该用〈个〉。小时作时长的量词是“个”，“只”不能修饰时间单位。"}, {"text": "妈妈每天早上六小时起床。", "explanation": "这里应该用〈六点〉。表示时刻要说“六点”，“六小时”表示时长，不能指一个时间点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22350, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "小时", "is_correct": true, "explanation": "小时：时间单位，一小时正好是六十分钟。"}, {"text": "小池", "is_correct": false, "explanation": "chí 与 shí 声母不同（ch 与 sh），意思是小池塘。"}, {"text": "晓事", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是懂事、明白事理。"}, {"text": "小视", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是轻视。"}, {"text": "小室", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是小房间。"}], "explanations": {"小时": "小时：时间单位，一小时正好是六十分钟。", "小池": "chí 与 shí 声母不同（ch 与 sh），意思是小池塘。", "晓事": "shì（第四声）与 shí（第二声）声调不同，意思是懂事、明白事理。", "小视": "shì（第四声）与 shí（第二声）声调不同，意思是轻视。", "小室": "shì（第四声）与 shí（第二声）声调不同，意思是小房间。"}, "sentence_index": null, "correct_answer": "小时"}, "level_3": {"options": [{"text": "小时", "is_correct": true, "explanation": "小时：一小时正好是六十分钟，句子成立。"}, {"text": "天", "is_correct": false, "explanation": "语义：一天远长于六十分钟，“一天有六十分钟”与事实不符。"}, {"text": "时辰", "is_correct": false, "explanation": "语域：“时辰”是古代的计时单位，现在很少单独使用，且约合两小时，与“六十分钟”不符。"}, {"text": "分钟", "is_correct": false, "explanation": "语义：一分钟本身就是六十秒，“一分钟有六十分钟”自相矛盾。"}], "explanations": {"小时": "小时：一小时正好是六十分钟，句子成立。", "天": "语义：一天远长于六十分钟，“一天有六十分钟”与事实不符。", "时辰": "语域：“时辰”是古代的计时单位，现在很少单独使用，且约合两小时，与“六十分钟”不符。", "分钟": "语义：一分钟本身就是六十秒，“一分钟有六十分钟”自相矛盾。"}, "sentence_index": 6, "correct_answer": "小时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们约好在明天三个小时见面。", "explanation": "这里应该用〈三点〉。表示时刻要说“三点”，“小时”表示时长，不能指某个时间点。"}, {"text": "他在图书馆读了一段小时的书。", "explanation": "这里应该用〈个〉。小时作时长的量词是“个”，“段”用于时间段或路程，不能直接修饰“小时”。"}, {"text": "这场雨下了两场小时。", "explanation": "这里应该用〈个〉。小时作时长的量词是“个”，“场”用于雨、电影、比赛等一次性事件，不能修饰时间长度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22350, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天在车站等了一场小时。", "corrected_sentence": "我昨天在车站等了一个小时。", "error_description": "量词错误：“场”用于比赛、电影、雨等一次性事件，不能修饰时长，小时作时长的量词应为“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22350, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她每天练两次小时钢琴。", "corrected_sentence": "她每天练两个小时钢琴。", "error_description": "“两次小时”用错了量词。“次”计算动作的次数，表示时长要用“个”，应为“两个小时”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
