INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22354, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22354, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用眼睛、耳朵或身体感觉到东西。", "primary_collocate": null, "pronunciation": "gǎn zhī", "ipa": "kan˨˩ ʈʂɻ̩˥˥", "syllable_count": 2, "sentences": [{"text": "我用手感知水有多热。", "target_word": "感知", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "鱼能感知水里的声音。", "target_word": "感知", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "眼睛可以感知光的亮和暗。", "target_word": "感知", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的皮肤感知到了风的方向。", "target_word": "感知", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "耳朵能感知很小的声音。", "target_word": "感知", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "闭上眼睛后，他靠身体感知周围的热度。", "target_word": "感知", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手指可以感知纸有多厚。", "target_word": "感知", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蛇用舌头感知空气里的气味。", "target_word": "感知", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地面轻轻动了，我立刻感知到了。", "target_word": "感知", "complexity_tier": "T3", "furigana": "dì miàn qīng qīng dòng le, wǒ lì kè gǎn zhī dào le.", "sentence_source": "generated"}, {"text": "盲人靠着手杖感知前面的路。", "target_word": "感知", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "感知到", "label": "结果补语形式"}, {"form": "感知了", "label": "完成体"}, {"form": "感知力", "label": "复合词"}], "register": "书面", "sense_fingerprint": "用眼、耳或身体直接感觉到事物（动词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd4d851-86a9-4cfd-a310-ec607390ed11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22354, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感知", "is_correct": true, "explanation": "正确。“感知”指用身体感觉到，与“用手”和“有多热”相符。"}, {"text": "看", "is_correct": false, "explanation": "语义：“看”靠眼睛完成，与句中的“用手”矛盾。"}, {"text": "听", "is_correct": false, "explanation": "语义：“听”靠耳朵完成，与句中的“用手”矛盾。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象是文字，不能说“写水有多热”。"}], "explanations": {"感知": "正确。“感知”指用身体感觉到，与“用手”和“有多热”相符。", "看": "语义：“看”靠眼睛完成，与句中的“用手”矛盾。", "听": "语义：“听”靠耳朵完成，与句中的“用手”矛盾。", "写": "搭配：“写”的对象是文字，不能说“写水有多热”。"}, "sentence_index": 0, "correct_answer": "感知"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我感知明天会下雨。", "explanation": "这里应该用〈预测〉。感知是通过感官觉察当下的事物，不能用来推断未来。"}, {"text": "他感知了老师的意见。", "explanation": "这里应该用〈听取〉。感知指用感官觉察，不用于接受别人的意见。"}, {"text": "他感知了一百块钱。", "explanation": "这里应该用〈花〉。感知指用感官觉察，不能表示花掉金钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22354, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "感知", "is_correct": true, "explanation": "正确。“感知”指用触觉感觉到，与“手指”和“纸有多厚”相符。"}, {"text": "闻", "is_correct": false, "explanation": "语义：“闻”靠鼻子完成，不能用手指去“闻”纸的厚度。"}, {"text": "尝", "is_correct": false, "explanation": "语义：“尝”靠味觉完成，与“手指”和“纸有多厚”不相符。"}, {"text": "念", "is_correct": false, "explanation": "搭配：“念”的对象是文字或句子，不能说“念纸有多厚”。"}], "explanations": {"感知": "正确。“感知”指用触觉感觉到，与“手指”和“纸有多厚”相符。", "闻": "语义：“闻”靠鼻子完成，不能用手指去“闻”纸的厚度。", "尝": "语义：“尝”靠味觉完成，与“手指”和“纸有多厚”不相符。", "念": "搭配：“念”的对象是文字或句子，不能说“念纸有多厚”。"}, "sentence_index": 6, "correct_answer": "感知"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他感知了作业。", "explanation": "这里应该用〈完成〉。感知指用感官觉察，不能表示做完某件任务。"}, {"text": "他感知那个人的名字。", "explanation": "这里应该用〈打听〉。感知是靠感官觉察，不能表示通过询问获得信息。"}, {"text": "他感知老师的电话号码。", "explanation": "这里应该用〈记得〉。感知表示当下的觉察，不表示记住已经知道的信息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22354, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他感知到的了远处的雷声。", "corrected_sentence": "他感知到了远处的雷声。", "error_description": "错误形式：“感知到的了远处的雷声”，在结果补语“到”后多加了“的”。正确形式：“感知到了远处的雷声”，“到”紧跟动词“感知”，“了”放在补语之后，不加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22354, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "蝙蝠用声音感知了到前方的障碍物。", "corrected_sentence": "蝙蝠用声音感知到了前方的障碍物。", "error_description": "错误形式：“感知了到”，结果补语“到”与“了”的顺序颠倒。正确形式：“感知到了”，“到”应紧跟动词，“了”放在补语之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
