INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22358, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "墨西哥人就是来自墨西哥的人。", "primary_collocate": null, "pronunciation": "mò xī gē rén", "ipa": "muɔ˥˩ ɕi˥ kɤ˥ ʐən˧˥", "syllable_count": 4, "sentences": [{"text": "那个学生是墨西哥人，名字叫马克。", "target_word": "墨西哥人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墨西哥人的生日会很热闹。", "target_word": "墨西哥人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在飞机上遇到了一位墨西哥人。", "target_word": "墨西哥人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆的老板是墨西哥人。", "target_word": "墨西哥人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "墨西哥人最爱吃玉米饼。", "target_word": "墨西哥人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不是美国人，是墨西哥人。", "target_word": "墨西哥人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说墨西哥人都很热情。", "target_word": "墨西哥人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们班有两个墨西哥人。", "target_word": "墨西哥人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "墨西哥人说西班牙语，我说汉语。", "target_word": "墨西哥人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他妈妈是墨西哥人，爸爸是中国人。", "target_word": "墨西哥人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "来自墨西哥的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '411da9e4-51a0-498e-b4c5-a2af973994ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22358, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "墨西哥", "is_correct": false, "explanation": "语义：“墨西哥”是国家，不是人，不能与“学生”构成身份说明。"}, {"text": "墨西哥城", "is_correct": false, "explanation": "语义：“墨西哥城”是城市名，不能作“学生”的身份。"}, {"text": "墨西哥风", "is_correct": false, "explanation": "搭配：“墨西哥风”指风格，不能用来说明一个人的国籍或身份。"}, {"text": "墨西哥人", "is_correct": true, "explanation": "“墨西哥人”指来自墨西哥的人，可以说明“学生”的国籍，与“名字叫马克”相符。"}], "explanations": {"墨西哥": "语义：“墨西哥”是国家，不是人，不能与“学生”构成身份说明。", "墨西哥城": "语义：“墨西哥城”是城市名，不能作“学生”的身份。", "墨西哥风": "搭配：“墨西哥风”指风格，不能用来说明一个人的国籍或身份。", "墨西哥人": "“墨西哥人”指来自墨西哥的人，可以说明“学生”的国籍，与“名字叫马克”相符。"}, "sentence_index": 0, "correct_answer": "墨西哥人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在墨西哥人工作了三年。", "explanation": "这里应该用〈墨西哥〉。“在……工作”后接地点，墨西哥人指人。"}, {"text": "这次会议在墨西哥人举行。", "explanation": "这里应该用〈墨西哥城〉。“在……举行”后接地点，墨西哥人指人。"}, {"text": "这首歌带有墨西哥人。", "explanation": "这里应该用〈墨西哥风〉。“带有”后接风格，墨西哥人指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cfad29-f526-4989-a5f1-bff446e93f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22358, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "墨西哥语", "is_correct": false, "explanation": "语义：“墨西哥语”是语言，不能“很热情”。"}, {"text": "墨西哥菜", "is_correct": false, "explanation": "搭配：“热情”形容人的态度，不能用于菜。"}, {"text": "墨西哥国旗", "is_correct": false, "explanation": "语义：国旗是物件，不能“很热情”。"}, {"text": "墨西哥人", "is_correct": true, "explanation": "“墨西哥人”是人，可以“很热情”，与句子相符。"}], "explanations": {"墨西哥语": "语义：“墨西哥语”是语言，不能“很热情”。", "墨西哥菜": "搭配：“热情”形容人的态度，不能用于菜。", "墨西哥国旗": "语义：国旗是物件，不能“很热情”。", "墨西哥人": "“墨西哥人”是人，可以“很热情”，与句子相符。"}, "sentence_index": 6, "correct_answer": "墨西哥人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他能说一点墨西哥人。", "explanation": "这里应该用〈墨西哥语〉。“说”后接语言，墨西哥人指人。"}, {"text": "这艘船要穿过墨西哥人。", "explanation": "这里应该用〈墨西哥湾〉。“穿过”后接水域或地点，墨西哥人指人。"}, {"text": "他拿到了墨西哥人。", "explanation": "这里应该用〈墨西哥国籍〉。“拿到”后接证件或身份，墨西哥人指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cfad29-f526-4989-a5f1-bff446e93f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22358, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天认识了一只墨西哥人。", "corrected_sentence": "我昨天认识了一位墨西哥人。", "error_description": "错误在量词：“墨西哥人”指人，量词“只”只用于动物，此处应改用“位”或“个”。正确说法是“一位墨西哥人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cfad29-f526-4989-a5f1-bff446e93f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22358, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那家店有三位墨西哥人们。", "corrected_sentence": "那家店有三位墨西哥人。", "error_description": "错误在“们”：“三位”已表示确定的人数，“墨西哥人”后面不能再加“们”。正确说法是“三位墨西哥人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cfad29-f526-4989-a5f1-bff446e93f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
