INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22364, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22364, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示“不管什么时候”的意思。", "primary_collocate": null, "pronunciation": "suí shí", "ipa": "swei˧˥ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "有事你可以随时找我。", "target_word": "随时", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们随时可以出发。", "target_word": "随时", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家店随时都有人。", "target_word": "随时", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你累了就随时告诉我。", "target_word": "随时", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生说，有问题可以随时打电话。", "target_word": "随时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气不好，比赛随时可能取消。", "target_word": "随时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，我们随时可以问她问题。", "target_word": "随时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他带着手机，随时能收到消息。", "target_word": "随时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店晚上也开门，你随时可以来买。", "target_word": "随时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水在杯子里，你渴了随时可以喝。", "target_word": "随时", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "随时随地", "label": "固定组合"}, {"form": "隨時", "label": "繁体"}], "register": "中性", "sense_fingerprint": "不管什么时候都可以或都有可能（副词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd4d851-86a9-4cfd-a310-ec607390ed11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22364, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "随时", "is_correct": true, "explanation": "正确。“随时”表示什么时候都可以找我，与“有事”相符。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”多与否定词连用，不能说“可以从来找我”。"}, {"text": "按时", "is_correct": false, "explanation": "语义：“按时”指在约定的时间，不表示任何时候都可以找我。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不经常，与“有事你可以……找我”的随时可找不符。"}], "explanations": {"随时": "正确。“随时”表示什么时候都可以找我，与“有事”相符。", "从来": "搭配：“从来”多与否定词连用，不能说“可以从来找我”。", "按时": "语义：“按时”指在约定的时间，不表示任何时候都可以找我。", "偶尔": "语义：“偶尔”表示不经常，与“有事你可以……找我”的随时可找不符。"}, "sentence_index": 0, "correct_answer": "随时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我随时告诉你了。", "explanation": "这里应该用〈已经〉。随时表示任何时候都可以，不能用于已经完成的动作。"}, {"text": "他被问住了，随时无法回答。", "explanation": "这里应该用〈当场〉。随时表示任何时候都可以，不表示当场立刻做出反应。"}, {"text": "他每天七点随时起床。", "explanation": "这里应该用〈按时〉。随时表示任何时候，不能与“七点”这样固定的钟点同时出现。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22364, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "随时", "is_correct": true, "explanation": "正确。“随时”表示任何时候都可以问，与“老师说”的允许相符。"}, {"text": "白白", "is_correct": false, "explanation": "语义：“白白”表示徒然、没有好处，与老师允许提问的语境不符。"}, {"text": "只好", "is_correct": false, "explanation": "语义：“只好”表示不得已而为之，与老师允许提问的语境相矛盾。"}, {"text": "早已", "is_correct": false, "explanation": "搭配：“早已”多与已经完成的动作连用，不与“可以问”搭配。"}], "explanations": {"随时": "正确。“随时”表示任何时候都可以问，与“老师说”的允许相符。", "白白": "语义：“白白”表示徒然、没有好处，与老师允许提问的语境不符。", "只好": "语义：“只好”表示不得已而为之，与老师允许提问的语境相矛盾。", "早已": "搭配：“早已”多与已经完成的动作连用，不与“可以问”搭配。"}, "sentence_index": 6, "correct_answer": "随时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他随时工作了十个小时。", "explanation": "这里应该用〈连续〉。随时表示任何时候都可以，不表示持续不断地做某件事。"}, {"text": "他随时考了一百分。", "explanation": "这里应该用〈居然〉。随时表示任何时候都可以，不表示出乎意料地取得某种结果。"}, {"text": "我随时去过北京。", "explanation": "这里应该用〈曾经〉。随时表示任何时候都可能，不能用来表示过去有过的经历。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22364, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们随时能都出门。", "corrected_sentence": "我们随时都能出门。", "error_description": "错误形式：“随时能都出门”，副词“都”没有紧跟“随时”。正确形式：“随时都能出门”，“都”应紧跟“随时”，放在助动词“能”之前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22364, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个问题随时地可以解决。", "corrected_sentence": "这个问题随时可以解决。", "error_description": "错误形式：“随时地”，副词“随时”后面多加了“地”。“随时”是副词，不需要加“地”，应为“随时可以”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22370, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "相同", "is_correct": true, "explanation": "正确。“相同”与“差别”相对，指两个东西之间没有不同之处。"}, {"text": "速度", "is_correct": false, "explanation": "速度指物体运动的快慢，与“差别”没有反义关系。"}, {"text": "温度", "is_correct": false, "explanation": "温度指冷热的程度，与“差别”没有反义关系。"}, {"text": "重量", "is_correct": false, "explanation": "重量指物体的轻重，与“差别”没有反义关系。"}], "correct_answer": "相同", "explanations": {"相同": "正确。“相同”与“差别”相对，指两个东西之间没有不同之处。", "速度": "速度指物体运动的快慢，与“差别”没有反义关系。", "温度": "温度指冷热的程度，与“差别”没有反义关系。", "重量": "重量指物体的轻重，与“差别”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb747d9-a693-4515-907d-dfb4b8efd201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22370, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "相同", "is_correct": true, "explanation": "正确。“相同”与“差别”相对，指两个东西之间没有不同之处。"}, {"text": "形状", "is_correct": false, "explanation": "形状指物体的外形，与“差别”没有反义关系。"}, {"text": "价格", "is_correct": false, "explanation": "价格指商品的价值用钱表示的数额，与“差别”没有反义关系。"}, {"text": "方向", "is_correct": false, "explanation": "方向指物体所朝的位置，与“差别”没有反义关系。"}], "correct_answer": "相同", "explanations": {"相同": "正确。“相同”与“差别”相对，指两个东西之间没有不同之处。", "形状": "形状指物体的外形，与“差别”没有反义关系。", "价格": "价格指商品的价值用钱表示的数额，与“差别”没有反义关系。", "方向": "方向指物体所朝的位置，与“差别”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb747d9-a693-4515-907d-dfb4b8efd201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22370, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "两个东西不一样的地方。", "primary_collocate": null, "pronunciation": "chā bié", "ipa": "ʈʂʰa˥ pje˧˥", "syllable_count": 2, "sentences": [{"text": "这两个苹果有什么差别？", "target_word": "差别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥和弟弟的差别很明显。", "target_word": "差别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机和电脑的差别是大小。", "target_word": "差别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两双鞋的差别只是颜色。", "target_word": "差别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我找不到这两张画的差别。", "target_word": "差别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两本书的差别不太大。", "target_word": "差别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你看一看，左右两张表格有什么差别？", "target_word": "差别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两种水果的差别在味道上。", "target_word": "差别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新车和旧车的差别很大。", "target_word": "差别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服和那件衣服几乎没有差别。", "target_word": "差别", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "差別", "label": "繁体"}], "register": "中性", "sense_fingerprint": "两个具体东西相比时看得出的不同之处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f5c53d1-4ea1-4d6d-9e6a-58003c554ebc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22370, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "差别", "is_correct": true, "explanation": "正确。句中问的是两个苹果之间看得出的不同之处，“差别”与句意相符。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：苹果没有年龄上的比较问题，“这两个苹果有什么年龄”不符合常识。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高指人或动物的身体高度，不能用来形容苹果。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：苹果没有脾气，“这两个苹果有什么脾气”与句意无关。"}], "explanations": {"差别": "正确。句中问的是两个苹果之间看得出的不同之处，“差别”与句意相符。", "年龄": "语义：苹果没有年龄上的比较问题，“这两个苹果有什么年龄”不符合常识。", "身高": "体貌：身高指人或动物的身体高度，不能用来形容苹果。", "脾气": "语义：苹果没有脾气，“这两个苹果有什么脾气”与句意无关。"}, "sentence_index": 0, "correct_answer": "差别"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个差别长两米，足够用了。", "explanation": "这里应该用〈绳子〉。差别是不同之处，不是有长度的东西，说“长两米”只能用于绳子这类实物。"}, {"text": "他的差别很好，能看清远处的字。", "explanation": "这里应该用〈视力〉。“好”用于视力、成绩等，差别是不同之处，不能说“差别很好”。"}, {"text": "我把那个差别放进了书包。", "explanation": "这里应该用〈东西〉。差别是抽象的不同之处，不是实物，装进书包的要说“东西”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb747d9-a693-4515-907d-dfb4b8efd201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22370, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "差别", "is_correct": true, "explanation": "正确。句中请人看左右两边有什么不同之处，“差别”与句意相符。"}, {"text": "心情", "is_correct": false, "explanation": "语义：两边的物品没有心情，“左右两边有什么心情”不符合常识。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人或动物的体型，不能用来形容左右两边的物品。"}, {"text": "性格", "is_correct": false, "explanation": "语义：物品没有性格，“左右两边有什么性格”与句意无关。"}], "explanations": {"差别": "正确。句中请人看左右两边有什么不同之处，“差别”与句意相符。", "心情": "语义：两边的物品没有心情，“左右两边有什么心情”不符合常识。", "身材": "体貌：身材指人或动物的体型，不能用来形容左右两边的物品。", "性格": "语义：物品没有性格，“左右两边有什么性格”与句意无关。"}, "sentence_index": 6, "correct_answer": "差别"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个差别的温度有三十度。", "explanation": "这里应该用〈水温〉。差别是不同之处，没有温度，不能说“有三十度”。"}, {"text": "我买了一个差别，很甜。", "explanation": "这里应该用〈西瓜〉。差别是抽象的不同之处，不能买，更不能说甜。"}, {"text": "这件衣服和那件衣服的差别很好吃。", "explanation": "这里应该用〈大〉或〈小〉。差别指不同之处，不能用“好吃”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb747d9-a693-4515-907d-dfb4b8efd201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22370, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个苹果有一场差别。", "corrected_sentence": "这两个苹果有一点差别。", "error_description": "量词错误：“差别”要用量词“点”或“种”，“场”用于比赛、雨、事件等，不能修饰“差别”。正确说法是“一点差别”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb747d9-a693-4515-907d-dfb4b8efd201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22370, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两个杯子的差别大很。", "corrected_sentence": "这两个杯子的差别很大。", "error_description": "状语位置错误：副词“很”要放在形容词“大”的前面，不能说“大很”。正确说法是“差别很大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb747d9-a693-4515-907d-dfb4b8efd201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
