INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22374, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "没有", "primary_collocate": null, "pronunciation": "méi", "ipa": "meɪ˧˥", "syllable_count": 1, "sentences": [{"text": "昨天我没去学校。", "target_word": "没", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他早上没吃饭，现在很饿。", "target_word": "没", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没看见你的手机。", "target_word": "没", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她还没回家，妈妈有点儿着急。", "target_word": "没", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书我没买，是朋友给我的。", "target_word": "没", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天太忙，我没喝水。", "target_word": "没", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没来上课，因为感冒了。", "target_word": "没", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在九点了，商店还没开门。", "target_word": "没", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说的话，我一句也没听懂。", "target_word": "没", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没带伞，所以衣服都湿了。", "target_word": "没", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "没有", "label": "复合"}, {"form": "沒", "label": "繁体"}], "register": "中性", "sense_fingerprint": "没：用在动词前，否定动作已经发生或存在", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea089b11-07da-4ae5-aa39-37efb2e90fe9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22374, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "没", "is_correct": true, "explanation": "没（méi）：副词，用在动词前，表示否定动作已经发生或存在。"}, {"text": "美", "is_correct": false, "explanation": "měi（第三声）与 méi（第二声）声调不同，意思是美丽。"}, {"text": "每", "is_correct": false, "explanation": "měi（第三声）与 méi（第二声）声调不同，意思是每个。"}, {"text": "妹", "is_correct": false, "explanation": "mèi（第四声）与 méi（第二声）声调不同，意思是妹妹。"}, {"text": "门", "is_correct": false, "explanation": "mén 与 méi 韵母不同（en 与 ei），意思是门。"}], "explanations": {"没": "没（méi）：副词，用在动词前，表示否定动作已经发生或存在。", "美": "měi（第三声）与 méi（第二声）声调不同，意思是美丽。", "每": "měi（第三声）与 méi（第二声）声调不同，意思是每个。", "妹": "mèi（第四声）与 méi（第二声）声调不同，意思是妹妹。", "门": "mén 与 méi 韵母不同（en 与 ei），意思是门。"}, "sentence_index": null, "correct_answer": "没"}, "level_3": {"options": [{"text": "不", "is_correct": false, "explanation": "体貌：“不”用于否定习惯或意愿，不能否定昨天已经发生的具体动作。"}, {"text": "没", "is_correct": true, "explanation": "没：否定已经发生的动作，与“昨天”这一具体的过去时间相符。"}, {"text": "别", "is_correct": false, "explanation": "语义：“别”表示劝阻或禁止，不能用来陈述昨天发生的事实。"}, {"text": "常常", "is_correct": false, "explanation": "语义：“常常”表示经常，与“昨天”这一次具体的时间矛盾。"}], "explanations": {"不": "体貌：“不”用于否定习惯或意愿，不能否定昨天已经发生的具体动作。", "没": "没：否定已经发生的动作，与“昨天”这一具体的过去时间相符。", "别": "语义：“别”表示劝阻或禁止，不能用来陈述昨天发生的事实。", "常常": "语义：“常常”表示经常，与“昨天”这一次具体的时间矛盾。"}, "sentence_index": 0, "correct_answer": "没"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我明天没去学校，因为要考试。", "explanation": "这里应该用〈不〉。“没”只否定已经发生或完成的动作，明天的计划要用“不”。"}, {"text": "我下个月没去北京，因为要工作。", "explanation": "这里应该用〈不〉。“没”只否定已经发生或完成的动作，下个月的安排要用“不”。"}, {"text": "他没是医生，他是老师。", "explanation": "这里应该用〈不〉。“是”的否定要说“不是”，不能用“没”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22374, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一定", "is_correct": false, "explanation": "语义：“一定”表示必然如此，与后句“因为感冒了”所说的缺课原因矛盾。"}, {"text": "没", "is_correct": true, "explanation": "没：否定已经发生的动作“来上课”，与后半句“因为感冒了”的原因相符。"}, {"text": "必须", "is_correct": false, "explanation": "语义：“必须”表示必要或义务，不能用来陈述他没来上课的事实。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经来上课”与“因为感冒了”（说明他没来的原因）互相矛盾。"}], "explanations": {"一定": "语义：“一定”表示必然如此，与后句“因为感冒了”所说的缺课原因矛盾。", "没": "没：否定已经发生的动作“来上课”，与后半句“因为感冒了”的原因相符。", "必须": "语义：“必须”表示必要或义务，不能用来陈述他没来上课的事实。", "已经": "语义：“已经来上课”与“因为感冒了”（说明他没来的原因）互相矛盾。"}, "sentence_index": 6, "correct_answer": "没"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们下周没去上海，因为要上课。", "explanation": "这里应该用〈不〉。“没”只否定已经发生或完成的动作，下周的安排要用“不”。"}, {"text": "他没应该去学校，因为他生病了。", "explanation": "这里应该用〈不〉。“应该”的否定要说“不应该”，“没”只否定已经发生的动作。"}, {"text": "妈妈明天没来接我，所以我自己回家。", "explanation": "这里应该用〈不〉。“没”只否定已经发生或完成的动作，明天的安排要用“不”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22374, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我前天去没学校。", "corrected_sentence": "我前天没去学校。", "error_description": "“没”应放在动词“去”之前，正确说法是「我前天没去学校」；“去没学校”的语序错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22374, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去没学校，因为下雨了。", "corrected_sentence": "他没去学校，因为下雨了。", "error_description": "“没”应放在动词“去”之前，正确说法是“没去学校”；“去没学校”的语序错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
