INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22376, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "有些事情不明白或者有困难。", "primary_collocate": null, "pronunciation": "wèn tí", "ipa": "wən˥˩ tʰi˧˥", "syllable_count": 2, "sentences": [{"text": "我的电脑出了问题，打不开了。", "target_word": "问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题太难，我想不出办法。", "target_word": "问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "如果你有问题，可以问老师。", "target_word": "问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他的身体没有问题，请放心。", "target_word": "问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的学习问题让妈妈很担心。", "target_word": "问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱不是问题，关键是时间。", "target_word": "问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起想办法，一定能解决问题。", "target_word": "问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车有问题，今天不能开。", "target_word": "问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师，我对这个句子有一个问题。", "target_word": "问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水太热会烫手，这是小问题，不用怕。", "target_word": "问题", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个问题", "label": "量词"}, {"form": "一些问题", "label": "量词"}, {"form": "问题少年", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：需要解决的困难或不明白的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb282ec0-1d20-4008-9f52-5b1110039fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22376, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "问题", "is_correct": true, "explanation": "问题：指电脑出的毛病或故障，与“打不开了”的语境相符。"}, {"text": "答案", "is_correct": false, "explanation": "语义：“答案”是问题的解答，不是电脑的故障，句意不通。"}, {"text": "笑话", "is_correct": false, "explanation": "语义：“笑话”指可笑的事，电脑打不开不是笑话。"}, {"text": "办法", "is_correct": false, "explanation": "语义：“办法”是解决问题的方法，电脑打不开的毛病不是办法，句意不通。"}], "explanations": {"问题": "问题：指电脑出的毛病或故障，与“打不开了”的语境相符。", "答案": "语义：“答案”是问题的解答，不是电脑的故障，句意不通。", "笑话": "语义：“笑话”指可笑的事，电脑打不开不是笑话。", "办法": "语义：“办法”是解决问题的方法，电脑打不开的毛病不是办法，句意不通。"}, "sentence_index": 0, "correct_answer": "问题"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他总是给我添问题。", "explanation": "这里应该用〈麻烦〉。“添”后接的是“麻烦”，不说“添问题”。"}, {"text": "我有一个问题想送给您。", "explanation": "这里应该用〈礼物〉。“问题”指有待解答的疑难，不能送给别人，送人的东西应说礼物。"}, {"text": "他的问题是三十岁。", "explanation": "这里应该用〈年龄〉。“问题”指疑难或毛病，不指岁数，说岁数要用年龄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d474c6-5243-4489-b129-456e059f3fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22376, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "问题", "is_correct": true, "explanation": "问题：指需要解决的困难，与“一定能解决”相符。"}, {"text": "食物", "is_correct": false, "explanation": "语义：“食物”不是需要解决的困难，“解决食物”句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是需要解决的困难，不能说“解决天气”。"}, {"text": "眼镜", "is_correct": false, "explanation": "搭配：“解决”的对象是困难或问题，“解决眼镜”不通。"}], "explanations": {"问题": "问题：指需要解决的困难，与“一定能解决”相符。", "食物": "语义：“食物”不是需要解决的困难，“解决食物”句意不通。", "天气": "语义：“天气”不是需要解决的困难，不能说“解决天气”。", "眼镜": "搭配：“解决”的对象是困难或问题，“解决眼镜”不通。"}, "sentence_index": 6, "correct_answer": "问题"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一个问题。", "explanation": "这里应该用〈饼干〉。“问题”指疑难，不能买，买的东西要说饼干。"}, {"text": "这个人的问题很好听。", "explanation": "这里应该用〈声音〉。“问题”指疑难，不能形容好听，形容声音才用好听。"}, {"text": "今天的问题很蓝。", "explanation": "这里应该用〈天空〉。“问题”没有颜色，形容蓝色的应是天空。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d474c6-5243-4489-b129-456e059f3fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22376, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们需要尽快解决了问题。", "corrected_sentence": "我们需要尽快解决问题。", "error_description": "“需要”表示尚未发生的需求，后面的动作还没有完成，“解决”后不加“了”。应说“我们需要尽快解决问题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d474c6-5243-4489-b129-456e059f3fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22376, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一个很难问题。", "corrected_sentence": "这是一个很难的问题。", "error_description": "“很难”修饰“问题”，中间要用“的”连接，应说“很难的问题”，不能说“很难问题”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d474c6-5243-4489-b129-456e059f3fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
