INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22378, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "意思是程度很高，比如“很”。", "primary_collocate": null, "pronunciation": "fēi cháng", "ipa": "fei˥ ʈʂʰaŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这个菜非常好吃。", "target_word": "非常", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今天天气非常好。", "target_word": "非常", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我昨天非常累，所以早早就睡了。", "target_word": "非常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北京的冬天非常冷，要多穿衣服。", "target_word": "非常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书非常有意思，我看了三遍。", "target_word": "非常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到这个消息，我非常高兴。", "target_word": "非常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说话的声音非常小，后面的同学听不见。", "target_word": "非常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店的人非常多，我们等了一个小时。", "target_word": "非常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他跑得非常快，一下子就赢了比赛。", "target_word": "非常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谢谢你的帮助，我非常感谢。", "target_word": "非常", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "程度副词，表示程度极高，用在形容词或心理动词前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '447b2f2c-611b-4adc-a6ed-b618209aaf2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22378, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "正在", "is_correct": false, "explanation": "语法：「正在」表示动作进行，不能直接修饰形容词「好吃」。"}, {"text": "非常", "is_correct": true, "explanation": "正确：「非常」表示程度很高，修饰形容词「好吃」。"}, {"text": "了", "is_correct": false, "explanation": "语法：「了」是助词，不能放在「这个菜」和「好吃」之间。"}, {"text": "着", "is_correct": false, "explanation": "语法：「着」是助词，不能放在「这个菜」和「好吃」之间。"}], "explanations": {"正在": "语法：「正在」表示动作进行，不能直接修饰形容词「好吃」。", "非常": "正确：「非常」表示程度很高，修饰形容词「好吃」。", "了": "语法：「了」是助词，不能放在「这个菜」和「好吃」之间。", "着": "语法：「着」是助词，不能放在「这个菜」和「好吃」之间。"}, "sentence_index": 0, "correct_answer": "非常"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我非常吃饭，一顿能吃三碗。", "explanation": "这里应该用〈很能〉。「非常」修饰形容词，表示程度，不能修饰「吃饭」这样的动作来表示吃得多；要说「很能吃」。"}, {"text": "他非常地忘了作业，老师很生气。", "explanation": "这里不这么用：「非常」表示程度，只修饰形容词和部分心理动词，不能修饰「忘」这样的动作；这里不是表示程度很高。"}, {"text": "他非常上学，每天都不迟到。", "explanation": "这里应该用〈每天〉。「非常」表示程度，不表示频率，「上学」这样的动作不能用「非常」修饰；要说「每天上学」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6a458cc-0e81-446e-9b52-8645627b3211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22378, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不", "is_correct": false, "explanation": "语义：「不小」与后面的「听不见」矛盾，声音不小，后排就听得见。"}, {"text": "非常", "is_correct": true, "explanation": "正确：「非常」表示程度很高，与「后面的同学听不见」的原因相符。"}, {"text": "的", "is_correct": false, "explanation": "语法：「的」是结构助词，「声音的小」不成立，不能放在「声音」和「小」之间表示程度。"}, {"text": "在", "is_correct": false, "explanation": "语法：「在」不能直接放在「声音」和「小」之间，「在小」不成立。"}], "explanations": {"不": "语义：「不小」与后面的「听不见」矛盾，声音不小，后排就听得见。", "非常": "正确：「非常」表示程度很高，与「后面的同学听不见」的原因相符。", "的": "语法：「的」是结构助词，「声音的小」不成立，不能放在「声音」和「小」之间表示程度。", "在": "语法：「在」不能直接放在「声音」和「小」之间，「在小」不成立。"}, "sentence_index": 6, "correct_answer": "非常"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他非常在学校里学习，成绩很好。", "explanation": "这里不这么用：「非常」是程度副词，不能修饰「在学校里学习」这样的动作和地点；表示地点要用「在……」，程度要用「非常」修饰形容词。"}, {"text": "今天的作业比昨天非常多，我写到很晚。", "explanation": "这里不这么用：比较句中不能用「非常」，它表示绝对的程度；比较时要用「更」，如「比昨天更多」。"}, {"text": "这把椅子非常木头。", "explanation": "「木头」表示材料，没有程度的差别，不能用「非常」修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6a458cc-0e81-446e-9b52-8645627b3211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22378, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条路的风景非常美，我们非常走了很久。", "corrected_sentence": "这条路的风景非常美，我们走了很久。", "error_description": "错误：「我们非常走了很久」；正确：「我们走了很久」。「非常」是程度副词，只修饰形容词，不能放在「走」这样的动作动词前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6a458cc-0e81-446e-9b52-8645627b3211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22378, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店的菜很非常便宜，学生都爱来。", "corrected_sentence": "这家店的菜非常便宜，学生都爱来。", "error_description": "错误：「很非常便宜」；正确：「非常便宜」。「很」和「非常」都表示程度，同一个形容词前面只用一个。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6a458cc-0e81-446e-9b52-8645627b3211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22380, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c6e4eaf-bbef-40a3-834b-a2f5a9583caa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22380, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c6e4eaf-bbef-40a3-834b-a2f5a9583caa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22380, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "两个人做同样的事情给对方。", "primary_collocate": null, "pronunciation": "hù xiāng", "ipa": "xu˥˩ ɕiaŋ˥", "syllable_count": 2, "sentences": [{"text": "同学们互相帮助，学习进步很快。", "target_word": "互相", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们是好朋友，常常互相写信。", "target_word": "互相", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们互相看着对方，不说话。", "target_word": "互相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居之间应该互相关心。", "target_word": "互相", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个孩子互相送了一个小礼物。", "target_word": "互相", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家互相介绍了自己的名字。", "target_word": "互相", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我和她互相学习对方的语言。", "target_word": "互相", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛以后，两个队互相握手。", "target_word": "互相", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夫妻俩互相理解，很少吵架。", "target_word": "互相", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们互相认识已经三年了。", "target_word": "互相", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "双方彼此对对方做同样的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39e035a-dda2-4ec6-9ffc-89dfa7d4a654') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22380, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "互相", "is_correct": true, "explanation": "正确：“互相”表示双方彼此做同样的事，“同学们互相帮助”符合语境。"}, {"text": "独自", "is_correct": false, "explanation": "语义：“独自”指一个人单独做，与“同学们”的复数主语矛盾。"}, {"text": "白白", "is_correct": false, "explanation": "语义：“白白”表示徒劳无功，与后文“学习进步很快”矛盾。"}, {"text": "特此", "is_correct": false, "explanation": "语域：“特此”是公文用语，不用于这种叙述。"}], "explanations": {"互相": "正确：“互相”表示双方彼此做同样的事，“同学们互相帮助”符合语境。", "独自": "语义：“独自”指一个人单独做，与“同学们”的复数主语矛盾。", "白白": "语义：“白白”表示徒劳无功，与后文“学习进步很快”矛盾。", "特此": "语域：“特此”是公文用语，不用于这种叙述。"}, "sentence_index": 0, "correct_answer": "互相"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我互相去超市买菜，很快就回来了。", "explanation": "这里应该用〈自己〉。互相要求双方彼此做同样的事，这里只有我一个人去超市，应说“自己”去。"}, {"text": "放学后，他们互相回家，走了不同的路。", "explanation": "这里应该用〈各自〉。“走了不同的路”说明各自行动，互相强调的是彼此对对方做同样的事，不能用于这里。"}, {"text": "他互相完成了这份作业。", "explanation": "这里应该用〈独立〉。互相需要双方或多方彼此做同样的事，一个人完成作业不能用互相。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c6e4eaf-bbef-40a3-834b-a2f5a9583caa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22380, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "互相", "is_correct": true, "explanation": "正确：“互相”表示双方彼此对对方做同样的事，“我和她互相学习”符合语境。"}, {"text": "单独", "is_correct": false, "explanation": "语义：“单独”强调各自或独自进行，与“互相”双方对对方做同样的事不符。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：“偏偏”表示与预期相反，句中没有这种语境。"}, {"text": "故", "is_correct": false, "explanation": "语域：“故”是书面语，口语叙述中不用。"}], "explanations": {"互相": "正确：“互相”表示双方彼此对对方做同样的事，“我和她互相学习”符合语境。", "单独": "语义：“单独”强调各自或独自进行，与“互相”双方对对方做同样的事不符。", "偏偏": "语义：“偏偏”表示与预期相反，句中没有这种语境。", "故": "语域：“故”是书面语，口语叙述中不用。"}, "sentence_index": 6, "correct_answer": "互相"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天互相照顾我，我从来不照顾她。", "explanation": "这里误把〈互相〉用于妈妈单方面照顾我的行为，应该用〈经常〉表示“常常”。互相要求双方彼此做同样的事，只有一方在照顾时不能用它。"}, {"text": "学生们互相听老师讲课，每节课都做笔记。", "explanation": "这里应该用〈认真〉来描述听课的态度。互相要求双方彼此做同样的事，学生听讲是单方面的，不能用互相。"}, {"text": "老板每个月互相给员工发工资，员工从来不发工资给老板。", "explanation": "这里应该用〈按时〉。互相要求双方彼此做同样的事，老板给员工发工资是单方面的，应说“按时”发放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c6e4eaf-bbef-40a3-834b-a2f5a9583caa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22380, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同学们互相互相鼓励，关系很好。", "corrected_sentence": "同学们互相鼓励，关系很好。", "error_description": "错误形式是“互相互相鼓励”，正确形式是“互相鼓励”。“互相”只说一次，重复使用是多余的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c6e4eaf-bbef-40a3-834b-a2f5a9583caa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22380, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个人互相了帮忙，把房间收拾干净。", "corrected_sentence": "两个人互相帮忙，把房间收拾干净。", "error_description": "错误形式是“互相了帮忙”，正确形式是“互相帮忙”。“了”表示完成，要放在动词之后，不能插在副词“互相”和动词“帮忙”中间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c6e4eaf-bbef-40a3-834b-a2f5a9583caa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22382, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "勇敢", "is_correct": false, "explanation": "“勇敢”指不怕困难和危险，与“礼貌”的意思无关。"}, {"text": "粗鲁", "is_correct": true, "explanation": "“粗鲁”指言语动作粗俗、不讲礼节，是“礼貌”的反义词。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”指头脑反应快，与“礼貌”的意思无关。"}, {"text": "健壮", "is_correct": false, "explanation": "“健壮”指身体强壮，与“礼貌”的意思无关。"}], "correct_answer": "粗鲁", "explanations": {"勇敢": "“勇敢”指不怕困难和危险，与“礼貌”的意思无关。", "粗鲁": "“粗鲁”指言语动作粗俗、不讲礼节，是“礼貌”的反义词。", "聪明": "“聪明”指头脑反应快，与“礼貌”的意思无关。", "健壮": "“健壮”指身体强壮，与“礼貌”的意思无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ffc170-d033-4a78-a5be-ee4c7f454139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22382, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "固执", "is_correct": false, "explanation": "“固执”指不肯改变主意，与“礼貌”的意思无关。"}, {"text": "无礼", "is_correct": true, "explanation": "“无礼”指没有礼貌、言行不恭敬，是“礼貌”的反义词。"}, {"text": "节俭", "is_correct": false, "explanation": "“节俭”指不浪费、会节约，与“礼貌”的意思无关。"}, {"text": "严肃", "is_correct": false, "explanation": "“严肃”指态度认真或庄重，与“礼貌”不构成反义关系。"}], "correct_answer": "无礼", "explanations": {"固执": "“固执”指不肯改变主意，与“礼貌”的意思无关。", "无礼": "“无礼”指没有礼貌、言行不恭敬，是“礼貌”的反义词。", "节俭": "“节俭”指不浪费、会节约，与“礼貌”的意思无关。", "严肃": "“严肃”指态度认真或庄重，与“礼貌”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ffc170-d033-4a78-a5be-ee4c7f454139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22382, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对别人有好的样子，让别人觉得舒服。", "primary_collocate": null, "pronunciation": "lǐ mào", "ipa": "li˨˩ mau˥˩", "syllable_count": 2, "sentences": [{"text": "服务员很有礼貌，客人都很满意。", "target_word": "礼貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对老人说话很礼貌。", "target_word": "礼貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友向客人问好，真有礼貌。", "target_word": "礼貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "迟到的时候要说“对不起”，这是礼貌。", "target_word": "礼貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你礼貌一点，别大声说话。", "target_word": "礼貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着说谢谢，非常有礼貌。", "target_word": "礼貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么有礼貌地打电话。", "target_word": "礼貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在别人家做客，要注意礼貌。", "target_word": "礼貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给我让座，我觉得他很礼貌。", "target_word": "礼貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对邻居要有礼貌，见面时打个招呼。", "target_word": "礼貌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "礼貌用语", "label": "复合词"}, {"form": "不礼貌", "label": "否定形式"}], "register": "中性", "sense_fingerprint": "礼貌：对人友好、有分寸，让别人觉得舒服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5846132b-121e-4712-a287-c75705189ab3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22382, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脾气", "is_correct": false, "explanation": "语义：“很有脾气”说的是性子，多含急躁或倔强，与“客人都很满意”矛盾。"}, {"text": "礼貌", "is_correct": true, "explanation": "“很有礼貌”说服务员对客人的态度好，与“客人都很满意”相符。"}, {"text": "力气", "is_correct": false, "explanation": "搭配：“力气”说体力，不用来评价服务员的态度。"}, {"text": "钱", "is_correct": false, "explanation": "语义：“很有钱”说的是财富，与服务态度无关。"}], "explanations": {"脾气": "语义：“很有脾气”说的是性子，多含急躁或倔强，与“客人都很满意”矛盾。", "礼貌": "“很有礼貌”说服务员对客人的态度好，与“客人都很满意”相符。", "力气": "搭配：“力气”说体力，不用来评价服务员的态度。", "钱": "语义：“很有钱”说的是财富，与服务态度无关。"}, "sentence_index": 0, "correct_answer": "礼貌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她主动礼貌座位，把位置让给了孕妇。", "explanation": "这里应该用〈礼让〉。“礼让座位”指主动把座位让出；“礼貌”是态度，不能作动词带宾语。"}, {"text": "开幕式的礼貌很隆重。", "explanation": "这里应该用〈礼仪〉。“礼仪”指隆重的仪式规范，可以说“很隆重”；“礼貌”是态度，不能形容仪式隆重。"}, {"text": "这位贵宾受到了高规格的礼貌。", "explanation": "这里应该用〈礼遇〉。“礼遇”指给予的优待和接待规格，可以说“高规格”；“礼貌”是待人的态度，不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ffc170-d033-4a78-a5be-ee4c7f454139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22382, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "礼物", "is_correct": false, "explanation": "语义：“礼物”是东西，不能说“有礼物地打电话”。"}, {"text": "礼貌", "is_correct": true, "explanation": "“有礼貌地打电话”说的是打电话的方式，与句意相符。"}, {"text": "名气", "is_correct": false, "explanation": "语义：“名气”说的是知名度，不能用来说明打电话的方式。"}, {"text": "力量", "is_correct": false, "explanation": "搭配：“力量”多用于言语或作品的作用，不用来说打电话的方式。"}], "explanations": {"礼物": "语义：“礼物”是东西，不能说“有礼物地打电话”。", "礼貌": "“有礼貌地打电话”说的是打电话的方式，与句意相符。", "名气": "语义：“名气”说的是知名度，不能用来说明打电话的方式。", "力量": "搭配：“力量”多用于言语或作品的作用，不用来说打电话的方式。"}, "sentence_index": 6, "correct_answer": "礼貌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的笑容里有一张礼貌，让人很放心。", "explanation": "这里应该用〈种〉。“张”用于纸张、桌子之类平面的东西，不能用来计量礼貌。"}, {"text": "他说话的样子带着一条礼貌，大家都愿意听。", "explanation": "这里应该用〈种〉。“条”用于细长的东西，不能用来计量礼貌。"}, {"text": "这位老师身上有一把礼貌，学生都很尊敬她。", "explanation": "这里应该用〈种〉。“把”用于有柄的器具，不能用来计量礼貌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ffc170-d033-4a78-a5be-ee4c7f454139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22382, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "服务员礼貌的向客人问好。", "corrected_sentence": "服务员礼貌地向客人问好。", "error_description": "修饰语用错。修饰动词“问好”的状语要用“地”，应说“礼貌地向客人问好”；“礼貌的”后接动词是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ffc170-d033-4a78-a5be-ee4c7f454139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22382, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她说话说地很礼貌。", "corrected_sentence": "她说话说得很礼貌。", "error_description": "补语标记用错。“很礼貌”作“说话”的补语，补语前的标记应用“得”，应说“说得很礼貌”；“说地很礼貌”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ffc170-d033-4a78-a5be-ee4c7f454139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
