INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22386, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "心里有某种感觉。", "primary_collocate": null, "pronunciation": "gǎn dào", "ipa": "kan˨˩˦ tau˥˩", "syllable_count": 2, "sentences": [{"text": "听到这个消息，我感到很高兴。", "target_word": "感到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她第一次坐飞机，感到有点儿紧张。", "target_word": "感到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走了一天路，我感到很累。", "target_word": "感到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对自己的工作感到满意。", "target_word": "感到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说我进步了，我感到非常开心。", "target_word": "感到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个人在国外，他常常感到孤单。", "target_word": "感到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到孩子们笑，妈妈感到很幸福。", "target_word": "感到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一进门就感到屋里很热。", "target_word": "感到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试以前，很多人都会感到害怕。", "target_word": "感到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对这个结果感到很吃惊。", "target_word": "感到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "感到了", "label": "体标（了）"}, {"form": "感到过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "动词，心里产生高兴、紧张、累等感觉，后面常接形容词或心理状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca85f957-df35-4d8f-af57-1db695739dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22386, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感到", "is_correct": true, "explanation": "“感到”后接形容词“很高兴”，表示心里产生的感受，句意通顺。"}, {"text": "看见", "is_correct": false, "explanation": "语义：“看见”指看到某物，不能表示心里的感受，与“很高兴”不搭。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，与句中表示心情的“很高兴”无关。"}, {"text": "发生", "is_correct": false, "explanation": "配价：“发生”是不及物动词，不能直接接形容词“很高兴”表示感受。"}], "explanations": {"感到": "“感到”后接形容词“很高兴”，表示心里产生的感受，句意通顺。", "看见": "语义：“看见”指看到某物，不能表示心里的感受，与“很高兴”不搭。", "吃": "语义：“吃”指进食，与句中表示心情的“很高兴”无关。", "发生": "配价：“发生”是不及物动词，不能直接接形容词“很高兴”表示感受。"}, "sentence_index": 0, "correct_answer": "感到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我感到了你寄来的信。", "explanation": "这里应该用〈收到〉。“感到”表示心里的感觉，不能用来表示接收信件，应说“收到”。"}, {"text": "我每天感到学生的作业。", "explanation": "这里应该用〈批改〉。“感到”表示心里的感觉，不能用来表示批阅作业，应说“批改”。"}, {"text": "他感到了一个数学公式。", "explanation": "这里应该用〈背〉。“感到”表示心里的感受，不能接公式表示记忆，应说“背”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22386, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "感到", "is_correct": true, "explanation": "“感到”后接形容词“很幸福”，表示心里的感受，句意通顺。"}, {"text": "听见", "is_correct": false, "explanation": "语义：“听见”表示听到声音，与“很幸福”这种心情不搭。"}, {"text": "卖", "is_correct": false, "explanation": "语义：“卖”是交易行为，用来表示心情，句意不通。"}, {"text": "打开", "is_correct": false, "explanation": "配价：“打开”是及物动词，后面要接宾语，不能直接接“很幸福”。"}], "explanations": {"感到": "“感到”后接形容词“很幸福”，表示心里的感受，句意通顺。", "听见": "语义：“听见”表示听到声音，与“很幸福”这种心情不搭。", "卖": "语义：“卖”是交易行为，用来表示心情，句意不通。", "打开": "配价：“打开”是及物动词，后面要接宾语，不能直接接“很幸福”。"}, "sentence_index": 6, "correct_answer": "感到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我感到了一杯咖啡。", "explanation": "这里应该用〈喝〉。“感到”表示心里的感觉，不能接饮品表示饮用，应说“喝”。"}, {"text": "老师感到了每个学生的名字。", "explanation": "这里应该用〈记住〉。“感到”表示心里的感受，不能接名字表示记忆，应说“记住”。"}, {"text": "我感到了窗外的那片云。", "explanation": "这里应该用〈看〉。“感到”表示心里的感觉，不能接景物表示看见，应说“看”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22386, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "看到比赛结果，我感到得很失望。", "corrected_sentence": "看到比赛结果，我感到很失望。", "error_description": "多出“得”：“感到”后直接接形容词作谓语，不能加“得”；应说“我感到很失望”，不能说“我感到得很失望”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22386, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "走进教室，我就感到得空气很闷。", "corrected_sentence": "走进教室，我就感到空气很闷。", "error_description": "多出“得”：“感到”后直接接宾语，不能加“得”；应说“感到空气很闷”，不能说“感到得空气很闷”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22392, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吃力", "is_correct": true, "explanation": "与“轻松”构成反义：吃力指做事费劲，与“不费力”相对。"}, {"text": "干净", "is_correct": false, "explanation": "与“轻松”无反义关系，它与“脏”相对。"}, {"text": "明亮", "is_correct": false, "explanation": "与“轻松”无反义关系，它与“昏暗”相对。"}, {"text": "仔细", "is_correct": false, "explanation": "与“轻松”无反义关系，它与“马虎”相对。"}], "correct_answer": "吃力", "explanations": {"吃力": "与“轻松”构成反义：吃力指做事费劲，与“不费力”相对。", "干净": "与“轻松”无反义关系，它与“脏”相对。", "明亮": "与“轻松”无反义关系，它与“昏暗”相对。", "仔细": "与“轻松”无反义关系，它与“马虎”相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22392, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吃力", "is_correct": true, "explanation": "与“轻松”构成反义：吃力指做事费劲，与“不费力”相对。"}, {"text": "复杂", "is_correct": false, "explanation": "与“轻松”无反义关系，它与“简单”相对。"}, {"text": "认真", "is_correct": false, "explanation": "与“轻松”无反义关系，它与“敷衍”相对。"}, {"text": "安静", "is_correct": false, "explanation": "与“轻松”无反义关系，它与“吵闹”相对。"}], "correct_answer": "吃力", "explanations": {"吃力": "与“轻松”构成反义：吃力指做事费劲，与“不费力”相对。", "复杂": "与“轻松”无反义关系，它与“简单”相对。", "认真": "与“轻松”无反义关系，它与“敷衍”相对。", "安静": "与“轻松”无反义关系，它与“吵闹”相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
